function _todayNumberTalkIndex() {
    const t = new Date();
    const dayOfYear = Math.floor((t - new Date(t.getFullYear(),0,0)) / 86400000);
    return dayOfYear % NUMBER_TALKS.length;
}
function _hasSecretPack(packId) {
    const p = activeProfile();
    return !!(p && p.unlockedSecrets && p.unlockedSecrets[packId]);
}
function renderNumberTalk() {
    const card  = document.getElementById('number-talk-card');
    const titleEl = document.getElementById('nt-title');
    const promptEl  = document.getElementById('nt-prompt');
    const stratsEl  = document.getElementById('nt-strategies');
    if (!card || !promptEl) return;
    // Só visível se o pack Mat+ estiver ativo
    if (!_hasSecretPack('mat-plus')) { card.style.display = 'none'; return; }
    card.style.display = '';
    const nt = NUMBER_TALKS[_todayNumberTalkIndex()];
    if (titleEl) titleEl.textContent = `Number Talk de hoje · ${nt.n}`;
    promptEl.innerHTML = nt.q;
    stratsEl.innerHTML = '<strong>Algumas estratégias possíveis</strong><br>' +
        nt.strats.map(s => `<div class="nt-strat-row">• ${s}</div>`).join('');
}
function toggleNumberTalk() {
    const card = document.getElementById('number-talk-card');
    const body = document.getElementById('nt-body');
    if (!card || !body) return;
    const open = body.style.display !== 'none';
    body.style.display = open ? 'none' : 'block';
    card.classList.toggle('open', !open);
}
window.toggleNumberTalk = toggleNumberTalk;

// ============================================================
// HEGGERTY-INSPIRED PHONOLOGICAL ROUTINE — 7 dias por semana
// Cada dia foca componentes diferentes (rima/sílaba/fonema)
// Fonte: Heggerty Phonemic Awareness Curriculum (adaptado PT)
// ============================================================
const HEGGERTY_DAYS = [
    // Domingo (0)
    [
        { tag: 'Rima', text: 'Adulto diz <strong>BOLA</strong> · GATO · MOLA · FOLA (palavra-fingida!) · OLHO. Repete só as que rimam com BOLA.' },
        { tag: 'Sílaba', text: '<strong>BORBOLETA</strong> — bate palmas em cada sílaba (4: BOR-BO-LE-TA).' },
        { tag: 'Primeiro som', text: 'Qual é o primeiro som de <strong>SAPO</strong>? (resposta: /s/)' },
        { tag: 'Juntar', text: 'Junta: /m/ + /a/ + /r/ — que palavra é? (MAR)' },
    ],
    // Segunda (1)
    [
        { tag: 'Rima', text: 'Diz 3 palavras que rimem com <strong>PATO</strong>. (ex.: gato, rato, mato)' },
        { tag: 'Sílaba', text: 'Tira a primeira sílaba de <strong>CAMISA</strong>. (MISA)' },
        { tag: 'Último som', text: 'Qual é o último som de <strong>FLOR</strong>? (/r/)' },
        { tag: 'Trocar', text: 'Em <strong>MALA</strong>, troca /m/ por /b/. Que palavra fica? (BALA)' },
    ],
    // Terça (2)
    [
        { tag: 'Rima', text: 'Diz uma palavra que rime com <strong>CHÃO</strong>. (mão, pão, são, não)' },
        { tag: 'Sílaba', text: 'Junta as sílabas <strong>CA-VA-LO</strong>. (CAVALO)' },
        { tag: 'Sons', text: 'Quantos sons tem <strong>SOL</strong>? (3: /s/ /o/ /l/)' },
        { tag: 'Tirar', text: 'Em <strong>BARCO</strong>, tira o som /b/. Que palavra fica? (ARCO)' },
    ],
    // Quarta (3)
    [
        { tag: 'Onset-rime', text: '<strong>PORTA</strong> começa com /p/ e o resto é /orta/. E <strong>CASA</strong>? (/k/ + /asa/)' },
        { tag: 'Sílaba', text: 'Acrescenta <strong>BA</strong> antes de <strong>NANA</strong>. (BANANA)' },
        { tag: 'Som médio', text: 'Qual é o som do meio em <strong>MAR</strong>? (/a/)' },
        { tag: 'Substituir', text: 'Em <strong>SOPA</strong>, troca /s/ por /c/. Que palavra fica? (COPA)' },
    ],
    // Quinta (4)
    [
        { tag: 'Rima', text: 'Estas palavras rimam? <strong>FOLHA · BOLHA</strong>. (sim) E <strong>FOLHA · MESA</strong>? (não)' },
        { tag: 'Sílaba', text: 'Quantas sílabas tem <strong>CARACOL</strong>? (3: CA-RA-COL)' },
        { tag: 'Segmentar', text: 'Diz os sons de <strong>PÉ</strong>. (/p/ /é/ — 2 sons)' },
        { tag: 'Famílias', text: 'BO, RO, MO, FO, JO — qual é o som comum? (/o/)' },
    ],
    // Sexta (5)
    [
        { tag: 'Rima', text: 'Inventa uma palavra que rime com <strong>SOL</strong>. (pode ser palavra-fingida!)' },
        { tag: 'Sílaba', text: 'Tira a sílaba do fim em <strong>MENINO</strong>. (MENI)' },
        { tag: 'Juntar sons', text: 'Junta /p/ + /é/. (PÉ) Junta /m/ + /ã/ + /o/. (MÃO)' },
        { tag: 'Inversão', text: 'Diz <strong>OPA</strong> ao contrário. (APO)' },
    ],
    // Sábado (6)
    [
        { tag: 'Mistura', text: 'Estas rimam? <strong>VACA · FACA</strong>. (sim) · <strong>RATO · CASA</strong>. (não)' },
        { tag: 'Sílaba', text: 'Bate palmas em <strong>HIPOPÓTAMO</strong>. (5: HI-PO-PÓ-TA-MO)' },
        { tag: 'Pares mínimos', text: 'BOLA e MOLA — que som mudou? (/b/ → /m/)' },
        { tag: 'Trava-línguas', text: 'Diz devagar: <strong>"O rato roeu a rolha da garrafa do rei da Rússia"</strong>.' },
    ],
];
function _todayHeggertyDay() { return new Date().getDay(); }
function renderHeggerty() {
    const card = document.getElementById('heggerty-card');
    const promptsEl = document.getElementById('hg-prompts');
    const titleEl = document.getElementById('hg-title');
    if (!card || !promptsEl) return;
    // Só visível se o pack Som+ estiver ativo
    if (!_hasSecretPack('som-plus')) { card.style.display = 'none'; return; }
    card.style.display = '';
    const dayNames = ['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];
    const day = _todayHeggertyDay();
    if (titleEl) titleEl.textContent = `Sons de ${dayNames[day]}`;
    const items = HEGGERTY_DAYS[day] || HEGGERTY_DAYS[0];
    promptsEl.innerHTML = items.map(p =>
        `<div class="hg-step"><span class="hg-step-label">${p.tag}</span>${p.text}</div>`
    ).join('');
}
function toggleHeggerty() {
    const card = document.getElementById('heggerty-card');
    const body = document.getElementById('hg-body');
    if (!card || !body) return;
    const open = body.style.display !== 'none';
    body.style.display = open ? 'none' : 'block';
    card.classList.toggle('open', !open);
}
window.toggleHeggerty = toggleHeggerty;

// ============================================================
// MATH JOURNAL — prompt semanal (segunda-feira)
// Convida a criança a refletir/desenhar matemática num caderno
// ============================================================
const MATH_JOURNAL_PROMPTS = [
    'Desenha o número <strong>15</strong> de 3 formas diferentes (ex.: dedos, dezenas+unidades, dinheiro).',
    'Onde viste matemática esta semana? Conta uma história curta.',
    'Inventa um problema com <strong>"comprei 3 e ganhei 2"</strong> e desenha-o.',
    'Qual é o teu número favorito? Porquê? Desenha-o em 3 formas.',
    'Faz um quadro de marcas (||| ||) para contar uma coleção (legos, cromos).',
    'Desenha duas formas geométricas que vês na cozinha.',
    'Conta passos de casa até à porta. Estima primeiro, depois conta!',
    'Quantos olhos há na tua família? E pés? E dedos das mãos?',
    'Que horas são quando acordas? E quando vais dormir? Quantas horas dormes?',
    'Desenha uma <strong>linha numérica</strong> de 0 a 20 e marca o teu número da sorte.',
];
function _thisWeekJournalIndex() {
    const t = new Date();
    const yearStart = new Date(t.getFullYear(), 0, 1);
    const weeks = Math.floor((t - yearStart) / (7 * 86400000));
    return weeks % MATH_JOURNAL_PROMPTS.length;
}
// Chave da semana do diário: a segunda-feira LOCAL desta semana (uma só âncora)
function _mjWeekKey() { const d = new Date(); d.setHours(0, 0, 0, 0); d.setDate(d.getDate() - ((d.getDay() + 6) % 7)); return 'mj-' + _localDayKey(d); }
function renderMathJournal() {
    const card = document.getElementById('math-journal-card');
    const promptEl = document.getElementById('mj-prompt');
    if (!card || !promptEl) return;
    // Só visível se o pack Mat+ estiver ativo
    if (!_hasSecretPack('mat-plus')) { card.style.display = 'none'; return; }
    // Só mostra à segunda-feira (dia 1) ou se já foi aberto esta semana
    const day = new Date().getDay();
    const isMonday = day === 1;
    const weekKey = _mjWeekKey();
    const wasOpened = state.mathJournalOpened === weekKey;
    if (!isMonday && !wasOpened) { card.style.display = 'none'; return; }
    card.style.display = 'block';
    promptEl.innerHTML = MATH_JOURNAL_PROMPTS[_thisWeekJournalIndex()];
}
function toggleMathJournal() {
    const card = document.getElementById('math-journal-card');
    const body = document.getElementById('mj-body');
    if (!card || !body) return;
    const open = body.style.display !== 'none';
    body.style.display = open ? 'none' : 'block';
    card.classList.toggle('open', !open);
    if (!open) {
        state.mathJournalOpened = _mjWeekKey();
        saveState();
    }
}
window.toggleMathJournal = toggleMathJournal;

function renderNextTestCard() {
    const card = document.getElementById('next-test-card');
    const today = todayStr();
    const upcoming = state.tests
        .filter(t => !t.done && t.date >= today)
        .sort((a, b) => a.date.localeCompare(b.date));
    if (upcoming.length === 0) { card.style.display = 'none'; return; }
    const t = upcoming[0];
    const days = daysBetween(today, t.date);
    const sub = SUBJECTS[t.subject];
    document.getElementById('next-test-title').textContent = `Teste de ${sub?.name || t.subject}`;
    document.getElementById('next-test-sub').textContent = days === 0 ? 'É hoje!' : days === 1 ? 'É amanhã' : `Faltam ${days} dias`;
    document.getElementById('next-test-days').textContent = days;
    card.classList.remove('urgent', 'soon');
    if (days <= 2) card.classList.add('urgent');
    else if (days <= 5) card.classList.add('soon');
    card.style.display = 'flex';
}

function renderNextRewardCard() {
    const card = document.getElementById('next-reward-card');
    const next = (state.rewards || []).filter(r => !r.claimed).sort((a, b) => a.cost - b.cost).find(r => r.cost > state.xp);
    if (!next) { card.style.display = 'none'; return; }
    const pct = Math.min(100, Math.round(state.xp / next.cost * 100));
    document.getElementById('next-reward-name').textContent = `Próximo prémio: ${next.name}`;
    document.getElementById('next-reward-fill').style.width = pct + '%';
    document.getElementById('next-reward-meta').textContent = `${state.xp} / ${next.cost} XP (faltam ${next.cost - state.xp})`;
    card.style.display = 'flex';
}

// ========== SUBJECTS TAB ==========
function renderSubjects() {
    const grid = document.getElementById('subjects-grid');
    const seen = state.exerciseSeen || {};
    grid.innerHTML = Object.entries(SUBJECTS).map(([key, sub]) => {
        const stats = state.subjects[key] || { answered: 0, correct: 0, xp: 0 };
        const accPct = stats.answered > 0 ? Math.round(stats.correct / stats.answered * 100) : 0;
        const active = activeTopicsFor(key);
        const maxEx = state.maxExercises || [];
        // Pool ativo (apenas tópicos ativos)
        const activePool = [
            ...EXERCISES.filter(e => e.s === key && active.has(e.t)),
            ...maxEx.filter(e => e.s === key && active.has(e.t))
        ];
        const totalActive = activePool.length;
        // Quantos do pool ativo já foram respondidos
        const answeredInPool = activePool.filter(e => seen[e.id]).length;
        // Barra: % do banco ativo já respondido (= "evolução" verdadeira)
        const barPct = totalActive > 0 ? Math.round((answeredInPool / totalActive) * 100) : 0;
        const shadow = (sub.color || '#f472b6') + '40'; // 25% opacidade
        return `
            <div class="subject-card" role="button" tabindex="0" onclick="openSubjectDetail('${key}')" style="--sub-color:${sub.color};--sub-shadow:${shadow}">
                <div class="subject-card-icon" role="button" tabindex="0" style="background:linear-gradient(135deg, ${sub.color}, ${sub.color}dd)"><i class="fas ${sub.icon}"></i></div>
                <h3>${sub.name}</h3>
                <div class="subject-card-meta" role="button" tabindex="0">
                    <div>${answeredInPool}/${totalActive} respondidas</div>
                    ${stats.answered > 0 ? `<div style="font-size:0.7rem;color:var(--text-light);margin-top:2px">${accPct}% acerto · ${stats.xp} XP</div>` : ''}
                </div>
                <div class="subject-card-bar" role="button" tabindex="0" title="${barPct}% do banco">
                    <div class="subject-card-bar-fill" role="button" tabindex="0" style="width:${barPct}%;background:linear-gradient(90deg, ${sub.color}, ${sub.color}cc)"></div>
                </div>
            </div>
        `;
    }).join('');
}

// ========== SUBJECT DETAIL (modal fullscreen) ==========
function openSubjectDetail(key, opts) {
    opts = opts || {};
    // Disciplina english_pm tem modo Curso dedicado (caminho linear estilo
    // path com 14 licoes e progressao). Nao interfere com outras disciplinas.
    if ((key === 'english_pm' && window.COURSE_ENGLISH_PM) ||
        (key === 'english_ge' && window.COURSE_ENGLISH_GE)) {
        openCoursePath(key);
        return;
    }
    // Leitura: biblioteca de textos — cada um abre o Professor de Leitura.
    if (key === 'leitura') {
        openLeituraLibrary();
        return;
    }
    // Detetive Mental: hub de jogos dedicado (em vez do ecrã genérico).
    // opts.generic força o ecrã completo (slider/IA/reiniciar) via "mais opções".
    if (key === 'detetive' && !opts.generic) {
        openDetetiveHub();
        return;
    }
    // Primeira vez em Mat+? Oferece o diagnóstico inicial
    if (key === 'mat_plus' && !state.matPlusDiag && !state.matPlusDiagSkipped) {
        showMatPlusDiagnosticIntro();
        return;
    }
    // Mat+: hub por áreas (Números / Contas / Frações & Problemas) — ecrã
    // amigável em vez do genérico. Opções avançadas via "⋯" (opts.generic).
    if (key === 'mat_plus' && !opts.generic) {
        openMatPlusHub();
        return;
    }
    currentSubjectView = key;
    const sub = SUBJECTS[key];
    const topics = CURRICULUM[key] || [];
    const toIndex = state.progress[key]?.toIndex ?? topics.length;
    const stats = state.subjects[key] || { answered: 0, correct: 0, xp: 0 };
    // Cálculo do banco total e perguntas respondidas/restantes nesta disciplina
    const seen = state.exerciseSeen || {};
    const allSubjectEx = [
        ...EXERCISES.filter(e => e.s === key),
        ...(state.maxExercises || []).filter(e => e.s === key)
    ];
    const totalEx = allSubjectEx.length;
    const seenEx = allSubjectEx.filter(e => seen[e.id]).length;
    const remainingEx = totalEx - seenEx;
    const seenPct = totalEx > 0 ? Math.round((seenEx / totalEx) * 100) : 0;
    const accPct = stats.answered > 0 ? Math.round((stats.correct / stats.answered) * 100) : 0;

    // Cartão do PROFESSOR da disciplina (especialista PT-PT; Inglês mantém-se em EN).
    const _profSD = (typeof activeProfile === 'function' && activeProfile()) || {};
    const _studentSD = _profSD.name || '';
    const _isEnSD = (key === 'ingles' || key === 'english_pm' || key === 'english_ge');
    const _tutorTitleSD = _isEnSD ? 'Falar com o Professor' : `Professor(a) de ${escapeHtml(sub.name)}`;
    const _tutorSubSD = _isEnSD
        ? 'Conversa livre · corrige-te e faz perguntas'
        : (_studentSD ? `Tira dúvidas e treina ${escapeHtml(sub.name)} contigo, ${escapeHtml(_studentSD)}` : `Tira dúvidas e treina ${escapeHtml(sub.name)} contigo`);

    const html = `
        <div class="fullscreen" id="subject-detail-screen">
            <div class="exercise-header">
                <button class="icon-btn" aria-label="Voltar" title="Voltar" onclick="closeSubjectDetail()"><i class="fas fa-arrow-left" aria-hidden="true"></i></button>
                <div style="flex:1;font-weight:700;display:flex;align-items:center;gap:8px">
                    <span style="width:32px;height:32px;border-radius:8px;background:${sub.color};color:#fff;display:inline-flex;align-items:center;justify-content:center"><i class="fas ${sub.icon}"></i></span>
                    ${sub.fullName || sub.name}
                </div>
            </div>
            <div class="exercise-body">
                <div class="tutor-card" data-tutor-subject="${escapeHtml(key)}" data-tutor-name="${escapeHtml(sub.name)}" onclick="openTutorFromSubjectCard(this)" style="margin:0 0 14px">
                  <div class="tutor-card-icon"><i class="fas fa-chalkboard-user"></i></div>
                  <div class="tutor-card-text">
                    <div class="tutor-card-title">${_tutorTitleSD}</div>
                    <div class="tutor-card-sub">${_tutorSubSD}</div>
                  </div>
                  <i class="fas fa-microphone tutor-card-mic"></i>
                </div>
                <div style="background:#fff;padding:14px;border-radius:14px;box-shadow:var(--shadow);margin-bottom:12px">
                    <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:12px">
                        <div>
                            <div style="font-size:0.72rem;color:var(--text-light);font-weight:600">RESPOSTAS CERTAS</div>
                            <div style="font-size:1.3rem;font-weight:800;color:${sub.color}">${stats.correct}/${stats.answered}${stats.answered > 0 ? ` <span style="font-size:0.85rem;color:var(--text-light);font-weight:700">(${accPct}%)</span>` : ''}</div>
                            <div style="font-size:0.78rem;color:#f59e0b;font-weight:700;margin-top:2px">⭐ ${stats.xp} XP</div>
                        </div>
                        <div>
                            <div style="font-size:0.72rem;color:var(--text-light);font-weight:600">EXERCÍCIOS DO BANCO</div>
                            <div style="font-size:1.3rem;font-weight:800;color:${sub.color}">${seenEx}/${totalEx}</div>
                            <div style="font-size:0.78rem;color:var(--text-light);font-weight:600;margin-top:2px">${remainingEx > 0 ? `🆕 ${remainingEx} por responder` : '🎉 Banco completo!'}</div>
                        </div>
                    </div>
                    <div style="height:6px;background:#f3f4f6;border-radius:999px;overflow:hidden">
                        <div style="height:100%;width:${seenPct}%;background:linear-gradient(90deg,${sub.color},${sub.color}cc);border-radius:999px;transition:width 0.4s"></div>
                    </div>
                    <div style="font-size:0.7rem;color:var(--text-light);text-align:right;margin-top:3px">${seenPct}% do banco visto</div>
                </div>

                ${(key === 'mat_plus' && state.matPlusDiag) ? `
                <div style="background:linear-gradient(135deg,#f0fdfa,#ccfbf1);border:1.5px solid #14b8a6;padding:12px 14px;border-radius:14px;margin-bottom:12px">
                    <div style="display:flex;align-items:center;gap:10px;margin-bottom:6px">
                        <span style="font-size:1.4rem">🎯</span>
                        <div style="flex:1">
                            <div style="font-size:0.72rem;color:#0f766e;font-weight:700;text-transform:uppercase;letter-spacing:0.05em">Último diagnóstico</div>
                            <div style="font-weight:800;color:#0f766e;font-size:1rem">${state.matPlusDiag.score}/${state.matPlusDiag.total} · ${new Date(state.matPlusDiag.date).toLocaleDateString('pt-PT', { day:'2-digit', month:'2-digit' })}</div>
                        </div>
                        <button class="btn btn-secondary" style="font-size:0.78rem;padding:6px 10px" onclick="redoMatDiagnostic()"><i class="fas fa-rotate"></i> Refazer</button>
                    </div>
                    ${(state.matPlusDiag.recommended || []).length > 0 ? `
                    <div style="font-size:0.78rem;color:#0f766e;margin-top:6px">
                        <strong>Recomendado:</strong> ${state.matPlusDiag.recommended.slice(0,3).map(t => escapeHtml(t)).join(' · ')}
                    </div>` : ''}
                </div>
                ` : (key === 'mat_plus' && !state.matPlusDiag) ? `
                <div style="background:#f0fdfa;border:1.5px dashed #14b8a6;padding:12px 14px;border-radius:14px;margin-bottom:12px;display:flex;align-items:center;gap:10px">
                    <span style="font-size:1.4rem">🎯</span>
                    <div style="flex:1;font-size:0.85rem;color:#0f766e">Ainda não fizeste o diagnóstico inicial.</div>
                    <button class="btn btn-primary-solid" style="font-size:0.78rem;padding:6px 12px;background:#14b8a6" onclick="redoMatDiagnostic()">Fazer agora</button>
                </div>
                ` : ''}

                ${key === 'detetive' ? _detetiveQuickChips() : ''}
                ${key === 'escrita' ? `<button class="det-surprise paper-cta write-cta" style="margin-bottom:12px" onclick="openWriteSheet()">✍️ Ficha de Escrita — escreve um texto à mão e mostra à professora!</button>` : ''}

                <!-- Criar duelo — visual identico a 'Comecar treino' (rosa primario) -->
                <button class="btn btn-primary-solid btn-block" style="margin-bottom:12px" onclick="pickDuelRecipientsAndCreate('${key}')">
                    <i class="fas fa-fist-raised"></i> Criar duelo com amigos
                </button>

                <div style="background:#fff;padding:14px;border-radius:14px;box-shadow:var(--shadow);margin-bottom:12px">
                    <label style="display:block;font-weight:700;margin-bottom:6px">Até onde já estudaste?</label>
                    <p class="muted" style="margin-bottom:10px">Selecciona o último tópico que deste. Só aparecem exercícios até esse ponto.</p>
                    <input type="range" id="progress-slider" min="0" max="${topics.length}" value="${toIndex}" style="width:100%" oninput="onProgressSlider(this.value)">
                    <div style="display:flex;justify-content:space-between;font-size:0.72rem;color:var(--text-light);margin-top:4px">
                        <span>0</span><span id="progress-current">${toIndex}</span><span>${topics.length}</span>
                    </div>
                </div>

                <!-- Botão "começar treino" ANTES da lista — acesso rápido sem scroll -->
                <button class="btn btn-primary-solid btn-block" style="margin-bottom:14px" onclick="startSubjectSession('${key}')">
                    <i class="fas fa-play"></i> Começar treino (todos os tópicos ativos)
                </button>

                <div class="section-title" style="margin-top:8px;display:flex;align-items:center;gap:8px;flex-wrap:wrap">
                    <i class="fas fa-list-ol"></i> <span style="flex:1">Tópicos</span>
                    <button class="btn btn-secondary" style="font-size:0.72rem;padding:6px 10px" onclick="selectAllTopics()"><i class="fas fa-check-double"></i> Todos</button>
                    <button class="btn btn-secondary" style="font-size:0.72rem;padding:6px 10px" onclick="clearTopicSelection()"><i class="fas fa-xmark"></i> Limpar</button>
                </div>
                <div class="ep-topic-controls">
                    <button type="button" class="ep-topic-focus-pill" id="ep-topic-focus-pill" onclick="toggleTopicFocus()"></button>
                </div>
                <div id="topic-list"></div>

                <!-- ===== BLOCO MAX ===== -->
                <div style="margin-top:16px;background:linear-gradient(135deg,#4c1d95,#f472b6);border-radius:16px;padding:14px;box-shadow:0 4px 16px rgba(109,40,217,0.35)">
                    <div style="color:#fff;font-weight:800;font-size:1rem;margin-bottom:4px"><i class="fas fa-wand-magic-sparkles"></i> MAX — Exercícios com IA</div>
                    <div style="color:#fbcfe8;font-size:0.78rem;margin-bottom:12px">Selecciona tópicos acima ou gera para todos</div>

                    <div id="max-topic-sel-bar" style="display:none;background:rgba(255,255,255,0.12);border-radius:10px;padding:10px;margin-bottom:10px">
                        <div style="color:#e9d5ff;font-size:0.78rem;font-weight:700;margin-bottom:8px"><i class="fas fa-check-square"></i> <span id="max-sel-count">0</span> tópico(s) selecionado(s)</div>
                        <button class="btn btn-block" style="margin-bottom:6px;background:#fff;color:#f472b6;border-radius:10px;padding:10px;font-weight:700;font-size:0.88rem" onclick="startMaxForSelected('${key}', false)">
                            <i class="fas fa-wand-magic-sparkles"></i> Gerar exercícios MAX
                        </button>
                        <button class="btn btn-block" style="margin-bottom:6px;background:#fbbf24;color:#78350f;border-radius:10px;padding:10px;font-weight:700;font-size:0.88rem" onclick="startMaxForSelected('${key}', true)">
                            <i class="fas fa-graduation-cap"></i> Preparação para teste
                        </button>
                    </div>

                    <button class="btn btn-block" style="background:rgba(255,255,255,0.18);color:#fff;border-radius:10px;padding:10px;font-weight:600;font-size:0.88rem;margin-bottom:6px" onclick="startMaxSession('${key}')">
                        <i class="fas fa-shuffle"></i> Treino MAX (todos os tópicos ativos)
                    </button>
                    <button class="btn btn-block" style="background:rgba(255,255,255,0.1);color:#fbcfe8;border-radius:10px;padding:8px;font-size:0.78rem" onclick="startMaxSession('${key}', {forceNew:true})">
                        <i class="fas fa-rotate"></i> Forçar novos exercícios (consome API)
                    </button>
                </div>

                <!-- Reiniciar progresso desta disciplina -->
                <div style="margin-top:20px;padding:14px;background:#fef2f2;border:1.5px dashed #fecaca;border-radius:12px;margin-bottom:80px">
                    <div style="font-size:0.82rem;color:#991b1b;margin-bottom:8px;line-height:1.4">
                        <i class="fas fa-triangle-exclamation"></i> Apaga respostas, acertos, IA e progresso <strong>só desta disciplina</strong>. Mantém o resto.
                    </div>
                    <button class="btn btn-block" style="background:#fff;color:#dc2626;border:1.5px solid #fecaca;border-radius:10px;padding:10px;font-weight:700;font-size:0.88rem" onclick="resetSubject('${key}')">
                        <i class="fas fa-rotate-left"></i> Reiniciar "${(sub.name || key).replace(/'/g, "\\'")}"
                    </button>
                </div>
            </div>
            <!-- Sticky action bar — só aparece com tópicos selecionados -->
            <div id="topic-sel-actions" style="display:none;position:sticky;bottom:0;left:0;right:0;background:#fff;border-top:1.5px solid #e5e7eb;padding:12px 16px calc(12px + env(safe-area-inset-bottom, 0px));box-shadow:0 -4px 16px rgba(0,0,0,0.08);z-index:20">
                <div style="font-size:0.78rem;font-weight:700;color:#db2777;margin-bottom:6px;text-align:center"><i class="fas fa-check-square"></i> <span id="sel-count">0</span> tópico(s) selecionado(s)</div>
                <button class="btn btn-primary-solid btn-block" onclick="startSubjectSession('${key}', { useSelection: true })">
                    <i class="fas fa-play"></i> Treinar tópicos selecionados
                </button>
            </div>
        </div>
    `;
    const container = document.createElement('div');
    container.id = 'subject-detail-container';
    container.innerHTML = html;
    document.body.appendChild(container);
    renderTopicList();
}

// Chips de escolha rápida de jogo para o Detetive Mental — a criança toca
// e joga JÁ esse tipo (ex.: Sudoku), sem depender da progressão. Cada tópico
// do Detetive é um tipo de jogo. Mostra quantos exercícios existem por tipo.
function _detetiveQuickChips() {
    const meta = [
        { t: 'Sudoku & Kakuro',      emoji: '🔢', label: 'Sudoku' },
        { t: 'Charadas matemáticas', emoji: '🧮', label: 'Charadas' },
        { t: 'Histórias-mistério',   emoji: '🕵️', label: 'Mistérios' },
        { t: 'Padrões e sequências', emoji: '🧩', label: 'Padrões' },
        { t: 'Lógica pura',          emoji: '🧠', label: 'Lógica' }
    ];
    const pool = [...(window.EXERCISES || []), ...(state.maxExercises || [])].filter(e => e.s === 'detetive');
    const chips = meta.map(m => {
        const n = pool.filter(e => e.t === m.t).length;
        if (!n) return '';
        return `<button class="det-chip" onclick="startSubjectSession('detetive', { topic: '${m.t.replace(/'/g, "\\'")}', bypassSeenCheck: true })">
            <span class="det-chip-emoji">${m.emoji}</span>
            <span class="det-chip-label">${m.label}</span>
            <span class="det-chip-count">${n}</span>
        </button>`;
    }).join('');
    return `
        <div style="background:#fff;padding:14px;border-radius:14px;box-shadow:var(--shadow);margin-bottom:12px">
            <div style="font-weight:800;font-size:0.95rem;margin-bottom:2px">🎮 Escolhe um jogo</div>
            <div style="font-size:0.76rem;color:var(--text-light);margin-bottom:10px">Toca e joga já esse tipo de desafio</div>
            <div class="det-chips">${chips}</div>
        </div>`;
}
window._detetiveQuickChips = _detetiveQuickChips;

let selectedTopicsForMax = new Set();

function _currentTopicFocus() {
    const f = state && state.topicFocus;
    return f === 'all' ? 'all' : 'active';
}
function toggleTopicFocus() {
    state.topicFocus = _currentTopicFocus() === 'active' ? 'all' : 'active';
    saveState();
    renderTopicList();
}
window.toggleTopicFocus = toggleTopicFocus;

function _updateTopicFocusPill() {
    const pill = document.getElementById('ep-topic-focus-pill');
    if (!pill) return;
    const key = currentSubjectView;
    const total = (CURRICULUM[key] || []).length;
    const activeN = activeTopicsFor(key).size;
    const focus = _currentTopicFocus();
    pill.classList.toggle('is-on', focus === 'active');
    pill.innerHTML = focus === 'active'
        ? `<i class="fas fa-bullseye"></i> Só ativos · ${activeN}`
        : `<i class="fas fa-layer-group"></i> Todos · ${total}`;
}

function renderTopicList() {
    const key = currentSubjectView;
    const allTopics = CURRICULUM[key] || [];
    // 'active' agora vem do state persistente (state.activeTopics) — checkbox
    // marca/desmarca um tópico para entrar no 'Começar treino' por defeito.
    const active = activeTopicsFor(key);
    // Mantém selectedTopicsForMax em sync com active topics (para a MAX bar)
    selectedTopicsForMax = new Set(active);
    _updateTopicFocusPill();
    // Filtro "Só ativos" — quando ligado e há tópicos ativos, mostra só esses
    const focus = _currentTopicFocus();
    const useFilter = focus === 'active' && active.size > 0;
    const visibleTopics = useFilter ? allTopics.filter(t => active.has(t)) : allTopics;
    const origIndex = new Map(allTopics.map((t, i) => [t, i]));
    const container = document.getElementById('topic-list');
    if (!container) return;
    const seen = state.exerciseSeen || {};
    const subColor = SUBJECTS[key]?.color || '#f472b6';
    // Tópicos recomendados pelo diagnóstico Mat+ (destacar)
    const recommendedSet = (key === 'mat_plus' && state.matPlusDiag && Array.isArray(state.matPlusDiag.recommended))
        ? new Set(state.matPlusDiag.recommended)
        : new Set();
    // Testes futuros (nao feitos) desta disciplina — para sinalizar topicos que saem em teste
    const testsForSubject = (state.tests || []).filter(t =>
        t.subject === key && !t.done && Array.isArray(t.topics) && t.topics.length > 0
    ).sort((a, b) => a.date.localeCompare(b.date));
    // Map topic -> teste mais proximo
    const topicToTest = {};
    for (const test of testsForSubject) {
        for (const tp of test.topics) {
            if (!topicToTest[tp]) topicToTest[tp] = test;
        }
    }
    const hiddenN = allTopics.length - visibleTopics.length;
    // Banner de testes proximos (se houver topicos em teste)
    let testBanner = '';
    if (testsForSubject.length > 0) {
        const topicsInTests = new Set();
        for (const test of testsForSubject) for (const tp of test.topics) topicsInTests.add(tp);
        const nextTest = testsForSubject[0];
        const [yyyy, mm, dd] = nextTest.date.split('-');
        const dateStr = `${dd}/${mm}`;
        const tCount = topicsInTests.size;
        testBanner = `<div style="background:linear-gradient(135deg,#fef3c7,#fde68a);border:1.5px solid #fcd34d;border-radius:10px;padding:8px 12px;margin-bottom:8px;font-size:0.82rem;color:#78350f;display:flex;align-items:center;gap:8px"><span style="font-size:1rem">📝</span><span style="flex:1"><strong>${tCount}</strong> ${tCount===1?'tópico sai':'tópicos saem'} no teste de ${dateStr}</span></div>`;
    } else if (activeProfile()?.year === 2 && ['matematica','portugues','estudo_meio','mat_plus'].includes(key)) {
        // Sugerir criar os testes do 3.o periodo se ainda nao houver nenhum
        testBanner = `<div style="background:linear-gradient(135deg,#dbeafe,#bfdbfe);border:1.5px solid #93c5fd;border-radius:10px;padding:10px 12px;margin-bottom:8px;font-size:0.82rem;color:#1e3a8a;display:flex;align-items:center;gap:10px"><span style="font-size:1.2rem">📅</span><div style="flex:1"><div style="font-weight:800">Ainda não tens testes deste período</div><div style="font-size:0.72rem;margin-top:2px">Cria os 3 testes do 3.º período (Mat 3/6 · Pt 11/6 · EM 16/6) com tópicos já marcados</div></div><button class="btn" style="background:#2563eb;color:#fff;border:none;padding:7px 12px;font-size:0.74rem;font-weight:800;border-radius:8px;flex-shrink:0" onclick="event.stopPropagation();setupEduarda3rdPeriod()">Criar</button></div>`;
    } else if (activeProfile()?.year === 5 && key === 'ingles') {
        // Sugerir criar teste de Ingles 5.o ano (orientadores da professora)
        testBanner = `<div style="background:linear-gradient(135deg,#dbeafe,#bfdbfe);border:1.5px solid #93c5fd;border-radius:10px;padding:10px 12px;margin-bottom:8px;font-size:0.82rem;color:#1e3a8a;display:flex;align-items:center;gap:10px"><span style="font-size:1.2rem">📅</span><div style="flex:1"><div style="font-weight:800">Ainda não tens teste de Inglês</div><div style="font-size:0.72rem;margin-top:2px">Cria teste com orientadores da professora (horas, rotinas, profissões, present simple, prepositions of time)</div></div><button class="btn" style="background:#2563eb;color:#fff;border:none;padding:7px 12px;font-size:0.74rem;font-weight:800;border-radius:8px;flex-shrink:0" onclick="event.stopPropagation();setupCarolinaIngles5()">Criar</button></div>`;
    }
    const banner = (useFilter && hiddenN > 0)
        ? `<div class="ep-topic-banner"><i class="fas fa-bullseye"></i> ${visibleTopics.length} de ${allTopics.length} tópicos ativos. <button type="button" onclick="toggleTopicFocus()" class="ep-topic-banner-link">Ver todos</button></div>`
        : (focus === 'active' && active.size === 0 && allTopics.length > 0)
            ? `<div class="ep-topic-banner"><i class="fas fa-circle-info"></i> Sem tópicos ativos. Ativa abaixo o que ela está a dar agora.</div>`
            : '';
    container.innerHTML = testBanner + banner + visibleTopics.map((t, vi) => {
        const i = origIndex.get(t) ?? vi;
        const isActive = active.has(t);
        const isRecommended = recommendedSet.has(t);
        // Pool deste tópico (estático + IA)
        const pool = [
            ...EXERCISES.filter(e => e.s === key && e.t === t),
            ...(state.maxExercises || []).filter(e => e.s === key && e.t === t)
        ];
        const count = pool.length;
        // Quantos respondidos correctamente / errados
        const seenIds = pool.filter(e => seen[e.id]).map(e => e.id);
        const seenCount = seenIds.length;
        // Calcular acertos a partir do history (mais recente vence por id)
        const lastResultById = {};
        (state.history || []).forEach(h => { if (h && h.id) lastResultById[h.id] = h.c; });
        const correctCount = seenIds.filter(id => lastResultById[id] === true).length;
        const wrongCount = seenIds.filter(id => lastResultById[id] === false).length;
        const pct = count > 0 ? Math.round((seenCount / count) * 100) : 0;
        // 'isActive' agora = "incluído nos meus treinos por defeito" (state persistente)
        // Click no checkbox/card persiste a escolha em state.activeTopics
        const tEsc = t.replace(/'/g, "\\'");
        // Cor da barra de progresso: verde se ≥ 80% acertos, amarelo se intermédio, cinza se nada
        const progBarColor = seenCount === 0 ? '#e5e7eb' : (correctCount / Math.max(seenCount, 1)) >= 0.8 ? '#16a34a' : '#f59e0b';
        // Indicador de estado para saber qual treinar
        // - 'novo' (sem badge — só a contagem 0/N)
        // - 'treinar' (vermelho) — acertos < 60%
        // - 'curso' (amarelo) — acertos 60-85% OU progresso < 80% do banco
        // - 'dominado' (verde) — acertos ≥ 85% E pelo menos 80% do banco respondido
        let statusBadge = '';
        if (seenCount > 0 && count > 0) {
            const acc = correctCount / seenCount;
            const coverage = seenCount / count;
            if (acc < 0.6) {
                statusBadge = '<span title="Acerto baixo — pratica mais" style="background:#fef2f2;color:#dc2626;border:1px solid #fca5a5;font-size:0.58rem;font-weight:800;padding:1px 5px;border-radius:4px;letter-spacing:0.04em;text-transform:uppercase">🎯 Treinar</span>';
            } else if (acc >= 0.85 && coverage >= 0.8) {
                statusBadge = '<span title="Dominado — continua a manter" style="background:#dcfce7;color:#15803d;border:1px solid #86efac;font-size:0.58rem;font-weight:800;padding:1px 5px;border-radius:4px;letter-spacing:0.04em;text-transform:uppercase">✓ Dominado</span>';
            } else {
                statusBadge = '<span title="Em progresso" style="background:#fef3c7;color:#92400e;border:1px solid #fcd34d;font-size:0.58rem;font-weight:800;padding:1px 5px;border-radius:4px;letter-spacing:0.04em;text-transform:uppercase">⚡ Em curso</span>';
            }
        }
        const stars = topicStars(key, t);
        // Badge "Sai no teste" — se este topico esta em algum teste futuro desta disciplina
        let testBadge = '';
        const upcomingTest = topicToTest[t];
        if (upcomingTest) {
            const [yyyy, mm, dd] = upcomingTest.date.split('-');
            const dateStr = `${dd}/${mm}`;
            const today = todayStr();
            const isPast = upcomingTest.date < today;
            const bg = isPast ? '#fef2f2' : '#fef3c7';
            const fg = isPast ? '#dc2626' : '#92400e';
            const bd = isPast ? '#fca5a5' : '#fcd34d';
            testBadge = `<span title="Sai no teste de ${SUBJECTS[key]?.name||''} de ${dateStr}" style="background:${bg};color:${fg};border:1px solid ${bd};font-size:0.58rem;font-weight:800;padding:1px 5px;border-radius:4px;letter-spacing:0.04em;text-transform:uppercase">📝 ${dateStr}</span>`;
        }
        const borderColor = isActive ? subColor : (isRecommended ? '#14b8a6' : (upcomingTest ? '#fcd34d' : 'transparent'));
        const cardBg = isActive ? '#fff' : (isRecommended ? '#f0fdfa' : (upcomingTest ? '#fffbeb' : '#fafafa'));
        return `
            <div onclick="toggleActiveTopic('${key}','${tEsc}');renderTopicList();" style="background:${cardBg};padding:7px 10px;border-radius:10px;box-shadow:var(--shadow-sm);margin-bottom:5px;display:flex;align-items:center;gap:7px;opacity:${isActive ? '1' : '0.55'};cursor:pointer;border:1.5px solid ${borderColor}">
                <input type="checkbox" ${isActive ? 'checked' : ''} onclick="event.stopPropagation();toggleActiveTopic('${key}','${tEsc}');renderTopicList();" style="width:16px;height:16px;accent-color:${subColor};flex-shrink:0" title="Incluir nos meus treinos por defeito">
                <span style="width:20px;height:20px;border-radius:50%;background:${isActive ? subColor : '#cbd5e1'};color:#fff;font-size:0.65rem;font-weight:800;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0">${i+1}</span>
                <div style="flex:1;min-width:0">
                    <div style="font-weight:700;font-size:0.88rem;display:flex;align-items:center;gap:5px;line-height:1.2;flex-wrap:wrap">${t}${testBadge}${statusBadge}${isRecommended ? '<span title="Recomendado pelo diagnóstico" style="background:#14b8a6;color:#fff;font-size:0.58rem;font-weight:700;padding:1px 5px;border-radius:4px;letter-spacing:0.04em;text-transform:uppercase">REC</span>' : ''}${stars ? `<span title="Domínio" style="font-size:0.72rem;letter-spacing:1px">${stars}</span>` : ''}</div>
                    <div style="font-size:0.68rem;color:var(--text-light);margin-top:1px;display:flex;align-items:center;gap:6px">
                        <span style="color:${seenCount > 0 ? subColor : 'var(--text-light)'};font-weight:600">${seenCount}/${count}</span>
                        ${correctCount > 0 ? `<span style="color:#16a34a">✓${correctCount}</span>` : ''}
                        ${wrongCount > 0 ? `<span style="color:#dc2626">✗${wrongCount}</span>` : ''}
                        ${count > 0 ? `<span style="flex:1;height:3px;background:#f3f4f6;border-radius:999px;overflow:hidden;min-width:30px"><span style="display:block;height:100%;width:${pct}%;background:${progBarColor};border-radius:999px;transition:width 0.3s"></span></span>` : ''}
                    </div>
                </div>
                <button class="icon-btn" onclick="event.stopPropagation();openTopicAnsweredModal('${key}','${tEsc}')" title="Perguntas respondidas" style="background:#fce7f3;color:#f472b6;flex-shrink:0;width:30px;height:30px;font-size:0.78rem"><i class="fas fa-list-check"></i></button>
                ${LESSONS[`${key}/${t}`] ? `<button class="icon-btn help-btn" onclick="event.stopPropagation();openLessonByKey('${key}/${tEsc}')" title="Explicação" style="width:30px;height:30px;font-size:0.78rem" aria-label="Explicação"><i class="fas fa-book-open" aria-hidden="true"></i></button>` : ''}
            </div>
        `;
    }).join('');
    updateTopicSelBar();
}
// Modal: lista de perguntas respondidas para um tópico
function openTopicAnsweredModal(subjectKey, topic) {
    const sub = SUBJECTS[subjectKey];
    const seen = state.exerciseSeen || {};
    const lastResultById = {};
    (state.history || []).forEach(h => { if (h && h.id) lastResultById[h.id] = h.c; });
    const pool = [
        ...EXERCISES.filter(e => e.s === subjectKey && e.t === topic),
        ...(state.maxExercises || []).filter(e => e.s === subjectKey && e.t === topic)
    ];
    const seenItems = pool
        .filter(e => seen[e.id])
        .sort((a, b) => (seen[b.id] || 0) - (seen[a.id] || 0)); // mais recentes primeiro
    const unseenCount = pool.length - seenItems.length;

    document.getElementById('topic-answered-modal-temp')?.remove();
    let listHtml;
    if (seenItems.length === 0) {
        listHtml = `<p style="text-align:center;color:var(--text-light);padding:20px">Ainda não respondeste a nenhuma pergunta deste tópico.</p>`;
    } else {
        listHtml = seenItems.map(e => {
            const result = lastResultById[e.id];
            const icon = result === true ? '✓' : result === false ? '✗' : '•';
            const color = result === true ? '#16a34a' : result === false ? '#dc2626' : '#9ca3af';
            const bg    = result === true ? '#f0fdf4' : result === false ? '#fef2f2' : '#f9fafb';
            const ts = seen[e.id];
            const date = ts ? new Date(ts).toLocaleDateString('pt-PT', { day:'2-digit', month:'2-digit', year:'numeric' }) : '';
            const qPreview = String(e.q || '').replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/gu, '').trim().slice(0, 100);
            return `
                <div style="background:${bg};padding:10px 12px;border-radius:8px;margin-bottom:6px;display:flex;align-items:flex-start;gap:10px;border-left:3px solid ${color}">
                    <div style="font-size:1.2rem;font-weight:700;color:${color};line-height:1;width:18px;flex-shrink:0;text-align:center">${icon}</div>
                    <div style="flex:1;min-width:0">
                        <div style="font-size:0.85rem;color:var(--text);line-height:1.35">${escapeHtml(qPreview)}${qPreview.length >= 100 ? '…' : ''}</div>
                        <div style="font-size:0.7rem;color:var(--text-light);margin-top:3px">${date}${e.diff ? ` · dif. ${e.diff}` : ''}</div>
                    </div>
                </div>
            `;
        }).join('');
    }

    const html = `
        <div id="topic-answered-modal-temp" class="modal" style="display:flex;align-items:center;justify-content:center;padding:20px">
            <div class="modal-content" style="max-width:560px;max-height:90vh;border-radius:18px;display:flex;flex-direction:column">
                <div class="modal-header">
                    <h2 style="font-size:1rem">📚 ${escapeHtml(topic)}</h2>
                    <button class="icon-btn" onclick="closeTopicAnsweredModal()" aria-label="Fechar"><i class="fas fa-times"></i></button>
                </div>
                <div class="modal-body" style="flex:1;overflow-y:auto">
                    <div style="display:flex;gap:8px;margin-bottom:14px;font-size:0.78rem;flex-wrap:wrap">
                        <span style="background:#fce7f3;color:#f472b6;padding:4px 10px;border-radius:999px;font-weight:700">📖 ${pool.length} no total</span>
                        <span style="background:#dbeafe;color:#1d4ed8;padding:4px 10px;border-radius:999px;font-weight:700">${seenItems.length} respondidas</span>
                        ${unseenCount > 0 ? `<span style="background:#f3f4f6;color:#6b7280;padding:4px 10px;border-radius:999px;font-weight:700">${unseenCount} novas</span>` : ''}
                    </div>
                    ${listHtml}
                </div>
            </div>
        </div>
    `;
    document.body.insertAdjacentHTML('beforeend', html);
}

function closeTopicAnsweredModal() {
    document.getElementById('topic-answered-modal-temp')?.remove();
}

function clearTopicSelection() {
    // Desactiva TODOS os tópicos da disciplina atual (state persistente)
    const key = currentSubjectView;
    if (key) setActiveTopicsFor(key, []);
    renderTopicList();
}

function updateTopicSelBar() {
    const n = selectedTopicsForMax.size;
    const maxBar = document.getElementById('max-topic-sel-bar');
    const maxCnt = document.getElementById('max-sel-count');
    if (maxBar) maxBar.style.display = n > 0 ? 'block' : 'none';
    if (maxCnt) maxCnt.textContent = n;
    // Sticky bar 'Treinar selecionados' já não é necessária — o botão
    // 'Começar treino' no topo usa os mesmos tópicos ativos.
    const selBar = document.getElementById('topic-sel-actions');
    if (selBar) selBar.style.display = 'none';
}

function selectAllTopics() {
    // Ativa TODOS os tópicos da disciplina (state persistente)
    const key = currentSubjectView;
    if (!key) return;
    const topics = CURRICULUM[key] || [];
    setActiveTopicsFor(key, topics);
    renderTopicList();
}

function startMaxForSelected(key, isTestPrep = false) {
    const topics = [...selectedTopicsForMax];
    selectedTopicsForMax.clear();
    startMaxSession(key, { topics, forceNew: true, testPrep: isTestPrep });
}

function onProgressSlider(val) {
    const key = currentSubjectView;
    const n = parseInt(val);
    state.progress[key] = { toIndex: n };
    // Slider funciona como atalho: define os tópicos 0..N como ativos
    // (sobrescreve o estado persistente).
    const topics = CURRICULUM[key] || [];
    setActiveTopicsFor(key, topics.slice(0, n));
    document.getElementById('progress-current').textContent = val;
    renderTopicList();
}

function closeSubjectDetail() {
    selectedTopicsForMax.clear();
    const el = document.getElementById('subject-detail-container');
    if (el) el.remove();
    currentSubjectView = null;
    renderSubjects();
    renderHome();
}

// ============================================================
// PAINEL DE PAIS — vista read-only do progresso do perfil ativo.
// Agrega dados que JÁ existem (history, subjects, max.tutorWeak):
// por disciplina mostra nº respondido, % de acerto e pontos fracos,
// + atividade dos últimos 7 dias. Não altera nada — só lê.
// ============================================================
function _parentStats(src) {
    // src opcional = { profile, max } vindo de um backup REMOTO (Firestore).
    // Sem src → perfil ativo local.
    const p = src ? src.profile : ((typeof activeProfile === 'function') ? activeProfile() : null);
    const maxObj = src ? (src.max || {}) : (state.max || {});
    const hist = (p && Array.isArray(p.history)) ? p.history : (src ? [] : (state.history || []));
    // Agrega por disciplina a partir do history (fonte mais fiável: tem s + c).
    const bySubj = {};
    hist.forEach(h => {
        if (!h || !h.s || /^(__proto__|constructor|prototype)$/.test(h.s)) return;
        const b = bySubj[h.s] || (bySubj[h.s] = { ans: 0, ok: 0 });
        b.ans++; if (h.c) b.ok++;
    });
    // Atividade dos últimos 7 dias (por data string YYYY-MM-DD).
    const days = {};
    hist.forEach(h => { if (h && h.d) { const d = days[h.d] || (days[h.d] = { ans: 0, ok: 0 }); d.ans++; if (h.c) d.ok++; } });
    // Pontos fracos do tutor de Inglês (se existirem).
    const weakRaw = (p && p.tutorWeak) || maxObj.tutorWeak || {};
    const weak = Object.keys(weakRaw)
        .map(t => ({ t, net: (weakRaw[t].wrong || 0) - (weakRaw[t].right || 0) }))
        .filter(x => x.net > 0)
        .sort((a, b) => b.net - a.net)
        .slice(0, 6);
    const readingLog = (p && Array.isArray(p.readingLog)) ? p.readingLog : (src ? [] : (state.readingLog || []));
    const sessionLog = (p && Array.isArray(p.sessionLog)) ? p.sessionLog : (src ? [] : (state.sessionLog || []));
    const lessonLog = (p && Array.isArray(p.lessonLog)) ? p.lessonLog : (src ? [] : (state.lessonLog || []));
    return { bySubj, days, weak, total: hist.length, name: p && p.name, year: p && p.year, hist, readingLog, sessionLog, lessonLog, mastery: (p && p.topicMastery) || (src ? {} : (state.topicMastery || {})), local: !src };
}

// ── "Está a melhorar?" — análise de EVOLUÇÃO a partir do histórico ──
// Responde à pergunta que o Painel não respondia: ela está a ficar melhor?
function _pdWeeklyAccuracy(hist) {
    const wk = {};
    hist.forEach(h => {
        if (!h || !h.d) return;
        const d = new Date(h.d + 'T00:00:00'); if (isNaN(d)) return;
        const monday = new Date(d); const day = (d.getDay() + 6) % 7; monday.setDate(d.getDate() - day);
        const key = _localDayKey(monday);
        const w = wk[key] || (wk[key] = { ans: 0, ok: 0, key });
        w.ans++; if (h.c) w.ok++;
    });
    return Object.values(wk).filter(w => w.ans >= 4).sort((a, b) => a.key.localeCompare(b.key)).slice(-6);
}
function _pdTopicMap(year) {
    const m = {};
    const bank = (window.EXERCISES_BY_YEAR && window.EXERCISES_BY_YEAR[year]) || [];
    bank.forEach(e => { if (e && e.id) m[e.id] = { t: e.t, s: e.s }; });
    (state.maxExercises || []).forEach(e => { if (e && e.id && !m[e.id]) m[e.id] = { t: e.t, s: e.s }; });
    return m;
}
function _pdSkillDeltas(hist, year) {
    const map = _pdTopicMap(year);
    const byTopic = {};
    hist.forEach(h => {
        const info = h && h.id && map[h.id];
        if (!info || !info.t) return;
        const t = byTopic[info.t] || (byTopic[info.t] = { t: info.t, s: info.s, seq: [] });
        t.seq.push(h.c ? 1 : 0);
    });
    const rows = [];
    Object.values(byTopic).forEach(t => {
        const n = t.seq.length;
        if (n < 6) return; // pouca amostra para tendência
        const half = Math.floor(n / 2);
        const earlier = t.seq.slice(0, half);
        const recent = t.seq.slice(half);
        const eAcc = Math.round(100 * earlier.reduce((a, b) => a + b, 0) / earlier.length);
        const rAcc = Math.round(100 * recent.reduce((a, b) => a + b, 0) / recent.length);
        rows.push({ t: t.t, s: t.s, delta: rAcc - eAcc, rAcc, n });
    });
    return rows;
}
// Tooltip rico ao toque (o <title> nativo é fraco em mobile): balão
// posicionado sobre a marca tocada, auto-esconde em 2.6s.
function _pdTip(evt) {
    const t = evt.currentTarget || evt.target;
    const tip = t && t.getAttribute && t.getAttribute('data-tip');
    const chart = t && t.closest ? t.closest('.pd-chart') : null;
    if (!tip || !chart) return;
    document.querySelectorAll('.pd-tipbox').forEach(x => x.remove());
    const box = document.createElement('div');
    box.className = 'pd-tipbox';
    box.textContent = tip;
    chart.appendChild(box);
    const r = t.getBoundingClientRect(), cr = chart.getBoundingClientRect();
    const bw = box.offsetWidth || 120;
    let x = r.left + r.width / 2 - cr.left;
    x = Math.max(bw / 2 + 4, Math.min(cr.width - bw / 2 - 4, x));
    box.style.left = x + 'px';
    box.style.top = Math.max(2, r.top - cr.top - 6) + 'px';
    clearTimeout(_pdTip._to);
    _pdTip._to = setTimeout(() => box.remove(), 2600);
}
window._pdTip = _pdTip;
// Calendário de constância (12 semanas): sequencial, um só matiz claro→escuro.
// É o gráfico do HÁBITO — mostra num relance se a prática é regular.
const _PD_HEAT_RAMP = ['#eef2f6', '#c9e8f2', '#7cc4dd', '#2d9fc4', '#0b6e8d'];
function _pdHeatmap(days) {
    const MONTHS = ['jan', 'fev', 'mar', 'abr', 'mai', 'jun', 'jul', 'ago', 'set', 'out', 'nov', 'dez'];
    const DAYS_PT = ['Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb', 'Dom'];
    const cell = 18, gap = 4, padL = 30, padT = 16;
    const WEEKS = 12;
    const today = new Date(); today.setHours(0, 0, 0, 0);
    const start = new Date(today); start.setDate(start.getDate() - (WEEKS * 7 - 1));
    start.setDate(start.getDate() - ((start.getDay() + 6) % 7)); // recua até segunda
    const W = padL + WEEKS * (cell + gap) - gap + 6;
    const H = padT + 7 * (cell + gap) - gap + 6;
    let cells = '', monthLabels = '', lastMonth = -1;
    for (let w = 0; w < WEEKS; w++) {
        const monday = new Date(start); monday.setDate(start.getDate() + w * 7);
        if (monday.getMonth() !== lastMonth) {
            lastMonth = monday.getMonth();
            monthLabels += `<text x="${padL + w * (cell + gap)}" y="11" class="pd-xlab">${MONTHS[lastMonth]}</text>`;
        }
        for (let d = 0; d < 7; d++) {
            const day = new Date(monday); day.setDate(monday.getDate() + d);
            if (day > today) continue;
            const key = _localDayKey(day);
            const n = (days[key] && days[key].ans) || 0;
            const lvl = n === 0 ? 0 : n <= 2 ? 1 : n <= 5 ? 2 : n <= 9 ? 3 : 4;
            const tip = `${DAYS_PT[d]} ${key.slice(8)}/${key.slice(5, 7)} · ${n} exercício${n === 1 ? '' : 's'}`;
            cells += `<rect x="${padL + w * (cell + gap)}" y="${padT + d * (cell + gap)}" width="${cell}" height="${cell}" rx="4" fill="${_PD_HEAT_RAMP[lvl]}" data-tip="${escapeHtml(tip)}" onclick="_pdTip(event)"><title>${escapeHtml(tip)}</title></rect>`;
        }
    }
    const dayLabels = [0, 2, 4].map(d =>
        `<text x="${padL - 6}" y="${padT + d * (cell + gap) + cell / 2 + 3}" text-anchor="end" class="pd-xlab">${DAYS_PT[d]}</text>`).join('');
    return `<svg width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" role="img" aria-label="Constância das últimas 12 semanas" xmlns="http://www.w3.org/2000/svg" class="pd-heat">${monthLabels}${dayLabels}${cells}</svg>
    <div class="pd-heat-legend">menos ${_PD_HEAT_RAMP.map(c => `<i style="background:${c}"></i>`).join('')} mais</div>`;
}
// Linha multi-série (comparação de perfis): 2 séries, legenda + rótulo
// direto no fim de cada linha (identidade nunca só pela cor).
function _pdMultiLine(o) {
    const labels = o.labels || [], series = o.series || [];
    const n = labels.length;
    if (!n || !series.length) return '';
    const W = 340, H = 160, padL = 34, padR = 70, padT = 14, padB = 22;
    const plotW = W - padL - padR, plotH = H - padT - padB, baseY = padT + plotH;
    const yMax = o.yMax || 100;
    const X = i => n === 1 ? padL + plotW / 2 : padL + i * (plotW / (n - 1));
    const Y = v => baseY - (Math.max(0, Math.min(yMax, v)) / yMax) * plotH;
    const ticks = [0, 50, 100].map(tv => {
        const ty = Y(tv);
        return `<line x1="${padL}" y1="${ty.toFixed(1)}" x2="${W - padR}" y2="${ty.toFixed(1)}" stroke="#e8edf2" stroke-width="1"/>
            <text x="${padL - 6}" y="${(ty + 3).toFixed(1)}" text-anchor="end" class="pd-tick">${tv}%</text>`;
    }).join('');
    const xLabels = labels.map((lb, i) => `<text x="${X(i).toFixed(1)}" y="${H - 6}" text-anchor="middle" class="pd-xlab">${lb}</text>`).join('');
    // Rótulos de fim: afasta-os se colidirem (mín. 14px)
    const ends = series.map(s => {
        const last = s.pts[s.pts.length - 1];
        return { name: s.name, color: s.color, x: X(last.i), y: Y(last.v) };
    });
    if (ends.length === 2 && Math.abs(ends[0].y - ends[1].y) < 14) {
        const mid = (ends[0].y + ends[1].y) / 2;
        const top = ends[0].y <= ends[1].y ? 0 : 1;
        ends[top].y = mid - 7; ends[1 - top].y = mid + 7;
    }
    const body = series.map((s, si) => {
        const pts = s.pts.map(p => [X(p.i), Y(p.v)]);
        const line = _pdSmooth(pts, padT, baseY);
        const dots = s.pts.map((p, k) => {
            const tip = escapeHtml(`${s.name} — semana de ${labels[p.i]}: ${p.v}%`);
            return `<circle cx="${X(p.i).toFixed(1)}" cy="${Y(p.v).toFixed(1)}" r="4.5" fill="${s.color}" stroke="#fff" stroke-width="2" data-tip="${escapeHtml(tip)}" onclick="_pdTip(event)"><title>${escapeHtml(tip)}</title></circle>`;
        }).join('');
        const e = ends[si];
        const endLab = `<circle cx="${(W - padR + 10)}" cy="${e.y.toFixed(1)}" r="3.5" fill="${e.color}"/><text x="${(W - padR + 17)}" y="${(e.y + 3.5).toFixed(1)}" class="pd-cmp-name">${escapeHtml(e.name.length > 9 ? e.name.slice(0, 8) + '…' : e.name)}</text>`;
        return `<path d="${line}" fill="none" stroke="${s.color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>${dots}${endLab}`;
    }).join('');
    return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${o.aria || 'Comparação de perfis'}" xmlns="http://www.w3.org/2000/svg">${ticks}${body}${xLabels}</svg>`;
}
// Secção "Lado a lado" — compara a precisão semanal de 2 perfis locais.
function _pdCompareHtml() {
    const profs = (state.profiles || []).filter(p => p && Array.isArray(p.history) && p.history.length >= 8);
    if (profs.length < 2) return '';
    // perfil ativo primeiro; depois o outro com mais história
    const activeId = state.activeProfileId;
    profs.sort((a, b) => (a.id === activeId ? -1 : b.id === activeId ? 1 : b.history.length - a.history.length));
    const pair = profs.slice(0, 2);
    // últimas 6 semanas (segundas-feiras) como eixo comum
    const mondays = [];
    const now = new Date(); now.setHours(0, 0, 0, 0);
    const mon0 = new Date(now); mon0.setDate(mon0.getDate() - ((mon0.getDay() + 6) % 7));
    for (let i = 5; i >= 0; i--) { const m = new Date(mon0); m.setDate(mon0.getDate() - i * 7); mondays.push(_localDayKey(m)); }
    const labels = mondays.map(k => k.slice(8) + '/' + k.slice(5, 7));
    const COLORS = ['#0891b2', '#e11d48'];
    const series = pair.map((p, pi) => {
        const wk = {};
        p.history.forEach(h => {
            if (!h || !h.d) return;
            const d = new Date(h.d + 'T00:00:00'); if (isNaN(d)) return;
            const m = new Date(d); m.setDate(d.getDate() - ((d.getDay() + 6) % 7));
            const key = _localDayKey(m);
            const w = wk[key] || (wk[key] = { ans: 0, ok: 0 });
            w.ans++; if (h.c) w.ok++;
        });
        const pts = [];
        mondays.forEach((k, i) => { const w = wk[k]; if (w && w.ans >= 3) pts.push({ i, v: Math.round(100 * w.ok / w.ans) }); });
        return { name: p.name || 'Perfil', color: COLORS[pi], pts };
    }).filter(s => s.pts.length >= 2);
    if (series.length < 2) return '';
    const legend = series.map(s => `<span class="pd-cmp-chip"><i style="background:${s.color}"></i>${escapeHtml(s.name)}</span>`).join('');
    return `<div class="pd-section-h">👥 Lado a lado — precisão semanal</div>
        <div class="pd-cmp-legend">${legend}</div>
        <div class="pd-chart">${_pdMultiLine({ labels, series, aria: 'Precisão semanal dos dois perfis' })}</div>`;
}
// ── "Dia a dia" — detalhe de UM dia: disciplinas, sessões com tempo,
// e resumos lidos. O nível de detalhe que um pai precisa para acompanhar.
function _pdDayDetailHtml(ctx, key) {
    const hist = (ctx.hist || []).filter(h => h && h.d === key);
    const sess = (ctx.sessionLog || []).filter(x => x && x.d === key);
    const les = (ctx.lessonLog || []).filter(x => x && x.d === key);
    if (!hist.length && !sess.length && !les.length) return '<div class="pd-empty" style="margin:8px 0 14px">Sem atividade neste dia.</div>';
    const ok = hist.filter(h => h.c).length;
    const pct = hist.length ? Math.round(100 * ok / hist.length) : 0;
    const totSecs = sess.reduce((s, x) => s + (x.secs || 0), 0);
    const fmtT = s => s >= 3600 ? Math.floor(s / 3600) + 'h' + String(Math.round((s % 3600) / 60)).padStart(2, '0') : s >= 60 ? Math.round(s / 60) + ' min' : s + ' s';
    const by = {};
    hist.forEach(h => { if (!h || !h.s || /^(__proto__|constructor|prototype)$/.test(h.s)) return; const b = by[h.s] || (by[h.s] = { n: 0, ok: 0 }); b.n++; if (h.c) b.ok++; });
    const subjRows = Object.keys(by).sort((a, b) => by[b].n - by[a].n).map(k => {
        const meta = (ctx.SUBJ && ctx.SUBJ[k]) || { name: k, color: '#64748b', icon: 'fa-book' };
        const b = by[k];
        const p2 = Math.round(100 * b.ok / b.n);
        return `<div class="pdd-subj"><span class="pd-ico" style="background:${meta.color};width:26px;height:26px;font-size:0.72rem"><i class="fas ${meta.icon}"></i></span><span class="pdd-subj-n">${escapeHtml(meta.name)}</span><span class="pdd-subj-v"><b>${b.n}</b> feitos · ${b.ok} certas (${p2}%)</span></div>`;
    }).join('');
    const sessRows = sess.map(x => {
        const meta = (ctx.SUBJ && ctx.SUBJ[x.s]) || { name: x.s, color: '#64748b' };
        return `<div class="pdd-sess"><span class="pdd-sess-h">${escapeHtml(x.hm || '—')}</span><span class="pdd-sess-s"><i style="background:${meta.color}"></i>${escapeHtml(meta.name)}</span><span class="pdd-sess-v">${Number(x.ok) || 0}/${Number(x.n) || 0} certas · <b>${fmtT(Number(x.secs) || 0)}</b></span></div>`;
    }).join('');
    const lesHtml = les.length
        ? `<div class="pdd-h">📖 Resumos lidos (${les.length})</div><div class="pd-weak" style="margin-bottom:10px">${les.map(x => `<span class="pd-weak-chip" style="background:${x.w === 'erro' ? '#fef3c7' : '#dbeafe'};color:${x.w === 'erro' ? '#92400e' : '#1d4ed8'}">${x.w === 'erro' ? '⚠️ ' : ''}${escapeHtml(x.t || x.k || '')}${Number(x.rt) ? ` · ${Number(x.rt)}s` : ''}</span>`).join('')}</div>`
        : `<div class="pdd-noles">📖 Não abriu nenhum resumo neste dia.</div>`;
    return `
        <div class="pdd-totals"><b>${hist.length}</b> exercícios · <b>${pct}%</b> certas${totSecs ? ` · <b>${fmtT(totSecs)}</b> de estudo` : ''}</div>
        ${subjRows ? `<div class="pdd-h">📚 Por disciplina</div>${subjRows}` : ''}
        ${sessRows ? `<div class="pdd-h">⏱️ Sessões e testes</div>${sessRows}` : ''}
        ${lesHtml}`;
}
window._pdPickDay = function (key) {
    const ctx = window._pdDayCtx;
    if (!ctx) return;
    ctx.sel = key;
    document.querySelectorAll('.pdd-chip').forEach(c => c.classList.toggle('sel', c.dataset.d === key));
    const box = document.getElementById('pdd-detail');
    if (box) box.innerHTML = _pdDayDetailHtml(ctx, key);
};
function _pdDayHtml(stats, SUBJ) {
    const keys = [];
    for (let i = 6; i >= 0; i--) { const d = new Date(); d.setDate(d.getDate() - i); keys.push(_localDayKey(d)); }
    const today = keys[keys.length - 1];
    window._pdDayCtx = { hist: stats.hist || [], sessionLog: stats.sessionLog || [], lessonLog: stats.lessonLog || [], SUBJ, sel: today };
    const DL = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'];
    const chips = keys.map(k => {
        const d = new Date(k + 'T12:00:00');
        const has = (stats.hist || []).some(h => h && h.d === k) || (stats.sessionLog || []).some(x => x && x.d === k);
        return `<button class="pdd-chip ${k === today ? 'sel' : ''} ${has ? 'has' : ''}" data-d="${k}" onclick="_pdPickDay('${k}')">${DL[d.getDay()]}<b>${k.slice(8)}</b></button>`;
    }).join('');
    return `<div class="pd-section-h">📅 Dia a dia</div>
        <div class="pdd-chips">${chips}</div>
        <div id="pdd-detail">${_pdDayDetailHtml(window._pdDayCtx, today)}</div>`;
}
// Secção "Está a melhorar?" — tendência de acerto por semana, competências
// que subiram/desceram, e fluência de leitura ao longo do tempo.
// ── Gráficos SVG do Painel de Pais — desenhados à mão, specs profissionais ──
// Regras seguidas: linha 2px com juntas redondas; pontos ≥8px com anel de
// superfície 2px; wash de área ~10-14%; colunas ≤24px com topo arredondado
// 4px e base reta; grelha hairline recessiva; rótulos SELETIVOS (extremo e
// último, nunca todos); texto sempre em tons de texto, nunca na cor da série;
// série única → sem legenda (o título nomeia-a); <title> nativo por marca.
const _PD_ACCENT = '#0891b2';
// Chave de dia LOCAL (YYYY-MM-DD) — igual a todayStr(). NUNCA toISOString():
// em UTC+1 a grelha inteira ficava deslocada um dia.
function _localDayKey(d) {
    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
}
let _pdGradSeq = 0;
function _pdNiceMax(v) {
    if (v <= 10) return 10;
    const p = Math.pow(10, Math.floor(Math.log10(v)));
    for (const m of [1, 1.5, 2, 2.5, 3, 4, 5, 6, 8, 10]) { const c = m * p; if (c >= v) return c; }
    return v;
}
// Catmull-Rom → Bézier, com controlo Y limitado ao plot (sem "overshoot"
// acima de 100% em patamares).
function _pdSmooth(pts, yMin, yMax) {
    if (pts.length < 3) return 'M' + pts.map(p => p[0].toFixed(1) + ',' + p[1].toFixed(1)).join(' L');
    const cl = y => Math.max(yMin, Math.min(yMax, y));
    let d = `M${pts[0][0].toFixed(1)},${pts[0][1].toFixed(1)}`;
    for (let i = 0; i < pts.length - 1; i++) {
        const p0 = pts[Math.max(0, i - 1)], p1 = pts[i], p2 = pts[i + 1], p3 = pts[Math.min(pts.length - 1, i + 2)];
        const c1x = p1[0] + (p2[0] - p0[0]) / 6, c1y = cl(p1[1] + (p2[1] - p0[1]) / 6);
        const c2x = p2[0] - (p3[0] - p1[0]) / 6, c2y = cl(p2[1] - (p3[1] - p1[1]) / 6);
        d += `C${c1x.toFixed(1)},${c1y.toFixed(1)} ${c2x.toFixed(1)},${c2y.toFixed(1)} ${p2[0].toFixed(1)},${p2[1].toFixed(1)}`;
    }
    return d;
}
// Gráfico de linha (série única): tendência ao longo do tempo.
function _pdLineChart(o) {
    const vals = o.vals || [], labels = o.labels || [], titles = o.titles || [];
    const n = vals.length;
    if (!n) return '';
    const color = o.color || _PD_ACCENT;
    const W = 340, H = 150, padL = 34, padR = 44, padT = 16, padB = 22;
    const plotW = W - padL - padR, plotH = H - padT - padB, baseY = padT + plotH;
    const yMax = o.yMax || _pdNiceMax(Math.max(...vals, 1));
    const X = i => n === 1 ? padL + plotW / 2 : padL + i * (plotW / (n - 1));
    const Y = v => baseY - (Math.max(0, Math.min(yMax, v)) / yMax) * plotH;
    const pts = vals.map((v, i) => [X(i), Y(v)]);
    const gid = 'pdg' + (++_pdGradSeq);
    const line = _pdSmooth(pts, padT, baseY);
    const area = `${line} L${pts[n - 1][0].toFixed(1)},${baseY} L${pts[0][0].toFixed(1)},${baseY} Z`;
    // Grelha: 3 linhas limpas (0, meio, topo) + ticks à esquerda, tabulares.
    const ticks = [0, yMax / 2, yMax].map(tv => {
        const ty = Y(tv);
        return `<line x1="${padL}" y1="${ty.toFixed(1)}" x2="${W - padR}" y2="${ty.toFixed(1)}" stroke="#e8edf2" stroke-width="1"/>
            <text x="${padL - 6}" y="${(ty + 3).toFixed(1)}" text-anchor="end" class="pd-tick">${Math.round(tv)}${o.unit === '%' ? '%' : ''}</text>`;
    }).join('');
    // Rótulos do eixo X — se muitos, salta alternados (mantém o último).
    const skip = n > 7 ? 2 : 1;
    const xLabels = labels.map((lb, i) => (i % skip === 0 || i === n - 1)
        ? `<text x="${X(i).toFixed(1)}" y="${H - 6}" text-anchor="middle" class="pd-xlab">${lb}</text>` : '').join('');
    // Pontos: todos com anel de superfície; o último é maior e leva o rótulo.
    const dots = pts.map((p, i) => {
        const last = i === n - 1;
        const tip = titles[i] || (labels[i] + ': ' + vals[i] + (o.unit || ''));
        return `<circle cx="${p[0].toFixed(1)}" cy="${p[1].toFixed(1)}" r="${last ? 5.5 : 4.5}" fill="${color}" stroke="#fff" stroke-width="2" class="pd-dot" data-tip="${escapeHtml(tip)}" onclick="_pdTip(event)"><title>${escapeHtml(tip)}</title></circle>`;
    }).join('');
    const endLabel = `<text x="${(pts[n - 1][0] + 9).toFixed(1)}" y="${(pts[n - 1][1] + 4).toFixed(1)}" class="pd-endlab">${vals[n - 1]}${o.unit || ''}</text>`;
    return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${o.aria || 'Evolução'}" xmlns="http://www.w3.org/2000/svg">
        <defs><linearGradient id="${gid}" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stop-color="${color}" stop-opacity="0.16"/>
            <stop offset="1" stop-color="${color}" stop-opacity="0.01"/>
        </linearGradient></defs>
        ${ticks}
        <path d="${area}" fill="url(#${gid})" class="pd-area"/>
        <path d="${line}" fill="none" stroke="${color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="pd-line"/>
        ${dots}${endLabel}${xLabels}
    </svg>`;
}
// Gráfico de colunas (últimos 7 dias): ênfase no dia de hoje, resto recessivo.
function _pdColumnChart(o) {
    const vals = o.vals || [], labels = o.labels || [], titles = o.titles || [];
    const n = vals.length;
    if (!n) return '';
    const accent = o.color || _PD_ACCENT, rest = '#c2dde9';
    const W = 340, H = 116, padT = 20, padB = 20, padL = 8, padR = 8;
    const plotH = H - padT - padB, baseY = padT + plotH;
    const step = (W - padL - padR) / n;
    const bw = Math.min(24, Math.round(step * 0.58));
    const yMax = _pdNiceMax(Math.max(...vals, 1));
    const maxI = vals.indexOf(Math.max(...vals));
    const cols = vals.map((v, i) => {
        const x = padL + i * step + (step - bw) / 2;
        const h = (v / yMax) * plotH;
        const y = baseY - h;
        const isToday = i === n - 1;
        const fill = isToday ? accent : rest;
        const r = Math.min(4, h);
        // Topo arredondado 4px, base reta (cresce da linha de base).
        const path = h <= 0 ? '' :
            `M${x.toFixed(1)},${baseY} L${x.toFixed(1)},${(y + r).toFixed(1)} Q${x.toFixed(1)},${y.toFixed(1)} ${(x + r).toFixed(1)},${y.toFixed(1)} L${(x + bw - r).toFixed(1)},${y.toFixed(1)} Q${(x + bw).toFixed(1)},${y.toFixed(1)} ${(x + bw).toFixed(1)},${(y + r).toFixed(1)} L${(x + bw).toFixed(1)},${baseY} Z`;
        // Rótulo de valor SELETIVO: só no máximo e no dia de hoje (se > 0).
        const cap = (v > 0 && (i === maxI || isToday))
            ? `<text x="${(x + bw / 2).toFixed(1)}" y="${(y - 5).toFixed(1)}" text-anchor="middle" class="pd-cap">${v}</text>` : '';
        return `<g class="pd-col">${path ? `<path d="${path}" fill="${fill}" data-tip="${titles[i] || (labels[i] + ': ' + v)}" onclick="_pdTip(event)"><title>${titles[i] || (labels[i] + ': ' + v)}</title></path>` : ''}${cap}
            <text x="${(padL + i * step + step / 2).toFixed(1)}" y="${H - 5}" text-anchor="middle" class="pd-xlab${isToday ? ' today' : ''}">${labels[i]}</text></g>`;
    }).join('');
    return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${o.aria || 'Atividade dos últimos 7 dias'}" xmlns="http://www.w3.org/2000/svg">
        <line x1="${padL}" y1="${baseY}" x2="${W - padR}" y2="${baseY}" stroke="#dbe3ea" stroke-width="1"/>
        ${cols}
    </svg>`;
}

function _pdImprovementHtml(stats) {
    const hist = stats.hist || [];
    const weeks = _pdWeeklyAccuracy(hist);
    const deltas = stats.local ? _pdSkillDeltas(hist, stats.year) : [];
    const rlog = stats.readingLog || [];
    if (weeks.length < 2 && deltas.length === 0 && rlog.length === 0) {
        return `<div class="pd-improve pd-improve-empty">📈 <b>Está a melhorar?</b><br><span>Ainda a recolher dados. Depois de uns dias de prática, aparece aqui a evolução.</span></div>`;
    }
    // Tendência semanal — linha suave com wash de área e rótulo no fim
    let weekHtml = '';
    if (weeks.length >= 2) {
        const vals = weeks.map(w => Math.round(100 * w.ok / w.ans));
        const labels = weeks.map(w => w.key.slice(8) + '/' + w.key.slice(5, 7));
        const titles = weeks.map((w, i) => `Semana de ${labels[i]}: ${vals[i]}% (${w.ok} certas em ${w.ans})`);
        const d = vals[vals.length - 1] - vals[0];
        const chip = d >= 6 ? `<span class="pd-chip up">▲ +${d} pontos</span>` : d <= -6 ? `<span class="pd-chip down">▼ ${d} pontos</span>` : `<span class="pd-chip flat">— estável</span>`;
        weekHtml = `<div class="pd-improve-sub">Precisão semanal ${chip}</div>
            <div class="pd-chart">${_pdLineChart({ vals, labels, titles, unit: '%', yMax: 100, aria: 'Precisão por semana' })}</div>`;
    }
    // Competências a melhorar / a reforçar
    let skillHtml = '';
    if (deltas.length) {
        const up = deltas.filter(x => x.delta >= 10).sort((a, b) => b.delta - a.delta).slice(0, 3);
        const down = deltas.filter(x => x.rAcc < 60 || x.delta <= -10).sort((a, b) => a.rAcc - b.rAcc).slice(0, 3);
        if (up.length) skillHtml += `<div class="pd-improve-sub">✅ A dominar melhor</div>` + up.map(x => `<div class="pd-skill up"><span>${escapeHtml(x.t)}</span><span class="pd-skill-d">+${x.delta}% → ${x.rAcc}%</span></div>`).join('');
        if (down.length) skillHtml += `<div class="pd-improve-sub">🎯 A reforçar</div>` + down.map(x => `<div class="pd-skill down"><span>${escapeHtml(x.t)}</span><span class="pd-skill-d">${x.rAcc}% certas</span></div>`).join('');
    }
    // Fluência de leitura
    let readHtml = '';
    if (rlog.length >= 1) {
        const recent = rlog.slice(-5);
        const lastR = recent[recent.length - 1];
        let trendTxt = '';
        if (rlog.length >= 3) {
            const early = rlog.slice(0, Math.ceil(rlog.length / 2));
            const late = rlog.slice(-Math.ceil(rlog.length / 2));
            const avg = a => Math.round(a.reduce((s, x) => s + (x.wpm || 0), 0) / a.length);
            const dW = avg(late) - avg(early);
            trendTxt = dW >= 6 ? `↗️ mais fluente (+${dW} pal/min)` : dW <= -6 ? `↘️ ${-dW} pal/min mais devagar` : '→ estável';
        }
        let readChart = '';
        if (rlog.length >= 2) {
            const rl = rlog.slice(-8);
            const rvals = rl.map(r => Number(r.wpm) || 0);
            const rlabels = rl.map(r => (r.d || '').slice(8) + '/' + (r.d || '').slice(5, 7));
            const rtitles = rl.map((r, i) => `Leitura de ${rlabels[i]}: ${Number(r.wpm) || 0} palavras/min · ${Number(r.acc) || 0}% precisão`);
            readChart = `<div class="pd-chart">${_pdLineChart({ vals: rvals, labels: rlabels, titles: rtitles, unit: '', aria: 'Palavras por minuto ao longo das leituras' })}</div>`;
        }
        readHtml = `<div class="pd-improve-sub">📖 Leitura em voz alta ${trendTxt ? '<b>' + trendTxt + '</b>' : ''}</div>
            <div class="pd-read-kpis">
                <div class="pd-read-kpi"><b>${Number(lastR.wpm) || 0}</b><span>palavras/min</span></div>
                <div class="pd-read-kpi"><b>${Number(lastR.acc) || 0}%</b><span>precisão</span></div>
                <div class="pd-read-kpi"><b>${rlog.length}</b><span>leituras</span></div>
            </div>${readChart}`;
    }
    // "Esta semana treina": os 3 tópicos com pior acerto (≥4 tentativas, <70%)
    let trainHtml = '';
    try {
        const SUBJm = (window.SUBJECTS_BY_YEAR && window.SUBJECTS_BY_YEAR[stats.year]) || SUBJECTS || {};
        const rows = Object.keys(stats.mastery || {}).map(k => {
            const m = stats.mastery[k] || {}; const d = (m.d1 || 0) + (m.d2 || 0) + (m.d3 || 0), w = (m.w1 || 0) + (m.w2 || 0) + (m.w3 || 0);
            const i = k.indexOf('/'); return { s: k.slice(0, i), t: k.slice(i + 1), n: d + w, acc: (d + w) ? Math.round(100 * d / (d + w)) : 0 };
        }).filter(r => r.n >= 4 && r.acc < 70).sort((a, b) => a.acc - b.acc).slice(0, 3);
        if (rows.length) trainHtml = `<div class="pd-improve-sub">🎯 Esta semana treina</div>` + rows.map(r => {
            const meta = SUBJm[r.s] || { name: r.s };
            return `<div class="pd-skill down"><span>${escapeHtml(meta.name)} · ${escapeHtml(r.t)}</span><span class="pd-skill-d">${r.acc}% em ${r.n}${stats.local ? ` <button class="pd-train-btn" data-s="${escapeHtml(r.s)}" data-t="${escapeHtml(r.t)}" onclick="_pdTrainWeak(this)">Treinar</button>` : ''}</span></div>`;
        }).join('');
    } catch (e) { console.warn('[pd] train', e); }
    return `<div class="pd-improve">
        <div class="pd-improve-h">📈 Está a melhorar?</div>
        ${trainHtml}${weekHtml}${skillHtml}${readHtml}
    </div>`;
}
// Botão 'Treinar' do bloco 'Esta semana treina': sessão só desse tópico
function _pdTrainWeak(btn) {
    const s = btn && btn.dataset && btn.dataset.s, t = btn && btn.dataset && btn.dataset.t;
    if (!s || !t) return;
    closeParentDashboard();
    setTimeout(() => { try { startSubjectSession(s, { topics: [t], bypassSeenCheck: true }); } catch (e) { showToast('Não consegui iniciar o treino desse tópico.'); } }, 150);
}
window._pdTrainWeak = _pdTrainWeak;
function openParentDashboard(remote) {
    document.getElementById('parent-dash-container')?.remove();
    const { bySubj, days, weak, total, name, year } = _parentStats(remote);
    // Mapa de disciplinas: para remoto, usa o do ano do perfil remoto.
    const SUBJ = remote
        ? ((typeof SUBJECTS_BY_YEAR !== 'undefined' && SUBJECTS_BY_YEAR[year]) || SUBJECTS || {})
        : (SUBJECTS || {});
    const subjRows = Object.keys(bySubj).sort((a, b) => bySubj[b].ans - bySubj[a].ans).map(k => {
        const s = bySubj[k];
        const meta = (SUBJ && SUBJ[k]) || { name: k, color: '#64748b', icon: 'fa-book' };
        const pct = s.ans ? Math.round((s.ok / s.ans) * 100) : 0;
        const barColor = pct >= 80 ? '#16a34a' : pct >= 60 ? '#f59e0b' : '#ef4444';
        return `<div class="pd-row">
            <div class="pd-row-head"><span class="pd-ico" style="background:${meta.color}"><i class="fas ${meta.icon}"></i></span>
              <span class="pd-name">${escapeHtml(meta.name)}</span>
              <span class="pd-pct" style="color:${barColor}">${pct}%</span></div>
            <div class="pd-bar"><span style="width:${pct}%;background:${barColor}"></span></div>
            <div class="pd-sub">${s.ok}/${s.ans} certas</div>
        </div>`;
    }).join('') || '<div class="pd-empty">Ainda sem exercícios respondidos. Quando a criança praticar, o progresso aparece aqui.</div>';
    // Últimos 7 dias — colunas com ênfase no dia de hoje
    const dVals = [], dLabels = [], dTitles = [];
    for (let i = 6; i >= 0; i--) {
        const d = new Date(); d.setDate(d.getDate() - i);
        const key = _localDayKey(d);
        const day = days[key] || { ans: 0, ok: 0 };
        const label = ['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'][d.getDay()];
        dVals.push(day.ans); dLabels.push(label);
        dTitles.push(`${label} ${key.slice(8)}/${key.slice(5, 7)}: ${day.ans} exercício${day.ans === 1 ? '' : 's'}${day.ans ? ` (${day.ok} certos)` : ''}`);
    }
    const weekChart = `<div class="pd-chart">${_pdColumnChart({ vals: dVals, labels: dLabels, titles: dTitles })}</div>`;
    const weakHtml = weak.length
        ? `<div class="pd-section-h">🎯 Pontos a reforçar (Inglês)</div><div class="pd-weak">${weak.map(w => `<span class="pd-weak-chip">${escapeHtml(w.t)}</span>`).join('')}</div>`
        : '';
    const pName = name || ((typeof activeProfile === 'function' && activeProfile()) ? activeProfile().name : '');
    const remoteTag = remote ? '<span class="pd-remote-tag">🌐 remoto</span>' : '';
    const foot = remote
        ? 'Dados sincronizados da nuvem (último backup do dispositivo da criança). Vista só de leitura.'
        : 'Vista só de leitura. Toca em "Ver outro perfil" para acompanhar outro perfil pelo código.';
    const html = `
      <div class="fullscreen" id="parent-dash-screen">
        <div class="exercise-header">
          <button class="icon-btn" aria-label="Voltar" title="Voltar" onclick="closeParentDashboard()"><i class="fas fa-arrow-left" aria-hidden="true"></i></button>
          <div style="flex:1;font-weight:700;display:flex;align-items:center;gap:8px">
            <span style="width:32px;height:32px;border-radius:8px;background:#0891b2;color:#fff;display:inline-flex;align-items:center;justify-content:center"><i class="fas fa-chart-line"></i></span>
            Estatísticas — ${escapeHtml(pName)} ${remoteTag}
          </div>
        </div>
        <div class="exercise-body">
          <div class="pd-kpis">
            <div class="pd-kpi"><div class="pd-kpi-n">${total}</div><div class="pd-kpi-l">exercícios feitos</div></div>
            <div class="pd-kpi"><div class="pd-kpi-n">${Object.keys(bySubj).length}</div><div class="pd-kpi-l">disciplinas ativas</div></div>
          </div>
          ${remote ? '' : '<button class="pd-remote-btn" onclick="openParentProfilePicker()">👥 Ver outro perfil (lista / código)</button>'}
          ${_pdDayHtml(_parentStats(remote), SUBJ)}
          ${_pdImprovementHtml(_parentStats(remote))}
          ${remote ? '' : _pdCompareHtml()}
          <div class="pd-section-h">📅 Últimos 7 dias</div>
          ${weekChart}
          <div class="pd-section-h">🔥 Constância — últimas 12 semanas</div>
          <div class="pd-chart pd-chart-heat">${_pdHeatmap(days)}</div>
          <div class="pd-section-h">📚 Desempenho por disciplina</div>
          ${subjRows}
          ${weakHtml}
          <div class="pd-foot">${foot}</div>
          ${remote ? '' : '<button class="pd-admin-link" onclick="openAdminGate()">🔐 Administrador</button>'}
        </div>
      </div>`;
    const wrap = document.createElement('div');
    wrap.id = 'parent-dash-container';
    wrap.innerHTML = html;
    document.body.appendChild(wrap); _overlayPush('parent-dash-container');
    try { const ch = wrap.querySelector('.pdd-chips'); if (ch) ch.scrollLeft = ch.scrollWidth; } catch {}
}
window.openParentDashboard = openParentDashboard;
// Seletor de perfis — lista os perfis DESTE dispositivo (state.profiles)
// para o pai escolher qual ver, mostra o código de cada um, e permite
// também ver um perfil de OUTRO dispositivo pelo código (remoto).
function openParentProfilePicker() {
    document.getElementById('parent-picker-modal')?.remove();
    const profs = (state.profiles || []);
    const rows = profs.map(p => {
        const code = p.userCode ? `<span class="pp-code">${escapeHtml(p.userCode)}</span>` : '<span class="pp-nocode">sem código</span>';
        const yr = p.year === 99 ? 'Profissional' : (p.year + 'º ano');
        const pj = JSON.stringify(p.id).replace(/"/g, '&quot;');
        return `<button class="pp-row" onclick="_parentViewLocal(${pj})">
            <span class="pp-av">${escapeHtml(p.avatar && p.avatar.emoji || '🙂')}</span>
            <span class="pp-info"><span class="pp-name">${escapeHtml(p.name || 'Perfil')}</span><span class="pp-meta">${escapeHtml(yr)} · ${code}</span></span>
            <span class="pp-go">ver →</span>
        </button>`;
    }).join('') || '<div class="pd-empty">Nenhum perfil neste dispositivo.</div>';
    const html = `
      <div class="modal" id="parent-picker-modal" style="align-items:center;padding:18px" onclick="if(event.target===this)this.remove()">
        <div class="modal-content" style="max-width:460px;border-radius:18px;overflow:hidden">
          <div style="background:linear-gradient(135deg,#0891b2,#0e7490);color:#fff;padding:18px 20px">
            <div style="font-size:1.15rem;font-weight:900">👥 Perfis neste dispositivo</div>
            <div style="font-size:0.78rem;opacity:0.92">Toca para ver o progresso de cada um</div>
          </div>
          <div class="modal-body" style="padding:16px">
            <div class="pp-list">${rows}</div>
            <button class="pd-remote-btn" style="margin-top:14px" onclick="document.getElementById('parent-picker-modal').remove();openRemoteParentDashboard()">🌐 Outro dispositivo — pelo código</button>
            <p style="text-align:center;font-size:0.72rem;color:var(--text-light);margin-top:12px">O código de cada perfil aparece também na área de Duelos/Amigos (perfil partilhável).</p>
          </div>
        </div>
      </div>`;
    document.body.insertAdjacentHTML('beforeend', html);
}
window.openParentProfilePicker = openParentProfilePicker;
function _parentViewLocal(id) {
    const p = (state.profiles || []).find(x => x.id === id);
    document.getElementById('parent-picker-modal')?.remove();
    if (!p) { showToast('Perfil não encontrado.'); return; }
    openParentDashboard({ profile: p, max: state.max });
}
window._parentViewLocal = _parentViewLocal;
// Painel de Pais REMOTO — pede o código do perfil da criança e busca o
// backup no Firestore (backups/{userCode}), mostrando o painel à distância.
async function openRemoteParentDashboard() {
    const codeRaw = prompt('Código do perfil da criança (ex: AB3K9X):');
    if (!codeRaw) return;
    const code = codeRaw.trim().toUpperCase();
    if (!/^[A-Z0-9]{4,10}$/.test(code)) { showToast('Código inválido (4–10 letras/números).'); return; }
    showToast('A procurar o progresso na nuvem…');
    try {
        const data = await fbFetchBackup(code);
        if (!data || !data.profile) { showToast('Sem dados para esse código. Confirma que o backup está ativo no dispositivo desse perfil.'); return; }
        openParentDashboard({ profile: data.profile, max: data.max });
    } catch (e) {
        console.warn('[parent] remote fetch failed', e);
        showToast('Erro ao buscar — verifica a ligação.');
    }
}
window.openRemoteParentDashboard = openRemoteParentDashboard;
// ── Overlays fullscreen com HISTÓRICO: o gesto/botão "voltar" do browser
// ou do iOS fecha o ecrã (em vez de sair da PWA). Pilha simples de ids.
const _overlayStack = [];
let _overlayIgnorePop = false;
function _overlayPush(id) {
    if (_overlayStack[_overlayStack.length - 1] === id) return; // re-render do topo
    for (let i = _overlayStack.length - 1; i >= 0; i--) { if (_overlayStack[i] === id) _overlayStack.splice(i, 1); } // nunca duplicado na pilha
    _overlayStack.push(id);
    try { history.pushState({ ep: id }, ''); } catch {}
}
function _overlayClose(id) {
    document.getElementById(id)?.remove();
    const i = _overlayStack.lastIndexOf(id);
    if (i < 0) return;
    _overlayStack.splice(i, 1);
    if (history.state && history.state.ep === id) { _overlayIgnorePop = true; try { history.back(); } catch { _overlayIgnorePop = false; } }
}
window._overlayClose = _overlayClose;
window.addEventListener('popstate', () => {
    if (_overlayIgnorePop) { _overlayIgnorePop = false; return; }
    const id = _overlayStack.pop();
    if (id) document.getElementById(id)?.remove();
});
function closeParentDashboard() {
    _overlayClose('parent-dash-container');
}
window.closeParentDashboard = closeParentDashboard;

// ============================================================
// ADMINISTRADOR — vê as estatísticas de TODOS os utilizadores com
// backup na nuvem (coleção backups/ do Firestore). Protegido por PIN
// guardado APENAS em localStorage (nunca em state.max — o max vai nos
// backups para a nuvem e o PIN vazaria).
// ============================================================
const ADMIN_PIN_KEY = 'escolaplay_admin_pin';
function openAdminGate() {
    let pin = null;
    try { pin = localStorage.getItem(ADMIN_PIN_KEY); } catch {}
    if (!pin) {
        const p1 = prompt('Primeira vez: define um PIN de administrador (mínimo 4 dígitos):');
        if (!p1 || p1.trim().length < 4) { if (p1 !== null) showToast('PIN demasiado curto (mínimo 4).'); return; }
        const p2 = prompt('Confirma o PIN:');
        if (p1 !== p2) { showToast('Os PINs não coincidem.'); return; }
        try { localStorage.setItem(ADMIN_PIN_KEY, p1.trim()); } catch {}
        showToast('PIN definido ✓ (só neste dispositivo)');
    } else {
        const t = prompt('PIN de administrador:');
        if (t === null) return;
        if (t !== pin) {
            openAdminGate._fails = (openAdminGate._fails || 0) + 1;
            if (openAdminGate._fails >= 3 && confirm('PIN errado 3 vezes. Esqueceste o PIN?\n\nOK = apagar o PIN e definir um novo (não dá acesso a mais nada — os dados ficam iguais).')) {
                try { localStorage.removeItem(ADMIN_PIN_KEY); } catch {}
                openAdminGate._fails = 0;
                showToast('PIN apagado — define um novo.');
                return openAdminGate();
            }
            showToast('PIN errado.'); return;
        }
        openAdminGate._fails = 0;
    }
    openAdminDashboard();
}
window.openAdminGate = openAdminGate;
// Lista a coleção users/ (leve: só código, nome, avatar, ano, lastSeen).
// Os BACKUPS continuam a ser lidos um a um por código (get), como sempre —
// não é preciso abrir a listagem da coleção backups nas regras.
async function _fbListUsers() {
    await _onFbReady();
    const { db } = window.__fb;
    const { collection, getDocs, query, limit } = await _fbQueryFns();
    const snap = await getDocs(query(collection(db, 'users'), limit(300)));
    const rows = [];
    snap.forEach(d => { const data = d.data() || {}; rows.push({ code: d.id, ...data }); });
    return rows;
}
function _adminLastSeenMs(row) {
    const u = row.lastSeen;
    if (u && typeof u.seconds === 'number') return u.seconds * 1000;
    if (u && typeof u.toMillis === 'function') { try { return u.toMillis(); } catch {} }
    return 0;
}
function _adminAgo(ms) {
    if (!ms) return 'sem registo';
    const days = Math.floor((Date.now() - ms) / 86400000);
    if (days <= 0) return 'hoje';
    if (days === 1) return 'ontem';
    if (days < 30) return `há ${days} dias`;
    return new Date(ms).toISOString().slice(0, 10);
}
let _adminRun = 0;
// const (não function): num script clássico, uma function de topo fica em
// window; const fica só no escopo léxico — só openAdminGate lhe chega.
const openAdminDashboard = async function () {
    const run = ++_adminRun;
    document.getElementById('admin-dash-container')?.remove();
    const wrap = document.createElement('div');
    wrap.id = 'admin-dash-container';
    wrap.innerHTML = `
      <div class="fullscreen" id="admin-dash-screen">
        <div class="exercise-header" style="background:linear-gradient(135deg,#1e293b,#334155)">
            <button class="icon-btn" aria-label="Voltar" title="Voltar" onclick="_overlayClose('admin-dash-container')"><i class="fas fa-arrow-left" aria-hidden="true"></i></button>
            <div style="flex:1;font-weight:800;color:#fff">🔐 Administração — todos os utilizadores</div>
        </div>
        <div class="exercise-body"><div class="pd-empty" id="admin-loading">⏳ A carregar os utilizadores…</div><div id="admin-body"></div></div>
      </div>`;
    document.body.appendChild(wrap); _overlayPush('admin-dash-container');
    let rows;
    try {
        rows = await _fbListUsers();
        if (run !== _adminRun) return; // outra abertura mais recente ganhou
    } catch (e) {
        console.warn('[admin] list failed', e);
        const load = document.getElementById('admin-loading');
        if (load) load.innerHTML = String(e && e.code) === 'permission-denied'
            ? '🔒 O Firestore não permite listar a coleção <b>users</b>.<br>Nas regras, troca <code>allow get</code> por <code>allow read</code> em <code>/users/{code}</code> (esta coleção só tem código, nome, avatar-emoji e ano — sem fotos nem histórico) e volta a tentar.'
            : '⚠️ Erro ao carregar da nuvem — verifica a ligação e tenta de novo.';
        return;
    }
    const load = document.getElementById('admin-loading');
    if (load) load.remove();
    const body = document.getElementById('admin-body');
    if (!body) return;
    if (!rows.length) { body.innerHTML = '<div class="pd-empty">Ainda não há utilizadores registados na nuvem. Cada perfil que ativa a partilha (Duelos/Amigos) aparece aqui.</div>'; return; }
    rows.forEach(r => { r._ms = _adminLastSeenMs(r); });
    rows.sort((a, b) => b._ms - a._ms);
    const WEEK = Date.now() - 7 * 86400000;
    const kActive = rows.filter(r => r._ms >= WEEK).length;
    window._adminRows = rows;
    const list = rows.map((r, i) => {
        // Avatar pode ser objeto {emoji} (perfis antigos) ou string de pack
        // (vampire:damon, disney3d:stitch…) — renderAvatar resolve as imagens.
        const av = r.avatar;
        const avHtml = (av && typeof av === 'object')
            ? `<span style="font-size:1.6rem;line-height:1">${escapeHtml(av.emoji || '🙂')}</span>`
            : renderAvatar(_pubAvatar(av) === '👤' && !av ? '🙂' : _pubAvatar(av), 40);
        const yr = r.year === 99 ? 'Prof.' : (r.year === 31 ? '3º (Oc.)' : (r.year ? r.year + 'º ano' : '—'));
        const fresh = r._ms >= WEEK;
        return `<button class="adm-row" onclick="_adminOpenUser(${i})">
            <span class="adm-av">${avHtml}</span>
            <span class="adm-info">
                <span class="adm-name">${escapeHtml(r.name || 'Perfil')} <span class="adm-code">${escapeHtml(r.code)}</span></span>
                <span class="adm-meta">${escapeHtml(yr)}${r.shareable === false ? ' · partilha desativada' : ''}</span>
            </span>
            <span class="adm-when ${fresh ? 'fresh' : ''}">${_adminAgo(r._ms)}</span>
        </button>`;
    }).join('');
    body.innerHTML = `
        <div class="pd-kpis">
            <div class="pd-kpi"><div class="pd-kpi-n">${rows.length}</div><div class="pd-kpi-l">utilizadores</div></div>
            <div class="pd-kpi"><div class="pd-kpi-n">${kActive}</div><div class="pd-kpi-l">ativos (7 dias)</div></div>
        </div>
        <div class="pd-section-h">👥 Utilizadores (mais recentes primeiro)</div>
        <div class="adm-list">${list}</div>
        <div class="pd-foot">Toca num utilizador para abrir as estatísticas dele (busca o backup pelo código).<br><br>ℹ️ Perfis que nunca ativaram a partilha (Duelos → perfil partilhável) não têm código nem dados na nuvem — por isso não aparecem aqui. Para acompanhares um perfil, ativa a partilha no dispositivo dele.</div>`;
};
// Ao tocar: busca o backup DESSE código (get — permitido desde sempre) e abre
// as estatísticas completas, com os gráficos todos.
async function _adminOpenUser(i) {
    const r = (window._adminRows || [])[i];
    if (!r) return;
    showToast('A procurar as estatísticas de ' + (r.name || r.code) + '…');
    try {
        const data = await fbFetchBackup(r.code);
        if (!data || !data.profile) { showToast('Este utilizador ainda não tem backup na nuvem.'); return; }
        openParentDashboard({ profile: data.profile, max: data.max });
    } catch (e) {
        console.warn('[admin] backup fetch', e);
        if (String(e && e.code) === 'permission-denied') {
            alert('🔒 As regras do Firestore não permitem LER backups por código.\n\nNa consola Firebase → Firestore → Rules, no bloco /backups/{code}, acrescenta:\n\nallow get: if true;\n\n(get lê um backup de cada vez, por código — não abre a listagem da coleção). Sem isto, nem o Administrador nem a "vista à distância" conseguem mostrar estatísticas remotas.');
        } else {
            showToast('Erro ao buscar o backup — verifica a ligação.');
        }
    }
}
window._adminOpenUser = _adminOpenUser;

// ============================================================
// MODO CURSO — isolado para disciplina english_pm
// ============================================================
// Estrutura: 14 lições agrupadas em 4 unidades. Cada lição mapeia
// exercícios existentes do pack english-pm. Progresso persistido em
// state.coursePath[subjectKey][lessonId] = {completed, accuracy, attempts, crown}.
// Crown: 0=não feita, 1=passada (≥60%), 2=boa (≥75%), 3=excelente (≥90%).
// Lock: lesson N+1 desbloqueia quando lesson N tiver crown ≥ 1.
function _getCourseConfig(subjectKey) {
    if (subjectKey === 'english_pm') return window.COURSE_ENGLISH_PM || null;
    if (subjectKey === 'english_ge') return window.COURSE_ENGLISH_GE || null;
    return null;
}
function _courseState(subjectKey) {
    state.coursePath = state.coursePath || {};
    state.coursePath[subjectKey] = state.coursePath[subjectKey] || { lessons: {} };
    return state.coursePath[subjectKey];
}
function _lessonProgress(subjectKey, lessonId) {
    const cs = _courseState(subjectKey);
    return cs.lessons[lessonId] || { completed: false, accuracy: 0, attempts: 0, crown: 0 };
}
function _isLessonUnlocked(course, lessonId) {
    const lesson = course.lessons.find(l => l.id === lessonId);
    if (lesson && lesson.unlocked) return true;
    const idx = course.lessons.findIndex(l => l.id === lessonId);
    if (idx <= 0) return true;
    const prev = course.lessons[idx - 1];
    return _lessonProgress(course.subjectKey, prev.id).crown >= 1;
}
function _crownFromAccuracy(acc) {
    if (acc >= 0.9) return 3;
    if (acc >= 0.75) return 2;
    if (acc >= 0.6) return 1;
    return 0;
}

function openCoursePath(subjectKey) {
    const course = _getCourseConfig(subjectKey);
    if (!course) { showToast('Curso indisponível'); return; }
    currentSubjectView = subjectKey;
    const sub = SUBJECTS[subjectKey];
    const cs = _courseState(subjectKey);
    const totalLessons = course.lessons.length;
    const doneLessons = course.lessons.filter(l => _lessonProgress(subjectKey, l.id).crown >= 1).length;
    const totalCrowns = course.lessons.reduce((sum, l) => sum + _lessonProgress(subjectKey, l.id).crown, 0);
    const maxCrowns = totalLessons * 3;
    const pct = Math.round((doneLessons / totalLessons) * 100);
    // Render unidade a unidade
    const unitsHtml = course.units.map((unit) => {
        const lessons = unit.lessonIds.map(id => course.lessons.find(l => l.id === id)).filter(Boolean);
        const lessonsHtml = lessons.map((l, idx) => {
            const prog = _lessonProgress(subjectKey, l.id);
            const unlocked = _isLessonUnlocked(course, l.id);
            const sideClass = idx % 2 === 0 ? 'left' : 'right';
            const stateClass = !unlocked ? 'locked' : (prog.crown >= 1 ? 'done' : 'available');
            const icon = !unlocked ? 'fa-lock'
                       : prog.crown >= 1 ? 'fa-check'
                       : 'fa-play';
            const crowns = unlocked && prog.crown > 0
                ? `<div class="course-crowns">${'★'.repeat(prog.crown)}${'☆'.repeat(3-prog.crown)}</div>`
                : '';
            const exCount = (l.exerciseIds || []).length;
            return `
              <div class="course-node ${sideClass} ${stateClass}" data-lesson="${l.id}" data-subject="${subjectKey}" role="button" tabindex="0">
                <div class="course-node-circle" style="background:${unlocked ? unit.color : '#cbd5e1'}">
                    <i class="fas ${icon}"></i>
                </div>
                <div class="course-node-label">
                    <div class="course-node-title">${escapeHtml(l.title)}</div>
                    <div class="course-node-sub">${escapeHtml(l.subtitle || '')} · ${exCount} ex</div>
                    ${crowns}
                </div>
              </div>`;
        }).join('');
        return `
          <div class="course-unit" style="--unit-color:${unit.color}">
            <div class="course-unit-header">
              <span class="course-unit-icon"><i class="fas ${unit.icon}"></i></span>
              <div>
                <div class="course-unit-title">${escapeHtml(unit.title)}</div>
                <div class="course-unit-sub">${lessons.length} lições</div>
              </div>
            </div>
            ${lessonsHtml}
          </div>`;
    }).join('');

    document.getElementById('subject-detail-container')?.remove();
    // Tutor da DISCIPLINA: usa o contexto do perfil ativo (ano + nome).
    const _profSD = (typeof activeProfile === 'function' && activeProfile()) || {};
    const _studentSD = _profSD.name || '';
    const _isEnSD = (subjectKey === 'ingles' || subjectKey === 'english_pm');
    const _tutorTitleSD = _isEnSD ? 'Falar com o Professor' : `Professor(a) de ${escapeHtml(sub.name)}`;
    const _tutorSubSD = _isEnSD
        ? 'Conversa livre · corrige-te e faz perguntas'
        : (_studentSD ? `Tira dúvidas e treina ${escapeHtml(sub.name)} contigo, ${escapeHtml(_studentSD)}` : `Tira dúvidas e treina ${escapeHtml(sub.name)} contigo`);
    const wrap = document.createElement('div');
    wrap.id = 'subject-detail-container';
    wrap.innerHTML = `
      <div class="fullscreen" id="subject-detail-screen">
        <div class="exercise-header">
          <button class="icon-btn" aria-label="Voltar" title="Voltar" onclick="closeSubjectDetail()"><i class="fas fa-arrow-left" aria-hidden="true"></i></button>
          <div style="flex:1;font-weight:700;display:flex;align-items:center;gap:8px">
            <span style="width:32px;height:32px;border-radius:8px;background:${sub.color};color:#fff;display:inline-flex;align-items:center;justify-content:center"><i class="fas ${sub.icon}"></i></span>
            ${escapeHtml(course.title)}
          </div>
          <button class="icon-btn" onclick="openCourseFreePractice('${subjectKey}')" title="Treino livre por tópico"><i class="fas fa-list"></i></button>
        </div>
        <div class="exercise-body" style="padding-bottom:80px">
          <div class="course-hero" style="background:linear-gradient(135deg,${sub.color},${sub.color}cc);color:#fff;padding:16px 18px;border-radius:16px;margin-bottom:18px;display:flex;align-items:center;gap:12px;position:relative;overflow:hidden">
            <span class="hero-sparkle" style="top:14%;left:30%"></span>
            <span class="hero-sparkle" style="top:60%;left:12%;animation-delay:0.8s"></span>
            <span class="hero-sparkle" style="top:24%;right:38%;animation-delay:1.4s"></span>
            <div style="flex:1;min-width:0;position:relative;z-index:1">
              <div style="font-size:0.78rem;opacity:0.85;font-weight:700;text-transform:uppercase;letter-spacing:0.5px">O teu caminho</div>
              <div style="font-size:1.4rem;font-weight:800;margin:4px 0"><span class="course-hero-count" data-target="${doneLessons}">${doneLessons}</span> / ${totalLessons} lições</div>
              <div style="height:8px;background:rgba(255,255,255,0.25);border-radius:999px;overflow:hidden;margin:8px 0 4px">
                <div style="height:100%;width:${pct}%;background:#fff;border-radius:999px;transition:width 0.5s"></div>
              </div>
              <div style="font-size:0.82rem;opacity:0.9">⭐ ${totalCrowns} / ${maxCrowns} coroas</div>
            </div>
            <div class="course-mascot-host" id="course-mascot" style="position:relative;z-index:1"></div>
          </div>
          <div class="tutor-card" data-tutor-subject="${escapeHtml(subjectKey)}" data-tutor-name="${escapeHtml(sub.name)}" onclick="openTutorFromSubjectCard(this)">
            <div class="tutor-card-icon"><i class="fas fa-chalkboard-user"></i></div>
            <div class="tutor-card-text">
              <div class="tutor-card-title">${_tutorTitleSD}</div>
              <div class="tutor-card-sub">${_tutorSubSD}</div>
            </div>
            <i class="fas fa-microphone tutor-card-mic"></i>
          </div>
          ${unitsHtml}
        </div>
      </div>`;
    document.body.appendChild(wrap);
    // Event delegation no wrap inteiro — apanha clicks em qualquer filho do
    // course-node (icone, titulo, subtitulo) sem depender de pointer-events.
    wrap.addEventListener('click', (ev) => {
        const node = ev.target.closest('.course-node');
        if (!node) return;
        if (node.classList.contains('locked')) {
            showToast('Lição trancada — completa a anterior primeiro');
            return;
        }
        const sk = node.getAttribute('data-subject');
        const lid = node.getAttribute('data-lesson');
        if (!sk || !lid) { showToast('Sem dados na lição: ' + (lid || '?')); return; }
        startCourseLesson(sk, lid);
    });
    // Mascote no hero — usa o avatar do perfil (Disney/etc.) se for imagem,
    // senão o Pip SVG. Fala ao tocar.
    const mascotHost = wrap.querySelector('#course-mascot');
    if (mascotHost && window.Mascot) {
        try {
            window._courseMascot = window.Mascot.create(mascotHost, {
                size: 78,
                avatarHtml: _mascotAvatarHtml(72),
                talkOnTap: true,
                phrases: [
                    { text: "Let's practise! You've got this.", lang: 'en-US' },
                    { text: "Ready to lead in English?", lang: 'en-US' },
                    { text: "One lesson at a time. Keep going!", lang: 'en-US' },
                    { text: "Toca numa lição e vamos a isto!", lang: 'pt-PT' }
                ]
            });
        } catch {}
    }
    // Reveal premium com GSAP (física de mola). Degrada para CSS se ausente.
    if (window.gsap) {
        wrap.classList.add('gsap-on');
        const g = window.gsap;
        const hero = wrap.querySelector('.course-hero');
        const mascot = wrap.querySelector('#course-mascot');
        const nodes = wrap.querySelectorAll('.course-node');
        const units = wrap.querySelectorAll('.course-unit');
        if (hero) g.from(hero, { y: -22, opacity: 0, duration: 0.5, ease: 'back.out(1.6)' });
        if (mascot) g.from(mascot, { scale: 0, opacity: 0, duration: 0.65, ease: 'back.out(2.2)', delay: 0.35, transformOrigin: 'bottom center' });
        g.from(units, { opacity: 0, duration: 0.4, stagger: 0.08, delay: 0.1, clearProps: 'opacity' });
        g.from(nodes, { y: 26, opacity: 0, duration: 0.5, ease: 'back.out(1.5)', stagger: 0.05, delay: 0.18, clearProps: 'transform,opacity' });
        // Contador animado nas lições do hero
        const counter = wrap.querySelector('.course-hero-count');
        if (counter) {
            const target = parseInt(counter.dataset.target, 10) || 0;
            const obj = { v: 0 };
            g.to(obj, { v: target, duration: 0.9, delay: 0.3, ease: 'power2.out',
                onUpdate: () => { counter.textContent = Math.round(obj.v); } });
        }
    }
}
window.openCoursePath = openCoursePath;

function openCourseFreePractice(subjectKey) {
    // Fallback: usa o renderizador original (lista de tópicos) sem o intercept.
    if (subjectKey === 'english_pm' && window.COURSE_ENGLISH_PM) {
        const prev = window.COURSE_ENGLISH_PM;
        delete window.COURSE_ENGLISH_PM;
        document.getElementById('subject-detail-container')?.remove();
        openSubjectDetail(subjectKey);
        window.COURSE_ENGLISH_PM = prev;
        return;
    }
    if (subjectKey === 'english_ge' && window.COURSE_ENGLISH_GE) {
        const prev = window.COURSE_ENGLISH_GE;
        delete window.COURSE_ENGLISH_GE;
        document.getElementById('subject-detail-container')?.remove();
        openSubjectDetail(subjectKey);
        window.COURSE_ENGLISH_GE = prev;
        return;
    }
    openSubjectDetail(subjectKey);
}
window.openCourseFreePractice = openCourseFreePractice;

async function startCourseLesson(subjectKey, lessonId) {
    console.log('[course] startCourseLesson', subjectKey, lessonId);
    const course = _getCourseConfig(subjectKey);
    if (!course) { showToast('Curso não disponível'); return; }
    const lesson = course.lessons.find(l => l.id === lessonId);
    if (!lesson) { showToast('Lição não encontrada: ' + lessonId); return; }
    if (!_isLessonUnlocked(course, lessonId)) { showToast('Completa a lição anterior primeiro'); return; }
    // Resolver IDs → exercícios. Suporta exercícios injetados por secret packs
    // (english-pm em EXERCISES_BY_YEAR[99]; english-ge no ano do perfil) e o
    // EXERCISES global. NÃO mexe noutros anos.
    const byId = {};
    const _profYr = (typeof activeProfile === 'function' && activeProfile() && activeProfile().year) || null;
    try { if (_profYr) await loadYearExtras(_profYr); } catch {}
    const _pools = [];
    if (window.EXERCISES_BY_YEAR) {
        if (Array.isArray(window.EXERCISES_BY_YEAR[99])) _pools.push(window.EXERCISES_BY_YEAR[99]);
        if (_profYr && Array.isArray(window.EXERCISES_BY_YEAR[_profYr])) _pools.push(window.EXERCISES_BY_YEAR[_profYr]);
    }
    for (const pool of _pools) for (const e of pool) byId[e.id] = e;
    for (const e of (typeof EXERCISES !== 'undefined' ? EXERCISES : [])) if (e.s === subjectKey) byId[e.id] = e;
    const items = lesson.exerciseIds.map(id => byId[id]).filter(Boolean);
    console.log('[course] resolved items:', items.length, '/ expected:', lesson.exerciseIds.length);
    if (items.length === 0) {
        const _pk = subjectKey === 'english_ge' ? 'english-ge' : 'english-pm';
        showToast('Sem exercícios — ativa o pack ' + _pk + ' no perfil');
        return;
    }
    currentSession = {
        items, idx: 0, correct: 0, wrong: 0, xp: 0, streak: 0, results: [],
        isDaily: false, subject: subjectKey,
        courseLesson: { subjectKey, lessonId },
        startedAt: Date.now()
    };
    // Fechar o ecra do caminho — senao o exercise-screen abre por baixo e
    // os exercicios so aparecem quando o utilizador sai do ecra do curso.
    document.getElementById('subject-detail-container')?.remove();
    openExerciseScreen();
    renderQuestion();
}
window.startCourseLesson = startCourseLesson;

// Chamado no fim da sessão (showSummary) — só ativa se courseLesson estiver presente
function _recordCourseLessonResult(session) {
    if (!session || !session.courseLesson) return;
    const { subjectKey, lessonId } = session.courseLesson;
    const total = (session.items || []).length;
    if (total === 0) return;
    const correct = session.correct || 0;
    const acc = correct / total;
    const cs = _courseState(subjectKey);
    const prev = cs.lessons[lessonId] || { completed: false, accuracy: 0, attempts: 0, crown: 0 };
    const newCrown = _crownFromAccuracy(acc);
    cs.lessons[lessonId] = {
        completed: prev.completed || newCrown >= 1,
        accuracy: Math.max(prev.accuracy || 0, acc),
        attempts: (prev.attempts || 0) + 1,
        crown: Math.max(prev.crown || 0, newCrown),
        lastAt: Date.now()
    };
    saveState();
}

// Abreviaturas curtas das disciplinas para o calendario de testes (cabem em
// celulas pequenas, melhor que so um ponto colorido).
const SUBJECT_SHORT = {
    portugues:   'Por',
    matematica:  'Mat',
    estudo_meio: 'EM',
    ingles:      'Ing',
    ciencias:    'CN',
    hgp:         'HGP',
    historia:    'His',
    quimica:     'Quí'
};
function subjectShortLabel(key) {
    return SUBJECT_SHORT[key] || (key || '?').slice(0, 3);
}

// ========== TESTS ==========
let _testsCalCursor = null; // 'YYYY-MM' do mês actualmente mostrado

function renderTestsCalendar() {
    const wrap = document.getElementById('tests-calendar');
    if (!wrap) return;
    const today = new Date();
    const todayY = today.getFullYear();
    const todayM = today.getMonth() + 1;
    const todayD = today.getDate();
    const todayStrFmt = `${todayY}-${String(todayM).padStart(2,'0')}-${String(todayD).padStart(2,'0')}`;
    if (!_testsCalCursor) {
        _testsCalCursor = `${todayY}-${String(todayM).padStart(2,'0')}`;
    }
    const [yr, mo] = _testsCalCursor.split('-').map(Number);
    const firstOfMonth = new Date(yr, mo - 1, 1);
    const lastOfMonth = new Date(yr, mo, 0);
    const daysInMonth = lastOfMonth.getDate();
    // PT: semana comeca a Segunda. Converte getDay() (0=Dom..6=Sab) para (0=Seg..6=Dom).
    const firstWeekdayPT = (firstOfMonth.getDay() + 6) % 7;
    const monthNames = ['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
    // Dias do mês com testes (agrupados por data → array de testes)
    const byDate = {};
    (state.tests || []).forEach(t => {
        if (!byDate[t.date]) byDate[t.date] = [];
        byDate[t.date].push(t);
    });
    // Calendario completo Seg-Dom (fins de semana em cinza claro).
    const dow = ['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'];
    const cells = [];
    for (let i = 0; i < firstWeekdayPT; i++) cells.push('<div class="tests-cal-cell empty"></div>');
    for (let d = 1; d <= daysInMonth; d++) {
        const dayDate = new Date(yr, mo - 1, d);
        const isWeekend = dayDate.getDay() === 0 || dayDate.getDay() === 6;
        const dateStr = `${yr}-${String(mo).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
        const ts = byDate[dateStr] || [];
        const isToday = dateStr === todayStrFmt;
        const hasTests = ts.length > 0;
        // Chips com sigla + cor da disciplina (max 3 visiveis, +N para overflow)
        const visible = ts.slice(0, 3);
        const chipsHtml = visible.map(t => {
            const sub = SUBJECTS[t.subject];
            const done = t.done ? ' is-done' : '';
            const label = subjectShortLabel(t.subject);
            return `<span class="tests-cal-chip${done}" style="background:${sub?.color || '#6b7280'}">${label}</span>`;
        }).join('');
        const overflow = ts.length > 3 ? `<span class="tests-cal-chip-more">+${ts.length - 3}</span>` : '';
        const tooltipNames = ts.map(t => (SUBJECTS[t.subject]?.name || t.subject)).join(', ');
        const cls = ['tests-cal-cell'];
        if (isToday) cls.push('is-today');
        if (hasTests) cls.push('has-tests');
        if (isWeekend) cls.push('is-weekend');
        const handler = hasTests ? `onclick="scrollToTestOn('${dateStr}')"` : '';
        cells.push(`<button type="button" class="${cls.join(' ')}" ${handler} ${hasTests ? `title="${tooltipNames}"` : ''}>
            <span class="tests-cal-day">${d}</span>
            ${hasTests ? `<span class="tests-cal-chips">${chipsHtml}${overflow}</span>` : ''}
        </button>`);
    }
    wrap.innerHTML = `
        <div class="tests-cal">
            <div class="tests-cal-header">
                <button type="button" class="tests-cal-nav" onclick="shiftTestsCal(-1)" aria-label="Mês anterior"><i class="fas fa-chevron-left"></i></button>
                <div class="tests-cal-title">${monthNames[mo-1]} ${yr}</div>
                <button type="button" class="tests-cal-nav" onclick="shiftTestsCal(1)" aria-label="Mês seguinte"><i class="fas fa-chevron-right"></i></button>
            </div>
            <div class="tests-cal-grid">
                ${dow.map(d => `<div class="tests-cal-dow">${d}</div>`).join('')}
                ${cells.join('')}
            </div>
        </div>
    `;
}
function shiftTestsCal(delta) {
    const [yr, mo] = (_testsCalCursor || '').split('-').map(Number);
    const d = new Date(yr || new Date().getFullYear(), (mo || (new Date().getMonth()+1)) - 1 + delta, 1);
    _testsCalCursor = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
    renderTestsCalendar();
}
window.shiftTestsCal = shiftTestsCal;
function scrollToTestOn(dateStr) {
    const ts = (state.tests || []).filter(t => t.date === dateStr);
    if (ts.length === 0) return;
    const firstId = ts[0].id;
    const el = document.querySelector(`.test-item[data-test-id="${firstId}"]`);
    if (el) {
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        el.classList.add('test-flash');
        setTimeout(() => el.classList.remove('test-flash'), 1500);
    } else {
        const list = document.getElementById('tests-list');
        if (list) list.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
}
window.scrollToTestOn = scrollToTestOn;

function renderTests() {
    renderTestsCalendar();
    const list = document.getElementById('tests-list');
    const today = todayStr();
    const sorted = [...state.tests].sort((a, b) => a.date.localeCompare(b.date));
    if (sorted.length === 0) {
        list.innerHTML = `<p class="muted" style="text-align:center;padding:20px">Sem testes agendados. Adiciona um para começares a receber lembretes.</p>`;
        return;
    }
    list.innerHTML = sorted.map(t => {
        const sub = SUBJECTS[t.subject];
        const days = daysBetween(today, t.date);
        const past = days < 0;
        let cls = 'future';
        if (t.done) cls = 'done';
        else if (past) cls = 'done';
        else if (days <= 2) cls = 'urgent';
        else if (days <= 5) cls = 'soon';
        const daysLabel = t.done ? 'Feito' : past ? `${-days}d atrás` : days === 0 ? 'Hoje!' : days === 1 ? 'Amanhã' : `em ${days}d`;
        const topicsLabel = (t.topics && t.topics.length) ? `${t.topics.length} tópicos: ${t.topics.slice(0, 3).join(', ')}${t.topics.length > 3 ? '…' : ''}` : 'todos os tópicos ativos';
        const seenCount = (t.seenEx || []).length;
        const seenLabel = seenCount > 0 ? `<div style="font-size:0.72rem;color:#f472b6;font-weight:600;margin-top:3px">📚 ${seenCount} pergunta${seenCount === 1 ? '' : 's'} vista${seenCount === 1 ? '' : 's'}</div>` : '';
        // Pílulas de nota objetivo / nota obtida. A nota obtida muda de cor
        // conforme bate o objetivo — feedback visual claro.
        const gradePills = [];
        if (t.targetGrade != null) {
            gradePills.push(`<span class="test-grade-pill test-grade-target" title="Nota objetivo">🎯 ${t.targetGrade}</span>`);
        }
        if (t.actualGrade != null) {
            const hit = t.targetGrade != null && t.actualGrade >= t.targetGrade;
            const cls2 = hit ? 'test-grade-hit' : (t.targetGrade != null ? 'test-grade-miss' : 'test-grade-atual');
            gradePills.push(`<span class="test-grade-pill ${cls2}" title="Nota obtida">${hit ? '✓' : '📝'} ${t.actualGrade}</span>`);
        }
        const gradeLabel = gradePills.length > 0 ? `<div class="test-grade-row">${gradePills.join('')}</div>` : '';
        return `
            <div class="test-item ${cls}" data-test-id="${t.id}">
                <div class="test-item-icon" style="background:${sub?.color || '#6b7280'}"><i class="fas ${sub?.icon || 'fa-book'}"></i></div>
                <div class="test-item-body">
                    <div class="test-item-subject">${sub?.name || t.subject}</div>
                    <div class="test-item-date">${formatDatePT(t.date)} · ${daysLabel}</div>
                    <div class="test-item-note">${topicsLabel}${t.note ? ` · ${t.note}` : ''}</div>
                    ${gradeLabel}
                    ${seenLabel}
                </div>
                <div class="test-item-actions">
                    ${!t.done ? `<button class="practice" title="Treinar para este teste" onclick="startTestPrep('${t.id}')"><i class="fas fa-dumbbell"></i></button>` : ''}
                    ${!t.done ? `<button class="practice" style="background:linear-gradient(135deg,#f472b6,#f472b6);color:#fff" title="Treino MAX (IA) para este teste" onclick="startMaxForTest('${t.id}')"><i class="fas fa-wand-magic-sparkles"></i></button>` : ''}
                    <button onclick="editTest('${t.id}')" title="Editar" aria-label="Editar"><i class="fas fa-pen" aria-hidden="true"></i></button>
                    <button class="del" onclick="deleteTest('${t.id}')" title="Apagar" aria-label="Apagar"><i class="fas fa-trash" aria-hidden="true"></i></button>
                </div>
            </div>
        `;
    }).join('');
}

function openAddTestModal(testId = null) {
    pendingTestId = testId;
    document.getElementById('test-modal-title').textContent = testId ? 'Editar teste' : 'Adicionar teste';
    const sel = document.getElementById('test-subject');
    sel.innerHTML = Object.entries(SUBJECTS).map(([k, s]) => `<option value="${k}">${s.fullName || s.name}</option>`).join('');
    const today = new Date();
    today.setDate(today.getDate() + 7);
    const defaultDate = `${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;
    if (testId) {
        const t = state.tests.find(x => x.id === testId);
        if (t) {
            sel.value = t.subject;
            document.getElementById('test-date').value = t.date;
            document.getElementById('test-note').value = t.note || '';
            document.getElementById('test-target-grade').value = (t.targetGrade != null) ? t.targetGrade : '';
            document.getElementById('test-atual-grade').value = (t.actualGrade != null) ? t.actualGrade : '';
        }
    } else {
        sel.value = Object.keys(SUBJECTS)[0];
        document.getElementById('test-date').value = defaultDate;
        document.getElementById('test-note').value = '';
        document.getElementById('test-target-grade').value = '';
        document.getElementById('test-atual-grade').value = '';
    }
    renderTestTopicsPicker();
    sel.onchange = renderTestTopicsPicker;
    document.getElementById('test-modal').style.display = 'flex';
}

