// Deteta se o que o utilizador disse corresponde a uma frase de reunião
// que treinou (skill Meetings). Guarda-a para dar crédito no debrief —
// fecha o ciclo "treinas a frase → usa-la numa reunião a sério".
function _tutorTrackMeetingUse(said) {
    if (!tutorState || !tutorState._roleplay) return;
    if (typeof _TUTOR_MEETING_PHRASES === 'undefined') return;
    const saidW = normalize(said).replace(/[^a-z0-9\s']/g, '').split(/\s+/).filter(w => w.length > 2);
    if (saidW.length < 3) return; // ignora respostas muito curtas
    tutorState._rpUsedPhrases = tutorState._rpUsedPhrases || [];
    for (const cat of _TUTOR_MEETING_PHRASES) {
        for (const p of cat.phrases) {
            // conta como "usada" se ≥70% das palavras-chave da frase treinada
            // aparecem no que o utilizador disse (não precisa de ser literal).
            if (_tutorWordMatch(said, p.en) >= 0.7) {
                if (!tutorState._rpUsedPhrases.some(u => u.en === p.en)) {
                    tutorState._rpUsedPhrases.push({ en: p.en, cat: cat.label });
                }
                return;
            }
        }
    }
}
function _tutorHandleInput(said) {
    if (!tutorState) return;
    _tutorAddYou(said);
    _tutorTrackMeetingUse(said);
    // Plano: responder no chat fecha o passo das skills "de conversa".
    try { _tutorPlanComplete(TUTOR_PLAN_CHAT_SKILLS); } catch {}
    // Em modo "treino do erro": valida a repetição antes de prosseguir
    if (tutorState.drill) {
        const d = tutorState.drill;
        if (_tutorWordMatch(said, d.expected) >= 0.55) {
            tutorState.drill = null;
            const cont = d.pendingReply ? (' ' + d.pendingReply) : '';
            _tutorAddTutor('Perfect!' + cont, '', '', true);
        } else {
            // Máximo 2 tentativas falhadas — depois a conversa segue em vez de
            // prender o utilizador num loop de "Almost — say it like this".
            d.tries = (d.tries || 0) + 1;
            if (d.tries >= 2) {
                tutorState.drill = null;
                const cont = d.pendingReply ? (' ' + d.pendingReply) : '';
                _tutorAddTutor("Good effort — we'll come back to that one. Let's keep going!" + cont, '', '', true);
            } else {
                _tutorAddTutor(`Almost — say it like this: ${d.expected}`, '', '', true);
            }
        }
        return;
    }
    _tutorRespond(said);
}

async function _tutorRespond(userText) {
    const bar = document.getElementById('tutor-bar');
    if (bar) bar.innerHTML = `<div class="tutor-thinking"><span class="tts-spinner"></span> O professor está a pensar…</div>`;
    const hist = tutorState.history.slice(-8).map(h => `${h.role === 'you' ? 'Student' : 'Tutor'}: ${h.text}`).join('\n');
    const rp = tutorState._roleplay;
    const replyInstr = rp
        ? `${rp.persona}'s in-character response in natural spoken business English (max 30 words), moving the meeting forward and pushing the student toward the objective ("${rp.objective}"), ending with a question or prompt. Stay fully in character as ${rp.persona}.`
        : `ONE short snappy English sentence to continue the conversation (max 16 words), ending with a brief question.`;
    const _cefrLv = (typeof _tutorTargetLevel === 'function') ? _tutorTargetLevel() : 'B2';
    const _cefrNx = { A2: 'B1', B1: 'B2', B2: 'C1', C1: 'C2', C2: 'C2' }[_cefrLv] || 'C1';
    const persona = rp
        ? `You are role-playing as ${rp.persona}, ${rp.personaRole}, in a "${rp.label}" work meeting (SAP project at Sonae) with a Portuguese Project Manager (${_cefrLv}→${_cefrNx}) practising business English. In the conversation below, "Tutor" lines are YOU (${rp.persona}). Stay fully in character, but STILL correct the student's English in the JSON fields. Pitch your language at ${_cefrLv} level, stretching gently toward ${_cefrNx}.`
        : `You are a snappy, encouraging English tutor for a Portuguese Project Manager (${_cefrLv}→${_cefrNx}) preparing to lead SAP/consulting meetings. Pitch your language at ${_cefrLv} level, stretching gently toward ${_cefrNx}.`;
    const _subjT = tutorState && tutorState.subject;
    const _subjectMode = !!(_subjT && !_subjT.isEnglish);
    const prompt = _subjectMode
        ? `Tu és Professor(a) de ${_subjT.name}, especialista em ${_subjT.name} para o ${_subjT.year}.º ano em Portugal (currículo AE 2018, DGE/ME). Estás a ajudar ${_subjT.studentName ? 'a aluna/aluno ' + _subjT.studentName : 'a aluna/aluno'}. Trata-a/o pelo nome com naturalidade quando fizer sentido. Usa SEMPRE Português Europeu (Portugal — NUNCA brasileiro), linguagem clara, didática e adequada à idade. Encorajador e paciente. À medida que a aluna/aluno fala sobre a matéria, exploras o que está a perceber e sugeres o próximo passo (rever conceito, fazer um exercício, ou aprofundar um tópico).

Conversa até agora:
${hist}

A aluna/aluno disse: "${userText}"

Devolve JSON ESTRITO (em Português Europeu, Portugal):
1) "corrected": versão clarificada/correta SÓ se houver erro conceptual/factual ou Português pouco claro. "" se já está bem.
2) "errorType": rótulo curto em PT-PT do tipo de erro (ex.: "Conceito", "Cálculo", "Comunicação", "Vocabulário"). "" se sem erro.
3) "explanation": explicação clara em PT-PT (40-70 palavras), ao nível do ${_subjT.year}.º ano.
4) "tip": dica PT-PT curta (máx 12 palavras).
5) "reply": UMA frase curta em PT-PT a continuar a conversa, encorajadora, terminando com uma pergunta ou sugestão (próximo passo: rever, exercícios, aprofundar).
6) "lessonTitle": título curto do tópico/conceito de ${_subjT.name} em causa NESTA conversa (SEMPRE preenches — é o que a aluna/aluno está a explorar agora, mesmo sem erro; ex.: "Subtração até 20", "Frações", "Comprimentos").
7) "points": 2-4 {form, use} explicando regra/conceito (form = ideia/fórmula/termo, use = quando/como aplicar, em PT-PT). [] se sem erro.
8) "examples": 2-3 {wrong, right, note} com erro típico vs correção (em PT-PT). [] se sem erro.
9) "fluencyHelp": se faltou vocabulário técnico/concetual, sugere termos {"want":"o que queria dizer (PT-PT)","phrases":[{"en":"termo correto","pt":"o que significa"}],"connectors":[],"topic":"breve tópico"}. {} se está bem.

{"corrected":"...","errorType":"...","explanation":"...","tip":"...","reply":"...","lessonTitle":"...","points":[{"form":"...","use":"..."}],"examples":[{"wrong":"...","right":"...","note":"..."}],"fluencyHelp":{}}`
        : `${persona}

Conversation so far:
${hist}

The student just said (transcribed from speech): "${userText}"

Return STRICT JSON:
1) "corrected": the student's sentence rewritten with correct grammar/verb tenses/natural wording. "" if already correct.
2) "errorType": short label of the MAIN error category, in ENGLISH grammar terminology (e.g. "Past Simple", "Prepositions", "Connectors", "Articles", "Word order", "Subject-verb agreement", "Vocabulary"). "" if correct.
3) "explanation": a clear lesson in EUROPEAN PORTUGUESE (Portugal, never Brazilian) explaining the rule and why it was wrong. 40-70 words. Teach the concept properly. Keep all grammar term names in ENGLISH (write "Simple Past", "Present Perfect", never "passado simples").
4) "tip": ultra-short PT-PT tip, max 12 words.
5) "reply": ${replyInstr}
6) "lessonTitle": short grammar rule title (e.g. "Work ON vs. work ABOUT", "Past Simple vs. Present Perfect"). "" if correct.
7) "points": array of 2-4 objects {form, use} mapping the whole rule — each form/word and WHEN to use it, in PT-PT. E.g. for articles: [{"form":"a / an","use":"algo novo ou não específico"},{"form":"the","use":"algo específico ou já mencionado"},{"form":"(sem artigo)","use":"ideias gerais, plurais, incontáveis"}]. "form" stays in English, "use" in PT-PT. [] if correct.
8) "examples": array of 2-3 objects {wrong,right,note} showing the rule (English wrong/right, note max 8 words PT-PT). "wrong" must be genuinely incorrect and DIFFERENT from "right". [] if correct.
9) "fluencyHelp": Look BEYOND grammar at WHAT the student is trying to communicate. If they struggled with vocabulary or fluency — used a Portuguese word, left a word out, described a word instead of naming it, used unnatural/non-fluent phrasing, or was missing linking words (connectors) — help them say it better and more fluently. Object: {"want":"what they were trying to express, PT-PT short","phrases":[{"en":"natural English word/phrase","pt":"PT-PT meaning"}],"connectors":["useful linking words for this idea, if relevant"],"topic":"short lesson topic in ENGLISH (vocabulary/Connectors/grammar) to drill this gap"}. Use {} if they expressed themselves naturally with no lexical/connector/fluency gap.
10) "pronunciationTips": Optional array of 0-3 objects {word, hint} for English words that are commonly mispronounced by Portuguese speakers AND appear in this sentence. Examples of typical traps to focus on: "though" (silent 'gh'), "thought" (th + ought), "schedule" (UK: 'shed-yool' / US: 'sked-jool'), "vegetable" (3 syllables, not 4), "Wednesday" (silent 'd'), "comfortable" (3 syllables: 'KUMF-ter-bul'), "iron" (silent 'r' in UK, 'EYE-urn' in US), "queue" (sounds like 'cue'), "chaos" (KAY-oss), "epitome" (4 syllables). "hint" is in PT-PT, max 10 words, with the phonetic approximation in caps. Use [] if no notable traps in the sentence.

{"corrected":"...","errorType":"...","explanation":"...","tip":"...","reply":"...","lessonTitle":"...","points":[{"form":"...","use":"..."}],"examples":[{"wrong":"...","right":"...","note":"..."}],"fluencyHelp":{},"pronunciationTips":[]}`;
    try {
        const { text } = await callClaudeAPI(prompt, 1100, true);
        if (!tutorState) return;
        const p = _extractJSON(text) || {};
        const corrected0 = (p.corrected || '').trim();
        const errorType = (p.errorType || '').trim();
        const explanation = (p.explanation || '').trim();
        const tip = (p.tip || '').trim();
        let reply = (p.reply || '').trim();
        const lessonTitle = (p.lessonTitle || '').trim();
        const points = Array.isArray(p.points) ? p.points.slice(0, 4) : [];
        const examples = Array.isArray(p.examples) ? p.examples.slice(0, 3) : [];
        const fluencyHelp = (p.fluencyHelp && typeof p.fluencyHelp === 'object' && !Array.isArray(p.fluencyHelp)) ? p.fluencyHelp : {};
        // Bug histórico: pronunciationTips era pedido no prompt e renderizado em
        // _tutorFluidCorrection, mas NUNCA extraído nem propagado — cartão
        // de pronúncia nunca aparecia. Agora é extraído e enviado adiante.
        const pronunciationTips = Array.isArray(p.pronunciationTips) ? p.pronunciationTips.slice(0, 3) : [];
        if (!reply) reply = _subjectMode ? 'Entendido. Conta-me mais.' : "Got it. Tell me more?";
        let corrected = corrected0;
        if (corrected && _sameUtterance(corrected, userText)) corrected = '';
        if (corrected) {
            tutorState._pending = { said: userText, corrected, errorType, explanation, tip, reply, lessonTitle, points, examples, pronunciationTips };
            _tutorFluidCorrection(tutorState._pending);
        } else {
            _tutorAddTutor(reply, '', tip, true);
            // Modo-disciplina: oferece sempre LIÇÃO completa + EXERCÍCIOS sobre o tópico em conversa.
            if (_subjectMode && lessonTitle) {
                const _chat = document.getElementById('tutor-chat');
                if (_chat) _chat.insertAdjacentHTML('beforeend', `
                  <div class="tutor-row them"><div class="tutor-bubble-av">🎯</div>
                    <div class="tutor-chat-prac">
                      <div class="tutor-chat-prac-h">Próximo passo para "${escapeHtml(lessonTitle)}":</div>
                      <div class="tutor-chat-prac-btns">
                        <button class="tutor-lbtn" data-topic="${escapeHtml(lessonTitle)}" onclick="_tutorChatLessonBtn(this)"><i class="fas fa-book-open"></i> Aprofundar (lição)</button>
                        <button class="tutor-lbtn prac" data-topic="${escapeHtml(lessonTitle)}" onclick="_tutorChatPracticeBtn(this)"><i class="fas fa-dumbbell"></i> Praticar 3 exercícios</button>
                      </div>
                    </div>
                  </div>`);
                if (typeof _tutorScroll === 'function') _tutorScroll();
            }
        }
        _tutorRenderFluencyHelp(fluencyHelp);
    } catch (e) {
        console.warn('[tutor] failed', e);
        if (tutorState) {
            const _fallbackEN = "Sorry, I didn't catch that. Say it again?";
            const _fallbackPT = 'Desculpa, não percebi. Podes repetir?';
            _tutorAddTutor(_subjectMode ? _fallbackPT : _fallbackEN, '', '', true);
        }
    }
}
