    if (tutorState) { tutorState._practiceReply = null; tutorState._pq = null; tutorState._reviewingCard = null; }
    _tutorAddTutor(`Boa! Acabámos a prática 🎉${consolMsg}${reply ? ' ' + reply : ''}`, '', '', true);
