function _sysSpeak(text, lang, cbs) {
    cbs = cbs || {};
    if (!('speechSynthesis' in window)) { cbs.onEnd && cbs.onEnd(); return; }
    try {
        const synth = window.speechSynthesis;
        // Só cancela se houver algo a tocar (cancelar a meio de um gesto e
        // depois falar dropa a fala em iOS). resume() desbloqueia se pausado.
        try { if (synth.speaking || synth.pending) synth.cancel(); synth.resume(); } catch {}
        const u = new SpeechSynthesisUtterance(text);
        u.lang = lang || 'en-US';
        u.rate = /^en/i.test(u.lang) ? 1.05 : 0.96;
        u.pitch = 1.0;
        const v = /^en/i.test(u.lang) ? _pickENVoice(u.lang) : (typeof _pickPTVoice === 'function' ? _pickPTVoice() : null);
        if (v) u.voice = v;
        u.onstart = () => cbs.onStart && cbs.onStart();
        u.onend = () => cbs.onEnd && cbs.onEnd();
        u.onerror = () => cbs.onEnd && cbs.onEnd();
        // SÍNCRONO — tem de ser no mesmo instante do toque para o iOS deixar tocar
        synth.speak(u);
    } catch { cbs.onEnd && cbs.onEnd(); }
}

// Indicador "a processar voz…" enquanto o Gemini gera o audio (so aparece
// se demorar >220ms — audio em cache nao faz piscar o spinner).
let _ttsLoadingTimer = null;
function _ttsLoadingShow() {
    _ttsLoadingClear();
    _ttsLoadingTimer = setTimeout(() => {
        if (document.getElementById('tts-loading')) return;
        const el = document.createElement('div');
        el.id = 'tts-loading';
        el.className = 'tts-loading';
        el.innerHTML = '<span class="tts-spinner"></span> A processar voz…';
        document.body.appendChild(el);
    }, 220);
}
function _ttsLoadingClear() {
    if (_ttsLoadingTimer) { clearTimeout(_ttsLoadingTimer); _ttsLoadingTimer = null; }
    document.getElementById('tts-loading')?.remove();
}

// Desbloqueio de áudio em iOS: no 1.º toque do utilizador, fala uma
// utterance silenciosa para "acordar" o motor de voz (depois disto, falar
// programaticamente passa a funcionar de forma mais fiável).
let _speechUnlocked = false;
function _unlockSpeechOnce() {
    if (_speechUnlocked) return;
    _speechUnlocked = true;
    // Cria/resumir o AudioContext do tutor JÁ (estamos num gesto real): assim
    // fica 'running' e a deteção de silêncio das gravações mãos-livres funciona
    // no iOS, mesmo quando arrancam fora de um toque.
    try { if (typeof _tutorGetCtx === 'function') _tutorGetCtx(); } catch {}
    try {
        if ('speechSynthesis' in window) {
            const u = new SpeechSynthesisUtterance('​');
            u.volume = 0;
            window.speechSynthesis.speak(u);
        }
    } catch {}
    // Desbloquear o elemento de áudio com um WAV silencioso curtinho
    try {
        const a = _getTtsAudioEl();
        a.src = 'data:audio/wav;base64,UklGRiQAAABXQVZFZm10IBAAAAABAAEARKwAAIhYAQACABAAZGF0YQAAAAA=';
        const p = a.play();
        if (p && p.then) p.then(() => { try { a.pause(); a.currentTime = 0; } catch {} }).catch(() => {});
    } catch {}
}
if (typeof document !== 'undefined') {
    document.addEventListener('pointerdown', _unlockSpeechOnce, { once: true, capture: true });
    document.addEventListener('touchend', _unlockSpeechOnce, { once: true, capture: true });
}

// Toca um Blob de áudio no elemento já desbloqueado. Devolve true se arrancou.
function _playBlob(blob, text, lang, cbs) {
    try {
        const audio = _getTtsAudioEl();
        try { if (audio.src && audio.src.startsWith('blob:')) URL.revokeObjectURL(audio.src); } catch {}
        audio.src = URL.createObjectURL(blob);
        _ttsAudio = audio;
        audio.onplay = () => { _ttsLoadingClear(); cbs.onStart && cbs.onStart(); };
        audio.onended = () => { cbs.onEnd && cbs.onEnd(); };
        audio.onerror = () => { _ttsLoadingClear(); _sysSpeak(text, lang, cbs); };
        const p = audio.play();
        if (p && p.catch) p.catch(() => { _ttsLoadingClear(); _sysSpeak(text, lang, cbs); });
        return true;
    } catch { return false; }
}

// Router central de fala. EN: Edge (neural grátis) -> Gemini -> voz do sistema.
async function speakEN(text, lang, cbs, voiceOverride) {
    cbs = cbs || {};
    if (!text) { cbs.onEnd && cbs.onEnd(); return; }
    _stopCurrentAudio();
    // Abençoar o <audio> ainda dentro do gesto (iOS) — antes de qualquer await.
    try { _primeTtsAudio(); } catch {}
    const isEN = /^en/i.test(lang || '');
    const isPT = /^pt/i.test(lang || '');
    // PROXY server-side da Edge — preferido se configurado. Funciona em iOS
    // (REST HTTPS, não WebSocket) e poupa a quota da chave Gemini para EN.
    if (state.ttsProxyUrl && state.useEdgeTTS !== false) {
        const voice = voiceOverride || state.edgeVoice || (isPT ? 'pt-PT-RaquelNeural' : 'en-US-AriaNeural');
        _ttsLoadingShow();
        try {
            const blob = await _edgeTTSProxy(text, voice, lang);
            if (blob && _playBlob(blob, text, lang, cbs)) { _lastTTSEngine = 'Proxy'; _ttsLoadingClear(); return; }
        } catch (e) { console.warn('[proxy-tts]', e); }
        _ttsLoadingClear();
    }
    if (isEN) {
        // 0) Mistral Voxtral TTS (mesma chave do STT) — preferido se houver chave
        if (state.max && state.max.mistralKey && state.useMistralTTS !== false && Date.now() > _mistralTTSCooldownUntil) {
            _ttsLoadingShow();
            try {
                const blob = await _mistralTTS(text, lang);
                if (blob) { if (_playBlob(blob, text, lang, cbs)) { _lastTTSEngine = 'Mistral'; return; } }
                else { _mistralTTSCooldownUntil = Date.now() + 8 * 60 * 1000; } // falhou — recua 8 min
            } catch (e) { _mistralTTSCooldownUntil = Date.now() + 8 * 60 * 1000; console.warn('[mistral-tts]', e); }
            _ttsLoadingClear();
        }
        // 1) Edge TTS (neural, grátis) — preferido, se ativo e fora de cooldown
        if (state.useEdgeTTS !== false && Date.now() > _edgeCooldownUntil) {
            _ttsLoadingShow();
            try {
                const blob = await _edgeTTS(text, state.edgeVoice, lang);
                if (blob) { if (_playBlob(blob, text, lang, cbs)) { _lastTTSEngine = 'Edge'; return; } }
                else { _edgeCooldownUntil = Date.now() + 8 * 60 * 1000; } // falhou (browser bloqueou?) — recua
            } catch (e) { _edgeCooldownUntil = Date.now() + 8 * 60 * 1000; console.warn('[edge-tts]', e); }
            _ttsLoadingClear();
        }
        // 2) Gemini (se houver key, ativo e fora de cooldown)
        if (_hasGeminiTTS() && state.useGeminiTTS !== false && Date.now() > _geminiCooldownUntil) {
            _ttsLoadingShow();
            try {
                const blob = await _geminiTTS(text, voiceOverride || state.geminiVoice, lang);
                if (blob) { if (_playBlob(blob, text, lang, cbs)) { _lastTTSEngine = 'Gemini'; return; } }
            } catch (e) { console.warn('[gemini-tts]', e); }
            _ttsLoadingClear();
        }
    }
    // Português: voz PT neural (Edge — fiável no iOS via <audio>), depois sistema.
    if (isPT && state.useEdgeTTS !== false && Date.now() > _edgeCooldownUntil) {
        _ttsLoadingShow();
        try {
            const blob = await _edgeTTS(text, _ptEdgeVoice(), 'pt-PT');
            if (blob) { if (_playBlob(blob, text, lang, cbs)) { _lastTTSEngine = 'Edge'; return; } }
            else { _edgeCooldownUntil = Date.now() + 8 * 60 * 1000; }
        } catch (e) { _edgeCooldownUntil = Date.now() + 8 * 60 * 1000; console.warn('[edge-tts pt]', e); }
        _ttsLoadingClear();
    }
    _lastTTSEngine = 'Sistema';
    // 3) Voz do sistema (síncrona) — PT escolhe voz pt-PT, EN escolhe voz EN
    _sysSpeak(text, lang, cbs);
}
window.speakEN = speakEN;
// Voz PT do Edge a usar: respeita a escolha do utilizador se for Edge, senão Raquel.
function _ptEdgeVoice() {
    const sel = (state && state.voicePT) || 'edge:pt-PT-RaquelNeural';
    return sel.indexOf('edge:') === 0 ? sel.slice(5) : 'pt-PT-RaquelNeural';
}

// Voz Gemini determinística por exercício (mesmo exercício → mesma voz,
// exercícios diferentes → vozes diferentes). Simula vários oradores.
const _GEMINI_VOICE_POOL = ['Kore', 'Aoede', 'Charon', 'Puck', 'Fenrir'];
function _voiceForCurrentExercise() {
    if (state.geminiRotateVoice === false) return state.geminiVoice || 'Kore';
    try {
        const ex = currentSession && currentSession.items && currentSession.items[currentSession.idx];
        if (ex && ex.id) {
            let h = 0; const s = String(ex.id);
            for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
            return _GEMINI_VOICE_POOL[h % _GEMINI_VOICE_POOL.length];
        }
    } catch {}
    return state.geminiVoice || 'Kore';
}

function ttsSpeakEN(text, lang) {
    speakEN(text, lang || 'en-US', null, _voiceForCurrentExercise());
}

function toggleSpeakMic() {
    const Rec = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!Rec) { showToast('Reconhecimento de voz não suportado'); return; }
    if (speakState.listening && _speakRecog) {
        speakState._userStop = true;
        try { _speakRecog.stop(); } catch {}
        return;
    }
    speakState._userStop = false;
    speakState._finalAcc = speakState._finalAcc || '';
    const start = () => {
        const r = new Rec();
        r.lang = speakState.lang || 'en-US';
        r.interimResults = true;
        r.maxAlternatives = 1;
        r.continuous = true; // tenta — alguns browsers (iOS) ignoram e cortam na primeira pausa
        _speakRecog = r;
        speakState.listening = true;
        const btn = document.getElementById('speak-mic');
        if (btn) { btn.innerHTML = '<i class="fas fa-stop"></i>&nbsp;&nbsp;A ouvir… toca para terminar'; btn.style.background = 'linear-gradient(135deg,#dc2626,#ea580c)'; }
        r.onresult = (ev) => {
            let interim = '';
            for (let i = ev.resultIndex; i < ev.results.length; i++) {
                const res = ev.results[i];
                if (res.isFinal) speakState._finalAcc += res[0].transcript + ' ';
                else interim += res[0].transcript;
            }
            const out = (speakState._finalAcc + interim).replace(/\s+/g, ' ').trim();
            speakState.transcript = speakState._finalAcc.trim() || out;
            const el = document.getElementById('speak-transcript');
            if (el) {
                el.style.color = '#0f172a';
                el.style.borderStyle = 'solid';
                el.style.background = '#fff';
                el.textContent = out || '…';
            }
            _markActionHasSelection(speakState.transcript.length > 0);
        };
        r.onerror = (ev) => {
            // Erros recuperáveis: 'no-speech', 'aborted' — deixa onend lidar.
            if (ev.error === 'not-allowed' || ev.error === 'service-not-allowed') {
                speakState._userStop = true;
                const el = document.getElementById('speak-transcript');
                if (el) el.textContent = 'Sem permissão de microfone. Ativa nas definições do browser.';
            }
        };
        r.onend = () => {
            // Auto-restart se o utilizador NÃO tocou em "Stop" — alguns motores
            // (Chrome iOS, webkit) terminam sozinhos na primeira pausa longa.
            if (!speakState._userStop) {
                try { setTimeout(start, 80); return; } catch {}
            }
            speakState.listening = false;
            _speakRecog = null;
            const btn = document.getElementById('speak-mic');
            if (btn) {
                const txt = speakState._finalAcc.trim().length > 0 ? 'Falar de novo' : 'Tocar e falar';
                btn.innerHTML = `<i class="fas fa-microphone"></i>&nbsp;&nbsp;${txt}`;
                btn.style.background = 'linear-gradient(135deg,#0891b2,#2563eb)';
            }
        };
        try { r.start(); } catch (e) {
            console.warn('[stt] start failed:', e);
            // Se já estava a correr, faz reset e tenta de novo daqui a pouco
            speakState.listening = false;
            setTimeout(() => { try { r.start(); speakState.listening = true; } catch {} }, 200);
        }
    };
    start();
}
window.toggleSpeakMic = toggleSpeakMic;

function resetSpeak() {
    speakState.transcript = '';
    speakState._finalAcc = '';
    speakState._userStop = false;
    const el = document.getElementById('speak-transcript');
    if (el) {
        el.textContent = 'A tua fala aparece aqui…';
        el.style.color = '#475569';
        el.style.borderStyle = 'dashed';
        el.style.background = '#f8fafc';
    }
    _markActionHasSelection(false);
}
window.resetSpeak = resetSpeak;
window.ttsSpeakEN = ttsSpeakEN;

// Validação speak via IA — devolve {status, corrected, tip}
async function aiValidateSpeech(exercise, transcript) {
    const expected = (exercise.ans || []).join(' / ');
    const norm = (s) => normalize(s).replace(/[^a-z0-9\s']/g, '');
    const nT = norm(transcript);
    const nE = norm(exercise.ans[0] || '');
    // Match local: se as palavras-chave estao todas presentes consideramos "correct".
    const tWords = new Set(nT.split(/\s+/).filter(w => w.length > 2));
    const eWords = nE.split(/\s+/).filter(w => w.length > 2);
    const hit = eWords.filter(w => tWords.has(w)).length;
    const localRatio = eWords.length ? hit / eWords.length : 0;
    if (!hasAIKey()) {
        if (localRatio >= 0.7) return { status: 'correct', corrected: '', tip: '' };
        if (localRatio >= 0.4) return { status: 'close', corrected: exercise.ans[0], tip: 'Tens metade da ideia — repete devagar a frase modelo.' };
        return { status: 'wrong', corrected: exercise.ans[0], tip: 'Ouve o modelo e tenta repetir a estrutura.' };
    }
    const prompt = `You are an English coach evaluating a Portuguese Project Manager (${(typeof _tutorTargetLevel === 'function') ? _tutorTargetLevel() : 'B2'} level, working toward the next CEFR level) preparing for SAP/consulting meetings.

CONTEXT (Portuguese, what the student should say in English): "${exercise.q}"
MODEL ANSWER(S): "${expected}"
STUDENT SAID (transcribed from speech): "${transcript}"

Evaluate:
- "correct": meaning AND grammar acceptable for a senior PM, even if wording differs from model.
- "close": meaning right but grammar/word-choice off (article, tense, preposition, awkward phrasing).
- "wrong": meaning wrong or unintelligible.

Return STRICT JSON:
{"status":"correct|close|wrong","corrected":"<one polished English version the student should learn>","tip":"<one short coaching note in EUROPEAN PORTUGUESE, max 18 words>"}`;
    try {
        const { text } = await callClaudeAPI(prompt, 320);
        const parsed = _extractJSON(text);
        if (parsed && ['correct', 'close', 'wrong'].includes(parsed.status)) {
            return {
                status: parsed.status,
                corrected: String(parsed.corrected || exercise.ans[0]).slice(0, 400),
                tip: String(parsed.tip || '').slice(0, 200)
            };
        }
    } catch (e) { console.warn('[speak-ai] failed:', e); }
    if (localRatio >= 0.7) return { status: 'correct', corrected: '', tip: '' };
    return { status: 'close', corrected: exercise.ans[0], tip: 'Repete a frase modelo devagar.' };
}

let orderState = [];
function redrawOrder() {
    const list = document.getElementById('order-list');
    if (!list) return;
    list.innerHTML = orderState.map((it, i) => `
        <li class="order-item">
            <span class="order-item-num">${i+1}</span>
            <span style="flex:1">${it}</span>
            <span class="order-ctrls">
                <button class="order-btn" onclick="moveOrder(${i}, -1)" aria-label="Subir" title="Subir"><i class="fas fa-arrow-up" aria-hidden="true"></i></button>
                <button class="order-btn" onclick="moveOrder(${i}, 1)" aria-label="Descer" title="Descer"><i class="fas fa-arrow-down" aria-hidden="true"></i></button>
            </span>
        </li>
    `).join('');
}
function moveOrder(i, dir) {
    const j = i + dir;
    if (j < 0 || j >= orderState.length) return;
    [orderState[i], orderState[j]] = [orderState[j], orderState[i]];
    redrawOrder();
}

let matchState = { leftItems: [], rightItems: [], matched: {} };
function redrawMatch() {
    const area = document.getElementById('match-area');
    if (!area) return;
    const leftHtml = matchState.leftItems.map((it, i) => {
        const matched = matchState.matched[i] !== undefined;
        const selected = matchSelection.left === i;
        return `<div class="match-cell ${matched ? 'matched' : ''} ${selected ? 'selected' : ''}" onclick="matchPickLeft(${i})">${it}</div>`;
    }).join('');
    const matchedRightIdx = new Set(Object.values(matchState.matched));
    const rightHtml = matchState.rightItems.map((it, i) => {
        const matched = matchedRightIdx.has(i);
        return `<div class="match-cell ${matched ? 'matched' : ''}" onclick="matchPickRight(${i})">${it}</div>`;
    }).join('');
    area.innerHTML = `<div class="match-col">${leftHtml}</div><div class="match-col">${rightHtml}</div>`;
}
function matchPickLeft(i) {
    if (matchState.matched[i] !== undefined) return;
    matchSelection.left = i;
    redrawMatch();
}
function matchPickRight(j) {
    if (matchSelection.left === null) { showToast('Escolhe primeiro a esquerda'); return; }
    if (Object.values(matchState.matched).includes(j)) return;
    matchState.matched[matchSelection.left] = j;
    matchSelection.left = null;
    redrawMatch();
}

// ============================================================
// SUDOKU 4×4 INTERATIVO — primeiro mini-jogo da Detetive Mental
// Renderiza grelha clicável + picker de números + bubble do
// "Detetive" com pistas/celebrações. Marca isCorrect quando a
// grelha está válida segundo as regras do sudoku (linhas, colunas
// e blocos 2×2 com 1, 2, 3, 4 cada um uma vez).
// ============================================================
let sudokuState = { grid: [], initial: [], selected: -1, moves: 0, solved: false, hintsUsed: 0, solution: null };

function _sudokuStartFromExercise(e) {
    const init = (e.puzzle && e.puzzle.initial) || [];
    sudokuState = {
        grid: [...init],
        initial: [...init],
        selected: -1,
        moves: 0,
        solved: false,
        hintsUsed: 0,
        solution: (e.puzzle && e.puzzle.solution) || null,
        coachMsg: e.hint || 'Toca numa célula vazia e escolhe 1, 2, 3 ou 4.'
    };
}

function _sudokuRender() {
    const area = document.getElementById('ex-answer-area');
    if (!area) return;
    const s = sudokuState;
    const cellHtml = s.grid.map((v, i) => {
        const fixed = s.initial[i] !== 0;
        const sel = i === s.selected ? ' sel' : '';
        const fx = fixed ? ' fixed' : '';
        // Detecta conflito na linha, coluna ou bloco 2×2.
        let conf = '';
        if (v !== 0) {
            const r = Math.floor(i / 4), c = i % 4;
            for (let k = 0; k < 4; k++) {
                if (k !== c && s.grid[r * 4 + k] === v) conf = ' conf';
                if (k !== r && s.grid[k * 4 + c] === v) conf = ' conf';
            }
            const br = Math.floor(r / 2) * 2, bc = Math.floor(c / 2) * 2;
            for (let dr = 0; dr < 2; dr++) for (let dc = 0; dc < 2; dc++) {
                const idx = (br + dr) * 4 + (bc + dc);
                if (idx !== i && s.grid[idx] === v) conf = ' conf';
            }
        }
        return `<button class="sk-cell${fx}${sel}${conf}" onclick="_sudokuSelect(${i})">${v === 0 ? '' : v}</button>`;
    }).join('');
    const picker = [1, 2, 3, 4].map(n =>
        `<button class="sk-pick" onclick="_sudokuFill(${n})">${n}</button>`
    ).join('') + `<button class="sk-pick sk-clear" onclick="_sudokuFill(0)">×</button>`;
    const filled = s.grid.filter(v => v !== 0).length;
    area.innerHTML = `
      <div class="sudoku-wrap">
        <div class="sk-coach">
          <span class="sk-coach-av">🕵️</span>
          <span class="sk-coach-msg" id="sk-coach-msg">${escapeHtml(s.coachMsg || '')}</span>
        </div>
        <div class="sudoku-grid">${cellHtml}</div>
        <div class="sudoku-meta">
          <span>${filled}/16 preenchidos · ${s.moves} jogadas${s.hintsUsed ? ' · pistas: ' + s.hintsUsed : ''}</span>
          <button class="sk-hint-btn" onclick="_sudokuHint()" ${s.solved ? 'disabled' : ''}>💡 Pista</button>
        </div>
        <div class="sudoku-picker">${picker}</div>
        ${s.solved ? '<div class="sk-solved">✅ Sudoku resolvido! Carrega em Responder.</div>' : ''}
      </div>`;
}

function _sudokuSelect(i) {
    if (sudokuState.solved) return;
    if (sudokuState.initial[i] !== 0) return;
    sudokuState.selected = (sudokuState.selected === i) ? -1 : i;
    _sudokuRender();
}
window._sudokuSelect = _sudokuSelect;

function _sudokuFill(n) {
    const s = sudokuState;
    if (s.solved) return;
    if (s.selected < 0) { showToast && showToast('Toca primeiro numa célula vazia'); return; }
    if (s.initial[s.selected] !== 0) return;
    if (s.grid[s.selected] !== n) {
        s.grid[s.selected] = n;
        s.moves += 1;
    }
    s.solved = _sudokuIsSolved(s.grid);
    if (s.solved) {
        const stars = '⭐'.repeat(Math.max(1, 3 - s.hintsUsed));
        const hintTxt = s.hintsUsed === 0
            ? 'sem ajudas! 🦸‍♀️'
            : `com ${s.hintsUsed} ajuda${s.hintsUsed === 1 ? '' : 's'}.`;
        s.coachMsg = `🎉 Resolveste em ${s.moves} jogadas ${hintTxt} ${stars}`;
        s.selected = -1;
    } else {
        const filled = s.grid.filter(v => v !== 0).length;
        if (filled === 16) {
            s.coachMsg = '🤔 A grelha está cheia mas há conflitos. As células com fundo vermelho repetem na linha, coluna ou bloco — corrige-as.';
        } else if (s.moves >= 6 && filled < 16) {
            s.coachMsg = 'Boa! Vai linha a linha: qual é o número que ainda não aparece?';
        }
    }
    _sudokuRender();
}
window._sudokuFill = _sudokuFill;

function _sudokuIsSolved(g) {
    if (g.some(v => v === 0)) return false;
    const checkGroup = (idxs) => {
        const seen = new Set();
        for (const i of idxs) { if (seen.has(g[i])) return false; seen.add(g[i]); }
        return seen.size === 4;
    };
    for (let r = 0; r < 4; r++) if (!checkGroup([r*4, r*4+1, r*4+2, r*4+3])) return false;
    for (let c = 0; c < 4; c++) if (!checkGroup([c, c+4, c+8, c+12])) return false;
    for (let br = 0; br < 2; br++) for (let bc = 0; bc < 2; bc++) {
        const idxs = [];
        for (let dr = 0; dr < 2; dr++) for (let dc = 0; dc < 2; dc++) idxs.push((br*2+dr)*4 + (bc*2+dc));
        if (!checkGroup(idxs)) return false;
    }
    return true;
}

function _sudokuHint() {
    const s = sudokuState;
    if (s.solved || !s.solution) return;
    // Procura uma célula vazia ou errada e revela o valor correcto.
    let target = -1;
    for (let i = 0; i < 16; i++) {
        if (s.initial[i] === 0 && s.grid[i] !== s.solution[i]) { target = i; break; }
    }
    if (target === -1) return;
    s.grid[target] = s.solution[target];
    s.hintsUsed += 1;
    s.coachMsg = `💡 Coloquei o número ${s.solution[target]} na célula em destaque. Foi possível porque era o único que não repetia na linha, coluna e bloco.`;
    s.selected = target;
    s.solved = _sudokuIsSolved(s.grid);
    if (s.solved) s.coachMsg = '🎉 Pronto! Resolvido com pistas — para a próxima tenta sem.';
    _sudokuRender();
}
window._sudokuHint = _sudokuHint;

// ============================================================
// COFRE DOS CÓDIGOS — type:'game' game:'cofre'
// Mostra história + pistas + N caixas para digitar um código.
// Numpad 0-9 + backspace + pista (revela um dígito).
// Usado para charadas matemáticas e mistérios "qual é o número?".
// ============================================================
let cofreState = { digits: 4, input: [], solution: '', hintsUsed: 0, solved: false, story: '', clues: [], hint: '' };
function _cofreStart(e) {
    cofreState = {
        digits: e.digits || (e.solution || '').length || 1,
        input: [],
        solution: String(e.solution || ''),
        hintsUsed: 0,
        solved: false,
        story: e.story || '',
        clues: e.clues || [],
        hint: e.hint || ''
    };
}
function _cofreRender() {
    const area = document.getElementById('ex-answer-area');
    if (!area) return;
    const s = cofreState;
    const boxes = Array.from({ length: s.digits }, (_, i) => {
        const v = s.input[i];
        const filled = v !== undefined ? 'filled' : '';
        const next = (s.input.length === i && !s.solved) ? 'next' : '';
        return `<div class="cofre-box ${filled} ${next}">${v !== undefined ? v : ''}</div>`;
    }).join('');
    const numpad = [1,2,3,4,5,6,7,8,9,0].map(n =>
        `<button class="cofre-key" onclick="_cofreType(${n})">${n}</button>`
    ).join('');
    const story = s.story ? `<div class="cofre-story">${escapeHtml(s.story)}</div>` : '';
    const clues = s.clues.length ? `<ul class="cofre-clues">${s.clues.map(c => `<li>${escapeHtml(c)}</li>`).join('')}</ul>` : '';
    const coach = s.solved
        ? `🎉 Cofre aberto! ${s.hintsUsed === 0 ? 'Sem ajudas! ⭐⭐⭐' : 'Usaste ' + s.hintsUsed + ' ajuda' + (s.hintsUsed===1?'':'s') + '.'}`
        : (s.hint || 'Lê as pistas e descobre o código.');
    area.innerHTML = `
      <div class="cofre-wrap">
        <div class="cofre-coach"><span class="cofre-coach-av">🕵️</span><span class="cofre-coach-msg">${escapeHtml(coach)}</span></div>
        ${story}${clues}
        <div class="cofre-boxes">${boxes}</div>
        <div class="cofre-actions">
          <button class="cofre-back" onclick="_cofreBack()" ${s.solved?'disabled':''}>⌫</button>
          <button class="cofre-hint" onclick="_cofreHint()" ${s.solved?'disabled':''}>💡 Pista</button>
        </div>
        <div class="cofre-numpad">${numpad}</div>
        ${s.solved ? '<div class="cofre-solved">✅ Código certo! Carrega Responder.</div>' : ''}
      </div>`;
}
function _cofreType(n) {
    const s = cofreState;
    if (s.solved) return;
    if (s.input.length >= s.digits) return;
    s.input.push(String(n));
    if (s.input.length === s.digits) s.solved = s.input.join('') === s.solution;
    _cofreRender();
}
window._cofreType = _cofreType;
function _cofreBack() {
    if (cofreState.solved) return;
    cofreState.input.pop();
    _cofreRender();
}
window._cofreBack = _cofreBack;
function _cofreHint() {
    const s = cofreState;
    if (s.solved) return;
    // Preenche o próximo dígito correcto da esquerda para a direita.
    const next = s.input.length;
    if (next >= s.digits) return;
    s.input.push(s.solution[next]);
    s.hintsUsed += 1;
    if (s.input.length === s.digits) s.solved = s.input.join('') === s.solution;
    _cofreRender();
}
window._cofreHint = _cofreHint;

// ============================================================
// COFRE EM PASSOS — type:'game' game:'cofre_steps'
// Acessibilidade discalculia: em vez de pedir o resultado final
// (e.g. "3×4×5"), divide em passos checáveis ("3×4=?" → "12×5=?").
// Cada passo tem o seu próprio prompt + numpad. Avança quando
// acerta um passo. A criança nunca tem de segurar muito na cabeça.
// ============================================================
let cstState = { steps: [], idx: 0, input: '', solved: false, hintsUsed: 0, story: '', coachMsg: '', shake: false };
function _cstStart(e) {
    cstState = {
        steps: e.steps || [],
        idx: 0,
        input: '',
        solved: false,
        hintsUsed: 0,
        story: e.story || '',
        coachMsg: e.intro || 'Vamos resolver passo por passo. Lê cada passo e digita o resultado.',
        shake: false
    };
}
function _cstRender() {
    const area = document.getElementById('ex-answer-area');
    if (!area) return;
    const s = cstState;
    const cur = s.steps[s.idx];
    if (!cur) return;
    const story = s.story ? `<div class="cst-story">${escapeHtml(s.story)}</div>` : '';
    const progress = s.steps.map((_, i) => {
        const cls = i < s.idx ? 'done' : (i === s.idx ? 'cur' : '');
        return `<div class="cst-dot ${cls}">${i < s.idx ? '✓' : (i+1)}</div>`;
    }).join('<div class="cst-dot-sep"></div>');
    const ansLen = String(cur.answer).length;
    const shakeCls = s.shake ? 'shake' : '';
    const boxes = Array.from({ length: ansLen }, (_, i) => {
        const v = s.input[i];
        const filled = v !== undefined ? 'filled' : '';
        const next = (s.input.length === i && !s.solved) ? 'next' : '';
        return `<div class="cofre-box ${filled} ${next} ${shakeCls}">${v !== undefined ? v : ''}</div>`;
    }).join('');
    const numpad = [1,2,3,4,5,6,7,8,9,0].map(n =>
        `<button class="cofre-key" onclick="_cstType(${n})">${n}</button>`
    ).join('');
    area.innerHTML = `
      <div class="cofre-wrap">
        <div class="cofre-coach"><span class="cofre-coach-av">🧠</span><span class="cofre-coach-msg">${escapeHtml(s.coachMsg)}</span></div>
        ${story}
        <div class="cst-progress">${progress}</div>
        <div class="cst-step-prompt">${escapeHtml(cur.prompt)}</div>
        <div class="cofre-boxes">${boxes}</div>
        <div class="cofre-actions">
          <button class="cofre-back" onclick="_cstBack()" ${s.solved?'disabled':''}>⌫</button>
          <button class="cofre-hint" onclick="_cstHint()" ${s.solved?'disabled':''}>💡 Pista</button>
        </div>
        <div class="cofre-numpad">${numpad}</div>
        ${s.solved ? '<div class="cofre-solved">✅ Resolveste tudo! Carrega Responder.</div>' : ''}
      </div>`;
}
function _cstType(n) {
    const s = cstState;
    if (s.solved) return;
    const cur = s.steps[s.idx];
    const ansLen = String(cur.answer).length;
    if (s.input.length >= ansLen) return;
    s.input += String(n);
    if (s.input.length >= ansLen) {
        if (s.input === String(cur.answer)) {
            // Acertou o passo — avança ou termina.
            if (s.idx + 1 < s.steps.length) {
                s.coachMsg = '✓ Boa! Vamos ao próximo passo.';
                _cstRender();
                setTimeout(() => {
                    s.idx += 1;
                    s.input = '';
                    s.coachMsg = 'Lê o próximo passo e digita.';
                    _cstRender();
                }, 750);
            } else {
                s.solved = true;
                s.coachMsg = `🎉 Resolveste em ${s.steps.length} passos${s.hintsUsed?' (com '+s.hintsUsed+' pista'+(s.hintsUsed===1?'':'s')+').':' — sem pistas! ⭐⭐⭐'}`;
                _cstRender();
            }
        } else {
            // Errou — pequeno feedback e limpa.
            s.coachMsg = '😕 Não é esse. Pensa mais um bocadinho.';
            s.shake = true;
            _cstRender();
            setTimeout(() => { s.input = ''; s.shake = false; _cstRender(); }, 600);
        }
    } else {
        _cstRender();
    }
}
window._cstType = _cstType;
function _cstBack() {
    if (cstState.solved) return;
    cstState.input = cstState.input.slice(0, -1);
    _cstRender();
}
window._cstBack = _cstBack;
function _cstHint() {
    const s = cstState;
    if (s.solved) return;
    const cur = s.steps[s.idx];
    if (s.hintsUsed === 0 && cur.hint) {
        // 1.ª pista — texto de ajuda só.
        s.coachMsg = '💡 ' + cur.hint;
        s.hintsUsed += 1;
        _cstRender();
        return;
    }
    // 2.ª pista (ou se não há texto) — revela a resposta do passo.
    s.input = String(cur.answer);
    s.coachMsg = `💡 A resposta deste passo é ${cur.answer}.`;
    s.hintsUsed += 1;
    _cstRender();
    setTimeout(() => {
        if (s.idx + 1 < s.steps.length) {
            s.idx += 1;
            s.input = '';
            s.coachMsg = 'Continua. Lê o próximo passo.';
        } else {
            s.solved = true;
            s.coachMsg = `🎉 Resolvido com ${s.hintsUsed} pista${s.hintsUsed===1?'':'s'}.`;
        }
        _cstRender();
    }, 1200);
}
window._cstHint = _cstHint;

// ============================================================
// ESTIMADOR — type:'game' game:'estimador'
// Slider de min..max, com "termómetro" vivo a indicar proximidade.
// Considera acerto se |valor − resposta| <= tolerance.
// ============================================================
let estState = { min: 0, max: 100, value: 50, answer: 0, tolerance: 1, unit: '', story: '', moved: false };
function _estStart(e) {
    const min = e.min ?? 0;
    const max = e.max ?? 100;
    // step: usa o do exercício, ou calcula um sensato — passos grandes
    // para ranges grandes (~50 passos do início ao fim) para não soar
    // hipersensível ao toque. Mínimo 1.
    const step = e.step ?? Math.max(1, Math.round((max - min) / 50));
    // Snap o ponto inicial a um múltiplo do step a partir de min.
    const rawMid = (min + max) / 2;
    const snapped = min + Math.round((rawMid - min) / step) * step;
    estState = {
        min, max, step,
        value: snapped,
        answer: e.answer,
        tolerance: e.tolerance ?? 1,
        unit: e.unit || '',
        story: e.story || '',
        hint: e.hint || '',
        moved: false
    };
}
function _estFeedback() {
    const s = estState;
    if (!s.moved) return '👆 Arrasta o cursor para fazer o teu palpite.';
    const d = Math.abs(s.value - s.answer);
    if (d <= s.tolerance) return '🥳 A QUENTE! Excelente palpite.';
    if (d <= s.tolerance * 2) return '🙂 Morno — estás perto.';
    if (d <= s.tolerance * 4) return '🥶 Frio. Pensa melhor.';
    return '🧊 Muito frio. Está bem longe.';
}
function _estRender() {
    const area = document.getElementById('ex-answer-area');
    if (!area) return;
    const s = estState;
    const story = s.story ? `<div class="est-story">${escapeHtml(s.story)}</div>` : '';
    area.innerHTML = `
      <div class="est-wrap">
        ${story}
        <div class="est-value">${s.value} <span class="est-unit">${escapeHtml(s.unit)}</span></div>
        <input class="est-slider" type="range" min="${s.min}" max="${s.max}" step="${s.step}" value="${s.value}" oninput="_estMove(this.value)">
        <div class="est-scale"><span>${s.min}</span><span>${s.max}</span></div>
        <div class="est-feedback">${_estFeedback()}</div>
      </div>`;
    // NOTA: a dica NÃO é mostrada aqui — fica escondida atrás do botão
    // "💡 Mostrar dica" no topo (e.hint). Antes aparecia sempre por baixo
    // e muitas vezes entregava a resposta (ex.: "Entre 28 e 31").
}
function _estMove(v) {
    estState.value = parseInt(v, 10);
    estState.moved = true;
    // NÃO re-renderiza o DOM todo durante o drag — só atualiza o valor
    // e o termómetro. Substituir o <input> em pleno drag faz o slider
    // saltar/perder o toque em mobile.
    const valEl = document.querySelector('.est-value');
    const fbEl = document.querySelector('.est-feedback');
    if (valEl) {
        // Mantém o span da unidade.
        const unit = estState.unit ? ` <span class="est-unit">${estState.unit}</span>` : '';
        valEl.innerHTML = estState.value + unit;
    }
    if (fbEl) fbEl.textContent = _estFeedback();
}
window._estMove = _estMove;

// ============================================================
// SUSPEITOS — type:'game' game:'suspeitos'
// Cartas de suspeitos com 3 estados (?, ❌, ✅). Tap para ciclar.
// Acerta quando há exactamente 1 ✅ no suspeito certo.
// ============================================================
let susState = { suspects: [], states: {}, solution: '', clues: [], story: '', solved: false };
function _susStart(e) {
    const states = {};
    (e.suspects || []).forEach(sp => { states[sp.id] = '?'; });
    susState = {
        suspects: e.suspects || [],
        states,
        solution: e.solution || '',
        clues: e.clues || [],
        story: e.story || '',
        // Modo "pick": pergunta de escolha única (intruso/analogia/condicional/
        // dedução) — 1 toque escolhe, sem o ciclo ❌/✅ de detetive, e as pistas
        // ficam escondidas atrás de um botão (senão entregam a resposta).
        pick: !!e.pick,
        cluesShown: 0,
        solved: false
    };
}
function _susRender() {
    const area = document.getElementById('ex-answer-area');
    if (!area) return;
    const s = susState;
    const cards = s.suspects.map(sp => {
        const st = s.states[sp.id] || '?';
        const cls = st === '✅' ? 'pick' : (st === '❌' ? 'out' : '');
        const stIcon = s.pick ? (st === '✅' ? '✅' : '') : st;
        return `<button class="sus-card ${cls}" onclick="_susCycle('${sp.id}')">
            <div class="sus-emoji">${sp.emoji || '🙂'}</div>
            <div class="sus-name">${escapeHtml(sp.name)}</div>
            <div class="sus-state">${stIcon}</div>
        </button>`;
    }).join('');
    const story = s.story ? `<div class="sus-story">${escapeHtml(s.story)}</div>` : '';
    let clues = '';
    if (s.clues.length) {
        if (s.pick) {
            const shown = s.clues.slice(0, s.cluesShown);
            const list = shown.length ? `<ul class="sus-clues">${shown.map(c => `<li>${escapeHtml(c)}</li>`).join('')}</ul>` : '';
            const more = s.cluesShown < s.clues.length
                ? `<button class="sus-clue-btn" onclick="_susMoreClue()">🔍 ${s.cluesShown === 0 ? 'Preciso de uma pista' : 'Outra pista'} (${s.cluesShown}/${s.clues.length})</button>` : '';
            clues = list + more;
        } else {
            clues = `<ul class="sus-clues">${s.clues.map(c => `<li>${escapeHtml(c)}</li>`).join('')}</ul>`;
        }
    }
    const picks = Object.values(s.states).filter(v => v === '✅').length;
    const coach = s.pick
        ? (picks === 0 ? 'Pensa bem e toca na tua resposta.' : 'Boa! Agora carrega Responder.')
        : (picks === 0
            ? 'Toca nos suspeitos: 1× = ❌ (não foi), 2× = ✅ (foi), 3× = limpa.'
            : picks > 1 ? '⚠️ Marca SÓ UM como culpado (✅).' : 'Quando tiveres a tua escolha, carrega Responder.');
    area.innerHTML = `
      <div class="sus-wrap">
        <div class="sus-coach"><span>${s.pick ? '🧠' : '🕵️'}</span><span>${escapeHtml(coach)}</span></div>
        ${story}${clues}
        <div class="sus-cards">${cards}</div>
      </div>`;
}
function _susCycle(id) {
    const s = susState;
    if (s.pick) {
        // Escolha única: toca = escolhe (e desmarca os outros); toca de novo = limpa.
        const was = s.states[id] === '✅';
        Object.keys(s.states).forEach(k => { s.states[k] = '?'; });
        if (!was) s.states[id] = '✅';
    } else {
        const order = ['?', '❌', '✅'];
        const cur = s.states[id] || '?';
        s.states[id] = order[(order.indexOf(cur) + 1) % 3];
    }
    _susRender();
}
window._susCycle = _susCycle;
function _susMoreClue() {
    if (susState) { susState.cluesShown = Math.min((susState.cluesShown || 0) + 1, (susState.clues || []).length); _susRender(); }
}
window._susMoreClue = _susMoreClue;

// ============================================================
// PADRÃO — type:'game' game:'padrao'
// Mostra sequência com '?' e o user escreve o termo em falta.
// Numpad para números, ou opções (chips) para letras/símbolos.
// ============================================================
let padState = { sequence: [], answer: '', input: '', options: null, solved: false };
function _padStart(e) {
    padState = {
        sequence: e.sequence || [],
        answer: String(e.answer || ''),
        input: '',
        options: e.options || null,
        hint: e.hint || '',
        solved: false
    };
}
function _padRender() {
    const area = document.getElementById('ex-answer-area');
    if (!area) return;
    const s = padState;
    const seqHtml = s.sequence.map(x => {
        const isQ = String(x) === '?';
        const v = isQ && s.input ? s.input : x;
        return `<span class="pad-term ${isQ ? 'q' : ''} ${isQ && s.solved ? 'ok' : ''}">${escapeHtml(String(v))}</span>`;
    }).join('<span class="pad-sep">,</span>');
    let input;
    if (s.options) {
        input = `<div class="pad-options">${s.options.map(o => `<button class="pad-opt" onclick="_padPick(${JSON.stringify(String(o)).replace(/"/g,'&quot;')})">${escapeHtml(String(o))}</button>`).join('')}</div>`;
    } else {
        const numpad = [1,2,3,4,5,6,7,8,9,0].map(n =>
            `<button class="pad-key" onclick="_padPick('${n}')">${n}</button>`
        ).join('');
        input = `<div class="pad-numpad">${numpad}<button class="pad-key pad-back" onclick="_padBack()">⌫</button></div>`;
    }
    area.innerHTML = `
      <div class="pad-wrap">
        <div class="pad-coach">🧩 ${escapeHtml(s.hint || 'Descobre o padrão e completa a sequência.')}</div>
        <div class="pad-seq">${seqHtml}</div>
        ${input}
        ${s.solved ? '<div class="pad-solved">✅ Acertaste! Carrega Responder.</div>' : ''}
      </div>`;
}
function _padPick(v) {
    const s = padState;
    if (s.solved) return;
    if (s.options) {
        s.input = String(v);
        s.solved = s.input === s.answer;
    } else {
        s.input = (s.input + String(v)).slice(0, 4);
        // Auto-validate quando o comprimento bate.
        if (s.input.length >= s.answer.length) s.solved = s.input === s.answer;
    }
    _padRender();
}
window._padPick = _padPick;
function _padBack() {
    if (padState.solved) return;
    padState.input = padState.input.slice(0, -1);
    _padRender();
}
window._padBack = _padBack;

// ============================================================
// QUANTOS VÊS? — type:'game' game:'quantos' (SUBITIZING)
// Treino nuclear de discalculia: ligar quantidade ↔ símbolo SEM
// contar um a um. Mostra pontos arrumados em ten-frames (2 linhas
// de 5 — o suporte visual padrão), a criança toca no número certo.
// Estrutura visual (não pontos espalhados ao acaso) porque é isso
// que constrói o "sentido de número".
// ============================================================
let qtState = { dots: 0, options: [], picked: null, solved: false, prompt: '' };
function _qtStart(e) {
    const dots = e.dots || 0;
    // Opções: a resposta + distractores próximos (±1, ±2), baralhadas.
    let opts = e.options;
    if (!opts) {
        const set = new Set([dots]);
        let delta = 1;
        while (set.size < 4) {
            if (dots - delta >= 0) set.add(dots - delta);
            if (set.size < 4) set.add(dots + delta);
            delta++;
        }
        opts = Array.from(set).sort((a, b) => a - b);
    }
    qtState = { dots, options: opts, picked: null, solved: false, prompt: e.prompt || 'Quantos pontos vês?' };
}
function _qtDotsHtml(n) {
    // Renderiza n pontos em ten-frames de 10 (5 col × 2 linhas).
    // Para n ≤ 10 → um ten-frame; 11-20 → dois. Células vazias ficam
    // como buraco ténue para a grelha dar referência espacial.
    const frames = [];
    let remaining = n;
    const nFrames = Math.max(1, Math.ceil(n / 10));
    for (let f = 0; f < nFrames; f++) {
        const inThis = Math.min(10, remaining);
        remaining -= inThis;
        const cells = Array.from({ length: 10 }, (_, i) =>
            `<span class="qt-cell ${i < inThis ? 'on' : ''}"></span>`
        ).join('');
        frames.push(`<div class="qt-frame">${cells}</div>`);
    }
    return frames.join('');
}
function _qtRender() {
    const area = document.getElementById('ex-answer-area');
    if (!area) return;
    const s = qtState;
    const opts = s.options.map(o => {
        let cls = 'qt-opt';
        if (s.picked !== null) {
            if (o === s.dots) cls += ' correct';
            else if (o === s.picked) cls += ' wrong';
        }
        return `<button class="${cls}" onclick="_qtPick(${o})" ${s.solved ? 'disabled' : ''}>${o}</button>`;
    }).join('');
    area.innerHTML = `
      <div class="qt-wrap">
        <div class="qt-coach"><span>🧠</span><span>${escapeHtml(s.prompt)}</span></div>
        <div class="qt-frames">${_qtDotsHtml(s.dots)}</div>
        <div class="qt-hint-tip">Olha para os grupos de 5 — não contes um a um!</div>
        <div class="qt-options">${opts}</div>
        ${s.solved ? '<div class="qt-solved">✅ Certo! Carrega Responder.</div>' : (s.picked !== null ? '<div class="qt-retry">Tenta outra vez 🙂</div>' : '')}
      </div>`;
}
function _qtPick(n) {
    const s = qtState;
    if (s.solved) return;
    s.picked = n;
    s.solved = (n === s.dots);
    _qtRender();
    if (!s.solved) {
        // Deixa ver o erro um momento e limpa para nova tentativa.
        setTimeout(() => { if (!qtState.solved) { qtState.picked = null; _qtRender(); } }, 900);
    }
}
window._qtPick = _qtPick;

// ============================================================
// CRUZA-NÚMEROS — type:'game' game:'cruzados' (palavras-cruzadas
// matemático / cross-sums). Encaixa números na grelha para
// completar contas que se cruzam. Forte para discalculia: junta
// cálculo, valor posicional e lógica espacial.
// Formato: e.grid = matriz de strings por célula:
//   ""        → fundo (sem célula)
//   "8"       → número fixo
//   "+ - × ÷ =" → operador/igual fixo
//   "_:4"     → célula a preencher (solução 4)
// e.bankExtra (opcional) = distratores extra no banco.
// ============================================================
let cruzState = { grid: [], cols: 0, blanks: [], bank: [], sel: -1, solved: false };
function _cruzStart(e) {
    const grid = e.grid || [];
    const cols = grid.reduce((m, r) => Math.max(m, r.length), 0);
    const blanks = [];
    grid.forEach((row, r) => row.forEach((cell, c) => {
        if (typeof cell === 'string' && cell.startsWith('_:')) {
            blanks.push({ r, c, sol: cell.slice(2), val: null, bankIdx: null });
        }
    }));
    let vals = blanks.map(b => b.sol).concat((e.bankExtra || []).map(String));
    vals = vals.sort(() => Math.random() - 0.5);
    cruzState = { grid, cols, blanks, bank: vals.map(v => ({ v, used: false })), sel: -1, solved: false };
}
function _cruzBlankAt(r, c) { return cruzState.blanks.findIndex(b => b.r === r && b.c === c); }
function _cruzRender() {
    const area = document.getElementById('ex-answer-area');
    if (!area) return;
    const s = cruzState;
    // Quando TODAS as células estão preenchidas mas o puzzle não está certo,
    // damos feedback: célula certa fica verde, errada fica vermelha — para a
    // criança ver o que corrigir (antes só bloqueava sem dizer o quê).
    const allFilled = s.blanks.length > 0 && s.blanks.every(b => b.val != null);
    const showWrong = allFilled && !s.solved;
    let cells = '';
    s.grid.forEach((row, r) => {
        for (let c = 0; c < s.cols; c++) {
            const cell = row[c];
            if (cell === undefined || cell === null || cell === '') { cells += '<div class="cz-bg"></div>'; continue; }
            if (typeof cell === 'string' && cell.startsWith('_:')) {
                const bi = _cruzBlankAt(r, c);
                const b = s.blanks[bi];
                const sel = bi === s.sel ? ' sel' : '';
                const filled = b.val != null ? ' filled' : '';
                let mark = '';
                if (showWrong && b.val != null) mark = (String(b.val) === String(b.sol)) ? ' cz-ok' : ' cz-wrong';
                else if (s.solved) mark = ' cz-ok';
                cells += `<button class="cz-cell blank${sel}${filled}${mark}" onclick="_cruzTapBlank(${bi})">${b.val != null ? b.val : ''}</button>`;
            } else if ('+-×÷='.includes(cell)) {
                cells += `<div class="cz-op">${cell}</div>`;
            } else {
                cells += `<div class="cz-fix">${escapeHtml(cell)}</div>`;
            }
        }
    });
    const bank = s.bank.map((b, i) =>
        `<button class="cz-chip${b.used ? ' used' : ''}" onclick="_cruzTapChip(${i})" ${b.used ? 'disabled' : ''}>${escapeHtml(b.v)}</button>`
    ).join('');
    area.innerHTML = `
      <div class="cruz-wrap">
        <div class="cruz-coach"><span>${s.solved ? '🎉' : showWrong ? '🔎' : '🧩'}</span><span>${s.solved ? 'Todas as contas certas! Carrega Responder.' : showWrong ? 'Quase! Os números a <b>vermelho</b> estão trocados — toca neles para mudar, ou carrega Responder para ver a solução.' : 'Toca numa célula vazia e depois no número certo. Cada conta (→ e ↓) tem de ficar correta.'}</span></div>
        <div class="cruz-grid" style="grid-template-columns:repeat(${s.cols},1fr)">${cells}</div>
        <div class="cruz-bank">${bank}</div>
      </div>`;
}
function _cruzTapBlank(i) {
    const s = cruzState; if (s.solved) return;
    const b = s.blanks[i];
    if (b.val != null) { // limpar — devolve o número ao banco
        if (b.bankIdx != null) s.bank[b.bankIdx].used = false;
        b.val = null; b.bankIdx = null; s.sel = i; _cruzRender(); return;
    }
    s.sel = (s.sel === i ? -1 : i);
    _cruzRender();
}
window._cruzTapBlank = _cruzTapBlank;
function _cruzTapChip(i) {
    const s = cruzState; if (s.solved) return;
    if (s.bank[i].used) return;
    if (s.sel < 0) { showToast && showToast('Toca primeiro numa célula vazia.'); return; }
    const b = s.blanks[s.sel];
    if (b.bankIdx != null) s.bank[b.bankIdx].used = false; // troca
    b.val = s.bank[i].v; b.bankIdx = i; s.bank[i].used = true; s.sel = -1;
    s.solved = s.blanks.every(x => x.val != null && String(x.val) === String(x.sol));
    _cruzRender();
}
window._cruzTapChip = _cruzTapChip;

// Devolve { status: 'correct'|'partial'|'wrong', missing?: string }.
// "partial" = resposta tem parte certa mas é incompleta — usado em
// perguntas com vários itens ("agrupa", "indica todos", "quantos X há
// e quais"). O missing descreve o que ainda falta para o aluno melhorar
// na próxima.
async function aiValidateAnswer(exercise, studentAnswer) {
    const n = normalize(studentAnswer);
    if ((exercise.ans || []).some(a => {
        const na = normalize(a);
        return na === n || (n.length >= 3 && (na.includes(n) || n.includes(na)));
    })) return { status: 'correct' };
    const cacheKey = `aival_${exercise.id}_${n.slice(0, 40)}`;
    const cached = sessionStorage.getItem(cacheKey);
    if (cached !== null) {
        try { return JSON.parse(cached); }
        catch (_) { return { status: cached === '1' ? 'correct' : 'wrong' }; }
    }
    const correctAnswers = (exercise.ans || []).join(' ou ');
    const langNote = exercise.s === 'ingles'
        ? '\nThe answer must be in English — Portuguese words are NOT accepted as correct even if they mean the same thing.'
        : '';
    const prompt = `És um(a) professor(a) a corrigir uma resposta de aluno em PORTUGUÊS EUROPEU.

PERGUNTA: "${exercise.q}"
RESPOSTA ESPERADA: "${correctAnswers}"
RESPOSTA DO ALUNO: "${studentAnswer}"

Decide entre 3 status:
- "correct": resposta certa. Aceita variações de escrita, abreviaturas, formas equivalentes (ex.: "atlântico" vale para "Oceano Atlântico").
- "partial": resposta TEM parte certa MAS está INCOMPLETA. Usa SEMPRE quando a pergunta pede VÁRIOS itens ("agrupa", "indica TODOS", "lista", "quais são", "quantos X há e quais") e o aluno só identificou ALGUNS. Em "missing" diz o que falta (curto, em PT-PT, máx. 12 palavras).
- "wrong": resposta factualmente errada ou não responde à pergunta.

Exemplo: pergunta "Agrupa correr/bonito/livro/rapidamente por classes"; aluno escreve "bonito é adjetivo" → status "partial", missing "falta classificar correr (verbo), livro (substantivo), rapidamente (advérbio)".${langNote}

Responde APENAS com JSON, um destes formatos:
{"status":"correct"}
{"status":"partial","missing":"<o que falta>"}
{"status":"wrong"}`;
    try {
        const { text } = await callClaudeAPI(prompt, 220);
        const parsed = _extractJSON(text);
        let result = { status: 'wrong' };
        if (parsed && ['correct', 'partial', 'wrong'].includes(parsed.status)) {
            result = { status: parsed.status };
            if (parsed.status === 'partial' && typeof parsed.missing === 'string') {
                result.missing = parsed.missing.slice(0, 200);
            }
        }
        try { sessionStorage.setItem(cacheKey, JSON.stringify(result)); } catch {}
        return result;
    } catch(e) { return { status: 'unknown', error: String(e && e.message || e) }; }
}

// ========== SUBMIT ==========
async function submitAnswer() {
    if (!currentSession) return;
    const s = currentSession;
    if (s._submitting) return;
    if (s.results && s.results[s.idx] !== undefined) return;
    s._submitting = true;
    try {
        const e = s.items[s.idx];
        let isCorrect = false;
        if (e.type === 'mc') {
            if (selectedAnswer === null) { showToast('Escolhe uma opção'); return; }
            isCorrect = selectedAnswer === e.ans;
            document.querySelectorAll('#ex-answer-area .btn-option').forEach((el, idx) => {
                el.disabled = true;
                if (idx === e.ans) el.classList.add('correct');
                else if (idx === selectedAnswer) el.classList.add('wrong');
            });
        } else if (e.type === 'tf') {
            if (selectedAnswer === null) { showToast('Escolhe Verdadeiro ou Falso'); return; }
            isCorrect = selectedAnswer === e.ans;
        } else if (e.type === 'fill' || e.type === 'problem' || e.type === 'passage') {
            const val = document.getElementById('fill-input')?.value || '';
            if (!val.trim()) { showToast('Escreve uma resposta'); return; }
            const n = normalize(val);
            isCorrect = (e.ans || []).some(a => {
                // strict: comparação exata (maiúsculas/pontuação contam — ex: 'Hoje está sol.')
                if (e.strict) return String(val).trim() === String(a).trim();
                const fold = t => String(t).replace(/[\u2018\u2019\u02bc\u2032´`]/g, "'");
                const na = fold(normalize(a)); const nn = fold(n);
                const strip = t => t.replace(/^[\s.,;:!?«»"']+|[\s.,;:!?«»"']+$/g, '');
                if (na === nn || strip(na) === strip(nn)) return true;
                const compact = t => strip(t).replace(/[\s\-–]/g, '').replace(/[€$%]/g, '');
                if (compact(na) && compact(na) === compact(nn)) return true;
                // Respostas numéricas: compara como NÚMERO (7 000 = 7000; 1,5 = 1.5;
                // mas 15 ≠ 1,5 e 700 ≠ 7000). Só decide se AMBOS forem um número.
                if (/^-?\d[\d\s.]*(,\d+)?$/.test(na) && /^-?\d[\d\s.]*(,\d+)?$/.test(nn)) {
                    const num = t => { let c = t.replace(/\s/g, ''); if (c.includes(',')) c = c.replace(/\./g, '').replace(',', '.'); else if (/^-?\d{1,3}(\.\d{3})+$/.test(c)) c = c.replace(/\./g, ''); return Number(c); };
                    const x = num(na), y = num(nn);
                    if (Number.isFinite(x) && Number.isFinite(y)) return Math.abs(x - y) < 1e-9;
                }
                // Aceita se a resposta esperada aparece INTEIRA (palavra completa, com
                // pontuação à volta permitida) no que escreveu ('é o porto.' para
                // 'porto'); nunca o inverso ('casa' p/ 'casas').
                if ((nn.length >= 3 && na.length >= 3) || /^\d+$/.test(na)) { const esc = na.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); return new RegExp("(^|[^\\p{L}\\p{N}\\-'])" + esc + "(?=$|[^\\p{L}\\p{N}\\-'])", 'u').test(nn); }
                return false;
            });
            // Validação IA como fallback — só se não acertou no matching e há chave API.
            // Pode devolver "partial" (resposta tem parte certa mas falta completar).
            if (!isCorrect && hasAIKey()) {
                const btn = document.getElementById('submit-btn');
                if (btn) { btn.disabled = true; btn.textContent = 'A verificar…'; }
                let r;
                try { r = await aiValidateAnswer(e, val); }
                finally { if (btn) { btn.disabled = false; btn.textContent = 'Responder'; } }
                // Se a sessão mudou durante o await (ex: utilizador cancelou e
                // entrou noutra), descartar o resultado para não corromper a nova.
                if (currentSession !== s) return;
                isCorrect = r && r.status === 'correct';
                if (r && r.status === 'partial') {
                    s._partial = { missing: r.missing || '' };
                }
                if (r && r.status === 'unknown') showToast('IA indisponível — resposta avaliada pela regra simples.');
            }
        } else if (e.type === 'speak') {
            const tr = (speakState.transcript || '').trim();
            if (!tr) { showToast('Toca no microfone e diz a frase'); return; }
            const btn = document.getElementById('submit-btn');
            if (btn) { btn.disabled = true; btn.textContent = 'A avaliar…'; }
            let r;
            try { r = await aiValidateSpeech(e, tr); }
            finally { if (btn) { btn.disabled = false; btn.textContent = 'Responder'; } }
            if (currentSession !== s) return;
            r = r || { status: 'wrong' };
            isCorrect = r.status === 'correct';
            s._speakResult = { transcript: tr, status: r.status, corrected: r.corrected, tip: r.tip };
        } else if (e.type === 'order') {
            isCorrect = orderState.every((it, i) => it === e.items[i]);
        } else if (e.type === 'game' && e.game === 'sudoku4') {
            if (!sudokuState.solved) {
                const _full = sudokuState.grid.every(v => v !== 0);
                // Cheio mas não resolvido = há conflitos (mesma célula repete na
                // linha/coluna/bloco). Não digas "termina" — ela acha que terminou.
                showToast(_full
                    ? '🔎 Ainda há conflitos — corrige as células a vermelho (ou usa 💡 Pista)'
                    : 'Preenche todas as células primeiro');
                return;
            }
            isCorrect = sudokuState.hintsUsed < 3; // 3+ pistas = resolvido pela app
            const stars = '⭐'.repeat(Math.max(1, 3 - sudokuState.hintsUsed));
            const hintsLine = sudokuState.hintsUsed === 0
                ? '🏅 Sem ajudas — fizeste tudo sozinha!'
                : `🤝 Usaste a Pista do Detetive ${sudokuState.hintsUsed}× (${sudokuState.hintsUsed === 1 ? 'uma' : sudokuState.hintsUsed} vez${sudokuState.hintsUsed === 1 ? '' : 'es'}).`;
            e.exp = `${stars}  ·  ${sudokuState.moves} jogadas  ·  ${hintsLine}`;
        } else if (e.type === 'game' && e.game === 'cofre') {
            if (cofreState.input.length < cofreState.digits) { showToast('Falta(m) dígito(s)'); return; }
            isCorrect = cofreState.solved && cofreState.hintsUsed < 3;
            const stars = '⭐'.repeat(Math.max(1, 3 - cofreState.hintsUsed));
            e.exp = `${stars}  ·  Código: ${cofreState.solution}  ·  ${cofreState.hintsUsed === 0 ? '🏅 Sem pistas!' : '🤝 Usaste ' + cofreState.hintsUsed + ' pista' + (cofreState.hintsUsed===1?'':'s') + '.'}`;
        } else if (e.type === 'game' && e.game === 'cofre_steps') {
            if (!cstState.solved) { showToast('Termina todos os passos primeiro'); return; }
            isCorrect = cstState.hintsUsed < 3;
            const stars = '⭐'.repeat(Math.max(1, 3 - cstState.hintsUsed));
            const last = cstState.steps[cstState.steps.length - 1];
            e.exp = `${stars}  ·  Resultado: ${last && last.answer}  ·  ${cstState.hintsUsed === 0 ? '🏅 Sem pistas!' : '🤝 Usaste ' + cstState.hintsUsed + ' pista' + (cstState.hintsUsed===1?'':'s') + '.'}`;
        } else if (e.type === 'game' && e.game === 'estimador') {
            if (!estState.moved) { showToast('Move o cursor primeiro'); return; }
            const d = Math.abs(estState.value - estState.answer);
            isCorrect = d <= estState.tolerance;
            e.exp = `Resposta certa: ${estState.answer} ${estState.unit}. Tu disseste ${estState.value} (diferença ${d}).`;
        } else if (e.type === 'game' && e.game === 'suspeitos') {
            const picks = Object.entries(susState.states).filter(([, v]) => v === '✅');
            if (picks.length === 0) { showToast(susState.pick ? 'Toca na tua resposta primeiro' : 'Marca um suspeito com ✅'); return; }
            if (picks.length > 1) { showToast('Marca SÓ UM suspeito como ✅'); return; }
            isCorrect = picks[0][0] === susState.solution;
            const name = (susState.suspects.find(sp => sp.id === susState.solution) || {}).name || susState.solution;
            e.exp = (isCorrect ? '🎯 Acertaste — ' : (susState.pick ? 'A resposta certa era ' : 'O culpado era ')) + name + '.';
        } else if (e.type === 'game' && e.game === 'padrao') {
            if (!padState.input) { showToast('Escreve o número em falta'); return; }
            isCorrect = padState.input === padState.answer;
            e.exp = `Termo em falta: ${padState.answer}.`;
        } else if (e.type === 'game' && e.game === 'quantos') {
            if (!qtState.solved) { showToast('Toca no número certo primeiro'); return; }
            isCorrect = true;
            e.exp = `Eram ${qtState.dots} pontos. Os grupos de 5 ajudam a ver de relance!`;
        } else if (e.type === 'game' && e.game === 'cruzados') {
            const allFilled = cruzState.blanks.every(b => b.val != null);
            if (!allFilled) { showToast('Preenche todas as células vazias primeiro'); return; }
            // Já pode avançar mesmo com números errados: submete e vê a solução
            // (antes ficava presa sem perceber que os números estavam trocados).
            isCorrect = cruzState.solved;
            cruzState._answered = true;
            if (!e.exp) {
                const sols = cruzState.blanks.map(b => b.sol).join(', ');
                e.exp = 'Os números que faltavam eram: ' + sols + '.';
            }
        } else if (e.type === 'match') {
            const all = Object.keys(matchState.matched).length === matchState.leftItems.length;
            if (!all) { showToast('Completa todas as associações'); return; }
            isCorrect = Object.entries(matchState.matched).every(([li, ri]) => {
                const left = matchState.leftItems[li];
                const right = matchState.rightItems[ri];
                return e.pairs.some(p => p[0] === left && p[1] === right);
            });
        }
        if (currentSession !== s) return;
        recordAnswer(e, isCorrect);
        showFeedback(e, isCorrect);
    } finally {
        s._submitting = false;
    }
}

function recordAnswer(e, isCorrect) {
    const s = currentSession;
    s.results = s.results || [];
    s.results[s.idx] = isCorrect;
    let gained = 0;
    if (isCorrect) {
        gained = XP_BY_DIFF[e.diff] || 10;
        s.streak += 1;
        if (s.streak >= 3) gained += 5;
        s.correct++;
    } else {
        s.streak = 0;
        s.wrong++;
    }
    s.xp += gained;
    s._lastGain = gained; // para a animação de XP a saltar no feedback
    const sub = state.subjects[e.s] || { answered: 0, correct: 0, xp: 0 };
    sub.answered += 1;
    if (isCorrect) { sub.correct += 1; sub.xp += gained; }
    state.subjects[e.s] = sub;
    state.xp += gained;
    state.history.push({ id: e.id, s: e.s, c: isCorrect, d: todayStr() });
    if (state.history.length > 3000) state.history.shift();
    // Revisão espaçada (Leitner): um erro entra na caixa 0 e volta amanhã;
    // cada acerto sobe de caixa (3, 7, 16, 30 dias); 5 acertos seguidos =
    // dominado (sai). Só se acompanham perguntas que já foram erradas.
    try {
        state.srs = state.srs || {};
        const cur = state.srs[e.id];
        if (!isCorrect || cur) {
            const INT = [1, 3, 7, 16, 30];
            const box = isCorrect ? Math.min(5, ((cur && cur.box) || 0) + 1) : 0;
            if (box >= 5) delete state.srs[e.id];
            else { const due = new Date(); due.setDate(due.getDate() + INT[box]); state.srs[e.id] = { box, due: _localDayKey(due), last: todayStr() }; }
        }
    } catch {}
    state.recentIds = state.recentIds || [];
    state.recentIds.push(e.id);
    if (state.recentIds.length > 30) state.recentIds.shift();
    // Regista timestamp da última vez que foi vista (para rotação inteligente)
    state.exerciseSeen = state.exerciseSeen || {};
    state.exerciseSeen[e.id] = Date.now();
    // Tracking de mestria por tópico+dificuldade (progressão adaptativa)
    state.topicMastery = state.topicMastery || {};
    if (e.s && e.t) {
        const key = e.s + '/' + e.t;
        const m = state.topicMastery[key] || { d1: 0, d2: 0, d3: 0, w1: 0, w2: 0, w3: 0 };
        const d = Math.max(1, Math.min(3, e.diff || 1));
        if (isCorrect) m['d' + d] = (m['d' + d] || 0) + 1;
        else m['w' + d] = (m['w' + d] || 0) + 1;
        state.topicMastery[key] = m;
    }
    // Marca pergunta como vista no teste ativo (para evitar repetir em sessões futuras)
    if (s.testId) {
        const t = (state.tests || []).find(x => x.id === s.testId);
        if (t) {
            t.seenEx = t.seenEx || [];
            if (!t.seenEx.includes(e.id)) t.seenEx.push(e.id);
        }
    }
    saveState();
}

// Áudio: gera tons sintetizados sem assets (Web Audio API). Silencioso se o browser bloquear.
let _audioCtx = null;
function getAudioCtx() {
    if (_audioCtx) return _audioCtx;
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return null;
    try { _audioCtx = new Ctx(); } catch (_) { return null; }
    return _audioCtx;
}

// ---- sons estilo Duolingo ----
function _duoNote(ctx, freq, delayMs, durMs, peak) {
    const t0 = ctx.currentTime + delayMs / 1000;
    const dur = durMs / 1000;
    // Fundamental sine puro — brilhante e limpo como xilofone
    const osc = ctx.createOscillator();
    const g = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.value = freq;
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.linearRampToValueAtTime(peak, t0 + 0.003);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(g).connect(ctx.destination);
    osc.start(t0); osc.stop(t0 + dur + 0.05);
    // Harmónica oitava — dá corpo de sino, decay mais rápido
    const oscH = ctx.createOscillator();
    const gH = ctx.createGain();
    oscH.type = 'sine';
    oscH.frequency.value = freq * 2;
    gH.gain.setValueAtTime(0.0001, t0);
    gH.gain.linearRampToValueAtTime(peak * 0.28, t0 + 0.003);
    gH.gain.exponentialRampToValueAtTime(0.0001, t0 + dur * 0.5);
    oscH.connect(gH).connect(ctx.destination);
    oscH.start(t0); oscH.stop(t0 + dur + 0.05);
}
function _duoWrong(ctx, freq, delayMs, durMs, peak) {
    const t0 = ctx.currentTime + delayMs / 1000;
    const dur = durMs / 1000;
    const osc = ctx.createOscillator();
    const g = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, t0);
    osc.frequency.exponentialRampToValueAtTime(freq * 0.87, t0 + dur); // glide para baixo
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.linearRampToValueAtTime(peak, t0 + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(g).connect(ctx.destination);
    osc.start(t0); osc.stop(t0 + dur + 0.05);
}

function playCorrectSound() {
    // Duolingo: "ding ding" — dois sinos ascendentes D5 → A5
    const ctx = getAudioCtx();
    if (!ctx) return;
    if (ctx.state === 'suspended') { try { ctx.resume(); } catch (_) {} }
    _duoNote(ctx, 587,  0,  280, 0.28); // D5
    _duoNote(ctx, 880, 85,  380, 0.25); // A5
}

function playWrongSound() {
    // Duolingo: "dun dun" — dois tons descendentes Eb4 → Bb3
    const ctx = getAudioCtx();
    if (!ctx) return;
    if (ctx.state === 'suspended') { try { ctx.resume(); } catch (_) {} }
    _duoWrong(ctx, 311,   0, 250, 0.22); // Eb4
    _duoWrong(ctx, 233, 170, 300, 0.20); // Bb3
}

function playPerfectSound() {
    // Sessão 100% — fanfare ascendente C5→E5→G5→C6 (arpejo de Dó maior)
    const ctx = getAudioCtx();
    if (!ctx) return;
    if (ctx.state === 'suspended') { try { ctx.resume(); } catch (_) {} }
    _duoNote(ctx, 523,   0, 260, 0.24); // C5
    _duoNote(ctx, 659,  80, 260, 0.24); // E5
    _duoNote(ctx, 784, 160, 260, 0.24); // G5
    _duoNote(ctx, 1047,240, 550, 0.28); // C6 — nota longa final
}

function playVictorySound() {
    // ≥80% — G5→B5→D6 arpejo de Sol maior, alegre mas mais curto
    const ctx = getAudioCtx();
    if (!ctx) return;
    if (ctx.state === 'suspended') { try { ctx.resume(); } catch (_) {} }
    _duoNote(ctx, 784,   0, 250, 0.22); // G5
    _duoNote(ctx, 988,  75, 250, 0.22); // B5
    _duoNote(ctx, 1175,150, 400, 0.24); // D6
}

function playBadgeSound() {
    // Badge desbloqueado — sparkle: 3 notas agudas ascendentes rápidas
    const ctx = getAudioCtx();
    if (!ctx) return;
    if (ctx.state === 'suspended') { try { ctx.resume(); } catch (_) {} }
    _duoNote(ctx, 880,   0, 180, 0.18); // A5
    _duoNote(ctx, 1175,  55, 180, 0.17); // D6
    _duoNote(ctx, 1568, 110, 320, 0.16); // G6
}

function playRewardSound() {
    // Prémio desbloqueado — "chest open": arpejo mais lento e encorpado
    const ctx = getAudioCtx();
    if (!ctx) return;
    if (ctx.state === 'suspended') { try { ctx.resume(); } catch (_) {} }
    _duoNote(ctx, 392,   0, 200, 0.20); // G4
    _duoNote(ctx, 523,  80, 200, 0.20); // C5
    _duoNote(ctx, 659, 160, 200, 0.22); // E5
    _duoNote(ctx, 784, 240, 200, 0.22); // G5
    _duoNote(ctx, 1047,320, 550, 0.26); // C6 — nota de chegada longa
}

function playStreakSound() {
    // Streak novo — whoosh ascendente + ding final
    const ctx = getAudioCtx();
    if (!ctx) return;
    if (ctx.state === 'suspended') { try { ctx.resume(); } catch (_) {} }
    const t0 = ctx.currentTime;
    // Sweep de frequência ascendente (o "whoosh")
    const osc = ctx.createOscillator();
    const g = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(280, t0);
    osc.frequency.exponentialRampToValueAtTime(840, t0 + 0.22);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.linearRampToValueAtTime(0.16, t0 + 0.04);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.28);
    osc.connect(g).connect(ctx.destination);
    osc.start(t0); osc.stop(t0 + 0.32);
    // Ding de confirmação no fim do sweep
    _duoNote(ctx, 1047, 220, 350, 0.20); // C6
}

function playEncouragementSound() {
    // Meio da sessão — dois "dings" alegres mas discretos
    const ctx = getAudioCtx();
    if (!ctx) return;
    if (ctx.state === 'suspended') { try { ctx.resume(); } catch (_) {} }
    _duoNote(ctx, 659,  0, 200, 0.16); // E5
    _duoNote(ctx, 880, 70, 260, 0.15); // A5
}

const ENCOURAGE_MSGS = [
    { icon: '⭐', text: 'Estás a ir muito bem!' },
    { icon: '💪', text: 'Continua assim!' },
    { icon: '🌟', text: 'Boa! Estás no caminho certo!' },
    { icon: '🎉', text: 'Já levas mais de metade!' },
    { icon: '🚀', text: 'Quase a chegar ao fim!' },
    { icon: '👏', text: 'Excelente! Não pares!' }
];
function showEncouragement() {
    const s = currentSession;
    if (!s) return;
    // Mostra a meio (~50%) e a 75% se tiver pelo menos 4 perguntas, e só se acertou maioria até aqui
    const total = s.items.length;
    if (total < 4) return;
    const idx = s.idx + 1; // já respondida
    const half = Math.floor(total / 2);
    const threeQ = Math.floor(total * 0.75);
    const fireAt = (idx === half) || (idx === threeQ);
    if (!fireAt) return;
    const ratio = s.correct / Math.max(1, idx);
    if (ratio < 0.5) return; // só encorajar se está a conseguir
    let msg;
    if (idx === half)         msg = ENCOURAGE_MSGS[3]; // metade
    else if (ratio === 1)     msg = ENCOURAGE_MSGS[2]; // perfeito
    else                      msg = ENCOURAGE_MSGS[Math.floor(Math.random() * 3)];
    const banner = document.createElement('div');
    banner.className = 'ep-encourage';
    banner.innerHTML = `<span class="ep-encourage-icon">${msg.icon}</span><span class="ep-encourage-text">${msg.text}</span>`;
    document.body.appendChild(banner);
    playEncouragementSound();
    requestAnimationFrame(() => banner.classList.add('show'));
    setTimeout(() => { banner.classList.remove('show'); setTimeout(() => banner.remove(), 400); }, 1800);
}

function showFeedback(e, isCorrect) {
    // Detecta resposta parcial (só fill-in via IA pode marcar — ver submitAnswer)
    const partial = (!isCorrect && currentSession?._partial) || null;
    if (currentSession) currentSession._partial = null; // consumido aqui
    if (isCorrect) playCorrectSound(); else playWrongSound();
    _haptic(isCorrect ? 'ok' : 'wrong');
    // Mascote reage (se o ecra do curso estiver visivel)
    if (window._courseMascot && window._courseMascot.el && window._courseMascot.el.isConnected) {
        window._courseMascot.react(isCorrect ? 'happy' : 'sad');
    }
    // Esconder botão IA inline (a pista só faz sentido ANTES de responder)
    const profWrap = document.getElementById('ex-prof-ia-wrap');
    if (profWrap) profWrap.style.display = 'none';
    // Trancar a área de resposta: esconder botões "Responder" e bloquear
    // interação (não dá para clicar opções, arrastar, escrever). O utilizador
    // é direccionado para o painel de feedback que aparece logo abaixo.
    const answerArea = document.getElementById('ex-answer-area');
    if (answerArea) {
        answerArea.style.pointerEvents = 'none';
        answerArea.querySelectorAll('button.btn-primary-solid').forEach(b => {
            // Esconde apenas botões "Responder" — preserva qualquer outro
            if ((b.textContent || '').trim().toLowerCase().startsWith('responder')) {
                b.style.display = 'none';
            }
        });
        answerArea.querySelectorAll('input, textarea').forEach(el => { el.disabled = true; });
    }
    const panel = document.getElementById('ex-feedback');
    panel.style.display = 'block';
    document.getElementById('feedback-icon').innerHTML = isCorrect ? '\u{1F389}' : (partial ? '\u{1F914}' : '\u{1F914}');
    if (isCorrect) {
        try { _showConfetti(); } catch {}
        // Combo de acertos seguidos + XP a saltar — o gancho das sessões curtas.
        try { _showCombo(currentSession ? currentSession.streak : 0, currentSession && currentSession._lastGain); } catch {}
    }
    const txt = document.getElementById('feedback-text');
    if (partial) {
        txt.textContent = 'Incompleto…';
        txt.className = 'feedback-text feedback-partial';
    } else {
        txt.textContent = isCorrect ? 'Certo!' : 'Ainda não…';
        txt.className = 'feedback-text ' + (isCorrect ? 'feedback-correct' : 'feedback-wrong');
    }
    let expParts = [];
    if (partial && partial.missing) {
        expParts.push(`Falta: ${partial.missing}.`);
    }
    if (!isCorrect) {
        // Mostra sempre a resposta certa — pode repetir no final da sessão
        if (e.type === 'mc') expParts.push(`Resposta certa: ${e.opts[e.ans]}.`);
        else if (e.type === 'tf') expParts.push(`Resposta certa: ${e.ans ? 'Verdadeiro' : 'Falso'}.`);
        else if (e.type === 'fill' || e.type === 'problem') expParts.push(`Resposta certa: ${e.ans[0]}.`);
        else if (e.type === 'order') expParts.push(`Ordem certa: ${e.items.join(' > ')}.`);
        else if (e.type === 'speak') {
            const r = currentSession?._speakResult;
            if (r) {
                expParts.push(`🎙️ Disseste: "${r.transcript}"`);
                if (r.corrected) expParts.push(`✅ Versão correta: "${r.corrected}"`);
                if (r.tip) expParts.push(`💡 ${r.tip}`);
            } else {
                expParts.push(`Resposta esperada: ${e.ans[0]}.`);
            }
        }
        if (e.exp) expParts.push(e.exp);
    } else if (e.type === 'speak') {
        const r = currentSession?._speakResult;
        if (r) expParts.push(`🎙️ Disseste: "${r.transcript}"`);
    }
    if (e.material)  expParts.push(`📘 ${e.material}`);
    if (e.solution)  expParts.push(`📐 Resolução: ${e.solution}`);
    if (e.exp && isCorrect) expParts.push(e.exp);
    // Render markdown leve (**bold**/*italic*) na explicação
    const _renderMdExp = (s) => escapeHtml(s || '')
        .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
        .replace(/(^|[^*])\*([^*\n]+)\*(?!\*)/g, '$1<em>$2</em>');
    const expEl = document.getElementById('feedback-exp');
    // svgAfter: visualização da solução (mostrada no feedback). Se o exercício
    // não tiver svgAfter mas tiver svg, mostra o svg original na altura do
    // feedback (sem repetir se for visualmente igual ao da pergunta).
    let visualFB = '';
    if (e.svgAfter) {
        visualFB = `<div style="margin:0 0 10px;text-align:center">${e.svgAfter}</div>`;
    }
    expEl.innerHTML = visualFB + expParts.map(p => _renderMdExp(p)).join('<br><br>');
    // v455: renderiza explicação rica se existir no exercício
    try { _renderRichExp(e); } catch {}
    // Botões dedicados para exercícios speak: ouvir a versão correta + repetir a tentativa
    if (e.type === 'speak') {
        const r = currentSession?._speakResult;
        const modelTxt = (r && r.corrected) ? r.corrected : (e.ans?.[0] || '');
        const lang = e.lang || 'en-US';
        if (modelTxt) {
            const btnRow = document.createElement('div');
            btnRow.style.cssText = 'display:flex;gap:8px;margin-top:12px';
            btnRow.innerHTML = `<button class="speak-fb-listen" style="flex:1;background:linear-gradient(135deg,#0891b2,#2563eb);color:#fff;border:none;border-radius:10px;padding:10px;font-size:0.85rem;font-weight:700;cursor:pointer"><i class="fas fa-volume-high"></i>&nbsp;Ouvir versão correta</button>`;
            btnRow.querySelector('.speak-fb-listen').addEventListener('click', () => ttsSpeakEN(modelTxt, lang));
            expEl.appendChild(btnRow);
        }
    }
    expEl.style.whiteSpace = 'pre-wrap';
    document.getElementById('feedback-exp').style.textAlign = 'left';
    // Botão explicação detalhada: sempre visível
    const detailBtn = document.getElementById('feedback-detail-btn');
    const detailWrap = document.getElementById('feedback-detail-wrap');
    if (detailWrap) { detailWrap.style.display = 'none'; detailWrap.innerHTML = ''; }
    if (detailBtn) {
        detailBtn.style.display = 'block';
        detailBtn.textContent = '💡 Explicar passo a passo';
        detailBtn.disabled = false;
    }
    // "Explica o teu raciocínio" — só Matemática (treina a comunicação/justificação matemática)
    const reasonBtn = document.getElementById('feedback-reason-btn');
    const reasonWrap = document.getElementById('feedback-reason-wrap');
    if (reasonWrap) { reasonWrap.style.display = 'none'; reasonWrap.innerHTML = ''; }
    if (reasonBtn) {
        const isMath = e && (e.s === 'matematica' || e.s === 'mat_plus');
        reasonBtn.style.display = isMath ? 'block' : 'none';
        reasonBtn.disabled = false;
        reasonBtn.innerHTML = '<i class="fas fa-pen-fancy"></i> Explica o teu raciocínio';
    }
    // Barra de ação passa a "Continuar" / "Ver resultado"
    const isLast = currentSession.idx + 1 >= currentSession.items.length;
    _setExAction('continue', isLast ? 'Ver resultado' : 'Continuar');
    // Animar XP se aumentou + floating "+N XP" sobre o feedback
    _bumpSessionXP(currentSession.xp, isCorrect);
    // Combo indicator: 3+ certas seguidas mostra "COMBO xN"
    _updateCombo(isCorrect ? (currentSession.streak || 0) : 0);
    // Garantir que o utilizador vê o feedback — scroll suave para o painel
    requestAnimationFrame(() => panel.scrollIntoView({ behavior: 'smooth', block: 'center' }));
}

// ============================================================
// Animações Duolingo-style: combo / XP bump / floating XP
// ============================================================
let _lastSessionXP = 0;
function _bumpSessionXP(newXP, isCorrect) {
    const wrap = document.querySelector('.session-xp');
    const span = document.getElementById('session-xp');
    if (!span) return;
    const gain = newXP - _lastSessionXP;
    span.textContent = newXP;
    _lastSessionXP = newXP;
    if (isCorrect && gain > 0 && wrap) {
        wrap.classList.remove('bump');
        // Forçar reflow para reiniciar a animação
        void wrap.offsetWidth;
        wrap.classList.add('bump');
        // Float "+N XP" perto do indicador de XP
        try {
            const rect = wrap.getBoundingClientRect();
            const float = document.createElement('div');
            float.className = 'xp-float';
            float.textContent = '+' + gain + ' XP';
            float.style.left = (rect.left + rect.width/2 - 30) + 'px';
            float.style.top  = (rect.bottom + 4) + 'px';
            document.body.appendChild(float);
            setTimeout(() => float.remove(), 1200);
        } catch {}
    }
}
function _updateCombo(streakCount) {
    let combo = document.getElementById('session-combo');
    if (streakCount < 3) {
        if (combo) combo.remove();
        return;
    }
    if (!combo) {
        combo = document.createElement('div');
        combo.id = 'session-combo';
        combo.className = 'session-combo';
        // Inserir junto ao session-xp
        const xp = document.querySelector('.session-xp');
        if (xp && xp.parentNode) xp.parentNode.insertBefore(combo, xp);
    }
    combo.innerHTML = '🔥 COMBO ×' + streakCount;
    combo.classList.remove('bump');
    void combo.offsetWidth;
    combo.classList.add('bump');
}

// ============================================================
// Action bar (Duolingo-style): UM botão fixo no fundo que alterna
// entre "Responder" e "Continuar"/"Ver resultado".
// ============================================================
let _exActionMode = 'submit';
function _setExAction(mode, label) {
    _exActionMode = mode;
    const bar = document.getElementById('ex-action-bar');
    const btn = document.getElementById('ex-action-btn');
    if (!btn || !bar) return;
    // Modo escondido — usado pelo roleplay, que se conduz sozinho
    if (mode === 'hidden') { bar.style.display = 'none'; return; }
    bar.style.display = '';
    if (mode === 'continue') {
        bar.classList.add('is-continue');
        bar.classList.remove('has-selection');
        btn.innerHTML = (label || 'Continuar') + ' <i class="fas fa-arrow-right"></i>';
    } else {
        bar.classList.remove('is-continue');
        bar.classList.remove('has-selection');
        btn.innerHTML = 'Responder';
    }
}
function _markActionHasSelection(has) {
    const bar = document.getElementById('ex-action-bar');
    if (bar) bar.classList.toggle('has-selection', !!has && _exActionMode === 'submit');
}
function exActionTap() {
    if (_exActionMode === 'continue') feedbackNext();
    else submitAnswer();
}
window.exActionTap = exActionTap;

// ============================================================
// Manter a action-bar visível quando o teclado iOS abre.
// iOS shrink-encolhe o visualViewport mas o layout viewport não.
// Usamos visualViewport API para subir a barra acima do teclado.
// ============================================================
(function _setupActionBarKeyboardFix() {
    if (typeof window === 'undefined' || !window.visualViewport) return;
    const adjust = () => {
        const bar = document.getElementById('ex-action-bar');
        if (!bar) return;
        const vv = window.visualViewport;
        const hidden = window.innerHeight - (vv.height + vv.offsetTop);
        if (hidden > 80) {
            // Teclado aberto — fixar a barra acima dele
            bar.style.position = 'fixed';
            bar.style.left = '0';
            bar.style.right = '0';
            bar.style.bottom = hidden + 'px';
            bar.style.maxWidth = '480px';
            bar.style.margin = '0 auto';
            bar.style.zIndex = '100';
            // Garantir que o input está visível ACIMA da action bar.
            // Sem isto, a barra pode tapar o input (bug reportado em iPad
            // landscape: "Se for uma imagem o responder fica em cima do
            // campo da resposta").
            const input = document.getElementById('fill-input');
            if (input && document.activeElement === input) {
                requestAnimationFrame(() => {
                    const r = input.getBoundingClientRect();
                    const barH = bar.offsetHeight || 64;
                    const visibleBottom = vv.height - barH - 12;
                    if (r.bottom > visibleBottom) {
                        const delta = r.bottom - visibleBottom;
                        window.scrollBy({ top: delta, behavior: 'smooth' });
                    }
                });
            }
        } else {
            // Teclado fechado — voltar a sticky
            bar.style.position = '';
            bar.style.left = '';
            bar.style.right = '';
            bar.style.bottom = '';
            bar.style.maxWidth = '';
            bar.style.margin = '';
            bar.style.zIndex = '';
        }
    };
    window.visualViewport.addEventListener('resize', adjust);
    window.visualViewport.addEventListener('scroll', adjust);
    // Também ajustar quando um fill-input ganha focus
    document.addEventListener('focusin', (e) => {
        if (e.target && e.target.id === 'fill-input') {
            setTimeout(adjust, 100);
            setTimeout(adjust, 400);
        }
    });
})();

// Avança para a próxima pergunta (ou termina a sessão)
function feedbackNext() {
    if (!currentSession) return;
    nextQuestion();
}

// Constrói o prompt detalhado do Professor IA — explicação pós-resposta com passos
function _buildDetailedExplanationPrompt(e, yr) {
    const subName = SUBJECTS[e.s]?.name || e.s;

    // Resposta certa em texto legível por tipo
    let correctAns;
    if (e.type === 'mc') correctAns = e.opts[e.ans];
    else if (e.type === 'tf') correctAns = e.ans ? 'Verdadeiro' : 'Falso';
    else if (e.type === 'order') correctAns = (e.items || []).join(' > ');
    else if (e.type === 'match' && e.pairs) correctAns = e.pairs.map(p => `${p[0]} ↔ ${p[1]}`).join('; ');
    else if (e.type === 'game' && e.game === 'sudoku4' && e.puzzle && e.puzzle.solution) correctAns = 'Sudoku resolvido: ' + e.puzzle.solution.join(',');
    else if (e.type === 'game' && e.game === 'cofre' && e.solution) correctAns = 'Código: ' + e.solution;
    else if (e.type === 'game' && e.game === 'cofre_steps' && Array.isArray(e.steps)) correctAns = 'Passos: ' + e.steps.map((s, i) => (i+1) + ') ' + s.answer).join('  ');
    else if (e.type === 'game' && e.game === 'estimador' && e.answer !== undefined) correctAns = String(e.answer) + (e.unit ? ' ' + e.unit : '');
    else if (e.type === 'game' && e.game === 'suspeitos' && e.solution) correctAns = (e.pick ? 'Resposta: ' : 'Culpado: ') + (((e.suspects || []).find(sp => sp.id === e.solution) || {}).name || e.solution);
    else if (e.type === 'game' && e.game === 'padrao' && e.answer) correctAns = String(e.answer);
    else if (e.type === 'game' && e.game === 'quantos' && e.dots !== undefined) correctAns = String(e.dots) + ' pontos';
    else if (e.type === 'game' && e.game === 'cruzados') correctAns = 'Grelha completa com todas as contas certas';
    else correctAns = Array.isArray(e.ans) ? e.ans[0] : String(e.ans);

    let qContext = `Disciplina: ${subName}\nTópico: ${e.t}\nPergunta: "${e.q}"\nResposta CERTA: ${correctAns}`;
    if (e.type === 'mc' && e.opts) qContext += `\nOpções apresentadas: ${e.opts.map((o,i)=>`${String.fromCharCode(65+i)}) ${o}`).join(' | ')}`;
    if (e.passage) qContext += `\nTexto de apoio: "${e.passage.slice(0, 400)}"`;
    if (e.material) qContext += `\nRegra do tópico: "${e.material}"`;
    if (e.exp) qContext += `\nNota curta do exercício: "${e.exp}"`;
    if (e.solution) qContext += `\nResolução resumida: "${e.solution}"`;

    // Lição estática para fundamentar
    const lesson = LESSONS[`${e.s}/${e.t}`] || state.maxLessons?.[`${e.s}/${e.t}`];
    if (lesson) {
        const lessonSnippet = lesson.body.replace(/\*\*/g, '').slice(0, 800);
        qContext += `\n\n--- Conteúdo do tópico (currículo, usa-o como base) ---\n${lessonSnippet}\n--- fim ---`;
    }

    // Estilo por faixa etária + tamanho
    let ageStyle, length;
    if (yr <= 2) {
        ageStyle = 'Estás a falar com uma criança de 7-8 anos. Frases CURTAS, palavras simples, exemplos do dia-a-dia (animais, comida, brincadeiras). Tom carinhoso. 1-2 emojis ajudam.';
        length = '3-4 frases muito curtas';
    } else if (yr <= 4) {
        ageStyle = `Estás a falar com uma criança do ${yr}.º ano (8-10 anos). Frases simples, com 1 exemplo concreto. Tom amigável, sem infantilizar.`;
        length = '4-6 frases claras';
    } else {
        ageStyle = `Estás a falar com um aluno do ${yr}.º ano (10-12 anos). Tom de professor/a, vocabulário próprio mas explicado. Sem rodeios.`;
        length = '5-8 frases ou 4-6 passos';
    }

    const isMath = e.s === 'matematica';
    const isEnglishY2 = e.s === 'ingles' && yr <= 2;

    return `És um professor/professora do ${yr}.º ano do Ensino Básico português, em Portugal. O aluno acabou de responder à pergunta abaixo (terá acertado ou errado — não interessa). Vais explicar-lhe DETALHADAMENTE, em Português Europeu (Portugal), como se chega à resposta certa, para ele perceber bem o assunto.

${qContext}

${ageStyle}

Estrutura da tua resposta (segue EXACTAMENTE este formato):

📚 O que está em causa
[Explica em 1-2 frases o conceito/regra envolvido nesta pergunta, ligado ao tópico "${e.t}".]

🪜 Passo a passo
${isMath ? `1. [Identifica o que a pergunta pede]
2. [Mostra o cálculo ou raciocínio passo a passo, com os números/operações concretos desta pergunta]
3. [Chega à resposta: ${correctAns}]
${yr >= 5 ? '4. [Confirma o resultado ou mostra como verificar]' : ''}` : `1. [Primeiro passo do raciocínio para esta pergunta concreta]
2. [Segundo passo, aplicando a regra ao caso]
3. [Conclusão: porquê a resposta é "${correctAns}"]
${yr >= 5 ? '4. [Reforço ou exemplo análogo]' : ''}`}

✅ Resposta: ${correctAns}
[Frase curta a justificar porquê esta é a resposta — sem repetir os passos.]

${isEnglishY2 ? '🇬🇧 Em Inglês: [palavra/frase inglesa] → 🇵🇹 Em Português: [tradução]\n[Dica de memorização para a criança.]' : ''}

Regras OBRIGATÓRIAS:
- Português EUROPEU (Portugal): "estás", "tu", "comboio", "autocarro", "rapariga"/"rapaz", "ecrã", "pequeno-almoço" — NUNCA "você", "trem", "ônibus", "garota"/"garoto", "tela", "café da manhã"
- ${length} no total (não escrevas demasiado)
- NÃO comentes a tua explicação ("vou explicar...", "espero ter ajudado", "como podes ver")
- NÃO digas coisas como "a resposta dada está correcta" ou "depende da interpretação"
- Vai DIRECTO ao conteúdo
- Sem markdown (**negrito**, # títulos), sem JSON, sem chavetas
- Usa SEMPRE as 3 secções acima com os emojis 📚 🪜 ✅ no início`;
}

// Renderiza a explicação detalhada em HTML rico
function _renderDetailedExplanationHtml(rawText) {
    const text = String(rawText || '').trim();
    const causaMatch = text.match(/📚\s*O que está em causa[:\s]*\n?([\s\S]*?)(?=\n*🪜|\n*✅|\n*🇬🇧|$)/);
    const passosMatch = text.match(/🪜\s*Passo a passo[:\s]*\n?([\s\S]*?)(?=\n*✅|\n*🇬🇧|\n*📚|$)/);
    const respMatch = text.match(/✅\s*Resposta[:\s]*([\s\S]*?)(?=\n*🇬🇧|\n*📚|\n*🪜|$)/);
    const engMatch = text.match(/🇬🇧[\s\S]*$/);

    let html = '';
    if (causaMatch) {
        const body = escapeHtml(causaMatch[1].trim()).replace(/\n+/g, '<br>');
        html += `<div style="margin-bottom:14px"><div style="font-weight:700;color:#1d4ed8;margin-bottom:4px;font-size:0.88rem">📚 O que está em causa</div><div>${body}</div></div>`;
    }
    if (passosMatch) {
        const passosRaw = passosMatch[1].trim();
        const lines = passosRaw.split('\n').map(l => l.trim()).filter(Boolean);
        const numbered = lines.filter(l => /^\d+\.?\s/.test(l));
        let passosHtml;
        if (numbered.length >= 2) {
            passosHtml = '<ol style="margin:0;padding-left:22px">' +
                numbered.map(l => `<li style="margin-bottom:6px">${escapeHtml(l.replace(/^\d+\.?\s*/, ''))}</li>`).join('') +
                '</ol>';
        } else {
            passosHtml = `<div>${escapeHtml(passosRaw).replace(/\n+/g, '<br>')}</div>`;
        }
        html += `<div style="margin-bottom:14px"><div style="font-weight:700;color:#1d4ed8;margin-bottom:6px;font-size:0.88rem">🪜 Passo a passo</div><div>${passosHtml}</div></div>`;
    }
    if (respMatch) {
        const body = escapeHtml(respMatch[1].trim()).replace(/\n+/g, '<br>');
        html += `<div style="margin-bottom:10px;padding:10px 12px;background:#dcfce7;border-left:4px solid #16a34a;border-radius:8px"><div style="font-weight:700;color:#166534;margin-bottom:2px;font-size:0.88rem">✅ Resposta</div><div style="color:#14532d">${body}</div></div>`;
    }
    if (engMatch) {
        const body = escapeHtml(engMatch[0].trim()).replace(/\n+/g, '<br>');
        html += `<div style="margin-top:8px;padding:10px 12px;background:#fef9c3;border-left:4px solid #eab308;border-radius:8px;font-size:0.88rem">${body}</div>`;
    }

    if (!html) html = `<div>${escapeHtml(text).replace(/\n+/g, '<br>')}</div>`;
    return html;
}

async function loadDetailedExplanation() {
    const e = currentSession.items[currentSession.idx];
    const btn = document.getElementById('feedback-detail-btn');
    const wrap = document.getElementById('feedback-detail-wrap');
    const cacheKey = `detail_v2_${e.id}`;
    const cached = sessionStorage.getItem(cacheKey);
    if (cached) { wrap.innerHTML = cached; wrap.style.display = 'block'; btn.style.display = 'none'; return; }

    // Lição estática (fallback se IA falhar ou não houver chave — currículo completo)
    const lessonKey = `${e.s}/${e.t}`;
    const lesson = LESSONS[lessonKey] || state.maxLessons?.[lessonKey];
    const showLesson = () => {
        const html = `<strong>${escapeHtml(lesson.title || '')}</strong><br><br>${escapeHtml(lesson.body).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>')}`;
        try { sessionStorage.setItem(cacheKey, html); } catch {}
        wrap.innerHTML = html; wrap.style.display = 'block'; btn.style.display = 'none';
    };

    // Sem API key → lição estática se existir, senão e.exp
    if (!hasAIKey()) {
        if (lesson) return showLesson();
        const fallback = e.exp || 'Não há explicação detalhada disponível para esta pergunta.';
        wrap.innerHTML = escapeHtml(fallback).replace(/\n/g, '<br>');
        wrap.style.display = 'block'; btn.style.display = 'none';
        return;
    }

    // Com API key → IA detalhada
    btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> A pensar…'; btn.disabled = true;
    const yr = activeProfile()?.year || 6;
    const prompt = _buildDetailedExplanationPrompt(e, yr);
    try {
        const { text } = await callClaudeAPI(prompt, 700, false);
        let clean = text.trim();
        if (clean.startsWith('{')) {
            try {
                const obj = JSON.parse(clean);
                clean = Object.values(obj).filter(v => typeof v === 'string').join('\n');
            } catch(_) {
                clean = clean.replace(/[{}"]/g, '').replace(/\b\w+:/g, '').trim();
            }
        }
        const html = _renderDetailedExplanationHtml(clean);
        try { sessionStorage.setItem(cacheKey, html); } catch {}
        wrap.innerHTML = html; wrap.style.display = 'block'; btn.style.display = 'none';
    } catch(err) {
        if (lesson) return showLesson();
        const fallback = e.exp
            ? `${escapeHtml(e.exp).replace(/\n/g,'<br>')}<br><br><em style="color:#9ca3af">(IA indisponível: ${String(err.message || err).slice(0, 100)})</em>`
            : `<em style="color:#dc2626">Erro: ${String(err.message || err).slice(0, 200)}</em>`;
        wrap.innerHTML = fallback;
        wrap.style.display = 'block'; btn.style.display = 'none';
    }
}

// ===== "Explica o teu raciocínio" — treina a comunicação/justificação matemática =====
function _exCorrectAnswerText(e) {
    if (!e) return '';
    if (e.type === 'mc' && Array.isArray(e.opts) && typeof e.ans === 'number') return e.opts[e.ans] || '';
    if (e.type === 'tf') return e.ans ? 'Verdadeiro' : 'Falso';
    if (Array.isArray(e.ans)) return e.ans[0] || '';
    if (typeof e.ans === 'string' || typeof e.ans === 'number') return String(e.ans);
    return '';
}
function startReasonExplain() {
    const wrap = document.getElementById('feedback-reason-wrap');
    const btn = document.getElementById('feedback-reason-btn');
    if (!wrap) return;
    if (btn) btn.style.display = 'none';
    wrap.style.display = 'block';
    wrap.innerHTML = `
      <div class="reason-box">
        <div class="reason-q">Explica, por palavras tuas, como se chega à resposta:</div>
        <textarea id="reason-input" class="reason-input" rows="3" placeholder="Ex: Como 1 m = 100 cm, a metade é 100 ÷ 2 = 50 cm."></textarea>
        <button class="btn btn-block reason-send" onclick="submitReasonExplain()" style="margin-top:8px"><i class="fas fa-check"></i> Avaliar o meu raciocínio</button>
      </div>`;
    setTimeout(() => { const ta = document.getElementById('reason-input'); if (ta) ta.focus(); }, 120);
}
window.startReasonExplain = startReasonExplain;
async function submitReasonExplain() {
    const e = currentSession && currentSession.items && currentSession.items[currentSession.idx];
    const wrap = document.getElementById('feedback-reason-wrap');
    const ta = document.getElementById('reason-input');
    const said = (ta && ta.value || '').trim();
    if (!e || !wrap) return;
    if (!said) { if (typeof showToast === 'function') showToast('Escreve a tua explicação primeiro'); return; }
    const sendBtn = wrap.querySelector('.reason-send');
    if (sendBtn) { sendBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> A avaliar…'; sendBtn.disabled = true; }
    if (!hasAIKey()) {
        wrap.innerHTML = `<div class="reason-box reason-result"><div class="reason-fb">Para avaliar o teu raciocínio com feedback, configura uma chave IA (Mistral) no Perfil.</div>${e.exp ? `<div class="reason-model"><b>📝 Explicação-modelo</b><div>${escapeHtml(e.exp).replace(/\n/g, '<br>')}</div></div>` : ''}</div>`;
        return;
    }
    const yr = (typeof activeProfile === 'function' && activeProfile()?.year) || 6;
    const prompt = _buildReasonEvalPrompt(e, said, yr);
    try {
        const { text } = await callClaudeAPI(prompt, 700, true);
        const d = _extractJSON(text) || {};
        wrap.innerHTML = _renderReasonEval(d, e);
    } catch (err) {
        wrap.innerHTML = `<div class="reason-box reason-result"><div class="reason-fb">Não consegui avaliar agora. Tenta outra vez.</div>${e.exp ? `<div class="reason-model"><b>📝 Explicação-modelo</b><div>${escapeHtml(e.exp).replace(/\n/g, '<br>')}</div></div>` : ''}</div>`;
    }
}
window.submitReasonExplain = submitReasonExplain;
function _buildReasonEvalPrompt(e, said, yr) {
    const correct = _exCorrectAnswerText(e);
    return `És um professor de Matemática (Portugal, AE 2018) a avaliar a EXPLICAÇÃO DO RACIOCÍNIO de um aluno do ${yr}.º ano (avalias a justificação/comunicação, não só a resposta final).
Problema: "${(e.q || '').replace(/"/g, "'")}"
Resposta correta: "${String(correct).replace(/"/g, "'")}"
Explicação de referência: "${(e.exp || '').replace(/"/g, "'")}"
O aluno explicou assim: "${said.replace(/"/g, "'")}"
Avalia a QUALIDADE da explicação: os passos estão certos e por ordem? justifica o "porquê"? usa linguagem matemática adequada? Sê encorajador mas honesto.
Devolve JSON ESTRITO em PORTUGUÊS EUROPEU (Portugal, nunca brasileiro):
{"nivel":"bom"|"parcial"|"fraco","feedback":"1-2 frases, específico e encorajador","bem":"o que esteve bem (curto; vazio se nada)","falta":"o que falta ou está errado no raciocínio (curto; vazio se nada)","modelo":"explicação-modelo do raciocínio, 2-4 passos curtos","frases":["frase-modelo para o aluno aprender a redigir a justificação","outra frase-modelo"]}`;
}
function _renderReasonEval(d, e) {
    d = d || {};
    const lvl = (d.nivel || '').toLowerCase();
    const badge = lvl === 'bom' ? '<span class="reason-badge ok">✓ Bom raciocínio</span>'
        : lvl === 'parcial' ? '<span class="reason-badge mid">≈ Quase lá</span>'
        : '<span class="reason-badge no">Vamos melhorar</span>';
    const frases = Array.isArray(d.frases) ? d.frases.filter(Boolean).slice(0, 3) : [];
    const modelo = d.modelo || (e && e.exp) || '';
    return `<div class="reason-box reason-result">
        ${badge}
        ${d.feedback ? `<div class="reason-fb">${escapeHtml(d.feedback)}</div>` : ''}
        ${d.bem ? `<div class="reason-line bem"><b>👍 Bem:</b> ${escapeHtml(d.bem)}</div>` : ''}
        ${d.falta ? `<div class="reason-line falta"><b>🔧 Falta:</b> ${escapeHtml(d.falta)}</div>` : ''}
        ${modelo ? `<div class="reason-model"><b>📝 Explicação-modelo</b><div>${escapeHtml(modelo).replace(/\n/g, '<br>')}</div></div>` : ''}
        ${frases.length ? `<div class="reason-frames"><b>✍️ Frases que podes usar</b>${frases.map(f => `<div class="reason-frame">${escapeHtml(f)}</div>`).join('')}</div>` : ''}
        <button class="btn btn-block reason-retry" onclick="startReasonExplain()" style="margin-top:8px"><i class="fas fa-rotate-right"></i> Tentar explicar outra vez</button>
    </div>`;
}
window._renderReasonEval = _renderReasonEval;
// Depois de ERRAR: abre o resumo do tópico com PORTÃO DE LEITURA antes de
// deixar avançar. É aqui que a leitura é obrigatória — errar é o sinal de
// que precisa mesmo de ler. Uma vez por tópico por sessão (não martela).
function _maybeForceLessonAfterWrong() {
    try {
        const s = currentSession;
        if (!s || !Array.isArray(s.items)) return false;
        if (s.results && s.results[s.idx] !== false) return false; // acertou (ou sem resposta)
        if (s.isDuel || s.fbDuelId) return false; // duelo cronometrado: nunca bloquear
        const e = s.items[s.idx];
        if (!e || !e.s || !e.t) return false;
        const key = e.s + '/' + e.t;
        const lesson = (window.LESSONS && window.LESSONS[key]) || (state.maxLessons && state.maxLessons[key]);
        if (!lesson) return false;
        s._forcedLessons = s._forcedLessons || [];
        if (s._forcedLessons.includes(key)) return false; // já leu por erro nesta sessão
        s._forcedLessons.push(key);
        // Acabou de ler → marca como visto (senão o auto-show do tópico novo
        // reabria o mesmo resumo na pergunta seguinte).
        try { const pr = activeProfile(); if (pr) { pr.lessonsSeen = pr.lessonsSeen || {}; pr.lessonsSeen[key] = Date.now(); saveState(); } } catch {}
        _lessonGateOnClose = () => { nextQuestion(); };
        openLessonByKey(key, { gated: true, why: 'erro' });
        return true;
    } catch (err) { console.warn('[force-lesson]', err); return false; }
}
function nextQuestion() {
    if (!currentSession) return; // sessão terminada entretanto (timer de duelo, saída)
    if (_maybeForceLessonAfterWrong()) return; // avança quando fechar o resumo
    showEncouragement();
    currentSession.idx += 1;
    if (currentSession.idx >= currentSession.items.length) finishSession();
    else renderQuestion();
}

function finishSession() {
    const s = currentSession;
    // Duelo Firestore (novo, v266+)
    if (s && s.fbDuelId) {
        _finishFirestoreDuel();
        return;
    }
    // Duelo legacy via URL ?duel=base64
    if (s && s.isDuel) {
        _finishDuel();
        return;
    }
    // Modo Curso: regista resultado da lição (isolado, não interfere com nada)
    try { _recordCourseLessonResult(s); } catch (e) { console.warn('[course] record failed', e); }
    // Registo detalhado da sessão (para o "Dia a dia" das Estatísticas):
    // disciplina dominante, nº perguntas, certas, e DURAÇÃO em segundos.
    try {
        if (s && Array.isArray(s.items) && s.items.length > 0) {
            const bySubjN = {};
            s.items.forEach(it => { if (it && it.s) bySubjN[it.s] = (bySubjN[it.s] || 0) + 1; });
            const domSubj = Object.keys(bySubjN).sort((a, b) => bySubjN[b] - bySubjN[a])[0] || 'outro';
            const rawSecs = s.startedAt ? Math.max(1, Math.round((Date.now() - s.startedAt) / 1000)) : 0;
            const secs = Math.min(rawSecs, s.items.length * 180); // ignora tempo ocioso (app aberta e esquecida)
            if (!Array.isArray(state.sessionLog)) state.sessionLog = [];
            state.sessionLog.push({ d: todayStr(), hm: new Date().toTimeString().slice(0, 5), s: domSubj, n: s.items.length, ok: s.correct || 0, secs });
            if (state.sessionLog.length > 150) state.sessionLog.shift();
            // Backup IMEDIATO (2.5s) — o debounce de 30s perdia o backup se
            // a app fosse fechada logo a seguir ao teste (visto nos dados
            // reais: filhas fizeram testes e a nuvem ficou desatualizada).
            try {
                const bp = activeProfile();
                if (bp && bp.userCode && typeof _doBackupPush === 'function') {
                    setTimeout(() => _doBackupPush(bp.userCode).catch(() => {}), 2500);
                }
            } catch {}
        }
    } catch (e) { console.warn('[sessionLog]', e); }
    let newBadges = [];
    // === STREAK (Ofensiva) ===
    // Conta QUALQUER sessão de exercícios (não só desafio diário).
    // Tolera 1 dia de folga (gap até 2).
    // Para gap >= 3 (streak partiria): ainda há 1 ESCUDO por mês — se houver
    // escudo disponível, salva a streak silenciosamente e mostra celebracao.
    const today = todayStr();
    const prevStreak = state.streak.days;
    const lastDate = state.streak.lastDate;
    let streakJustIncreased = false;
    let streakReset = false;
    let streakSaved = false; // escudo usado para salvar a streak
    if (lastDate !== today) {
        const gap = daysBetween(lastDate, today);
        if (gap >= 1 && gap <= 2) {
            // Continuou: gap=1 (jogou ontem) ou gap=2 (1 dia de folga, ainda dentro)
            state.streak.days += 1;
            streakJustIncreased = true;
        } else {
            // gap >= 3 — streak normalmente partia. Se houver escudo disponivel
            // (nunca usado ou usado ha 30+ dias), salva-a.
            const lastShield = state.streak.lastShield;
            const shieldDays = lastShield ? daysBetween(lastShield, today) : null;
            const canSave = state.streak.days > 0 && (shieldDays == null || shieldDays >= 30);
            if (canSave) {
                state.streak.days += 1;
                state.streak.lastShield = today;
                streakJustIncreased = true;
                streakSaved = true;
            } else {
                if (state.streak.days > 0) streakReset = true;
                state.streak.days = 1;
            }
        }
        state.streak.lastDate = today;
        if (state.streak.days > state.streak.best) state.streak.best = state.streak.days;
    }
    if (s.isDaily) {
        const firstToday = !(state.daily && state.daily.date === today && state.daily.completed);
        state.daily = { date: today, completed: true, correct: s.correct };
        // 'Repetir desafio' não volta a contar para as medalhas de consistência
        if (firstToday) {
            state.totalDailies = (state.totalDailies || 0) + 1;
            if (s.correct === s.items.length) state.perfectDailies = (state.perfectDailies || 0) + 1;
        }
    }
    // Notificações visuais ao utilizador
    if (streakSaved) {
        // Escudo usado — celebrar
        if (typeof showToast === 'function') showToast(`🛡️ Escudo usado! Ofensiva de ${state.streak.days} dias salva.`);
        setTimeout(() => { try { _flashStreakChip(); } catch(_) {} }, 200);
    } else if (streakJustIncreased && state.streak.days >= 2) {
        const milestoneMap = { 3: '🔥 3 dias seguidos!', 7: '🏆 1 semana inteira!', 14: '⭐ 2 semanas!', 30: '👑 1 mês completo!', 60: '💎 2 meses!', 100: '🌟 100 dias!' };
        const ms = milestoneMap[state.streak.days];
        if (ms) showToast(ms);
        else if (typeof showToast === 'function') showToast(`🔥 ${state.streak.days} dias seguidos!`);
        // Animação visual no chip
        setTimeout(() => { try { _flashStreakChip(); } catch(_) {} }, 200);
    } else if (streakReset && prevStreak >= 3) {
        // Aviso amistoso quando perdeu uma streak grande
        if (typeof showToast === 'function') showToast(`💪 Recomeçaste a tua ofensiva! (anterior: ${prevStreak} dias)`);
    }
    BADGES.forEach(b => {
        if (!state.badges.includes(b.id) && b.check(state)) {
            state.badges.push(b.id);
            newBadges.push(b);
        }
    });
    // Verificar prémios desbloqueados (ainda não reclamados e sem unlockedAt)
    const newlyUnlocked = (state.rewards || []).filter(r => !r.claimed && !r.unlockedAt && state.xp >= r.cost);
    newlyUnlocked.forEach(r => { r.unlockedAt = todayStr(); });
    saveState();
    showSummary(s, newBadges, newlyUnlocked, streakJustIncreased);
}

function showSummary(s, newBadges, newRewards, streakIncreased) {
    try { _holidayMarkDoneIfApplicable(s); } catch {}
    document.getElementById('exercise-screen').style.display = 'none';
    document.getElementById('summary-screen').style.display = 'flex';
    const total = s.items.length;
    const acc = total ? Math.round(s.correct / total * 100) : 0;

    // Tier por desempenho
    let title, emoji, tier;
    if (acc === 100)      { title = 'Perfeito!';     emoji = '🏆'; tier = 'tier-perfect'; }
    else if (acc >= 80)   { title = 'Excelente!';    emoji = '🌟'; tier = 'tier-great'; }
    else if (acc >= 50)   { title = 'Quase lá!';     emoji = '💪'; tier = 'tier-ok'; }
    else                  { title = 'Treina mais!';  emoji = '🌱'; tier = 'tier-low'; }

    // Sub-label do hero
    const subLabel = s.isDaily ? 'Desafio diário' : (s.testId ? 'Treino para teste' : 'Sessão de treino');

    // Hero
    const hero = document.getElementById('summary-hero');
    hero.classList.remove('tier-perfect','tier-great','tier-ok','tier-low');
    hero.classList.add(tier);
    // Mascote Pip no lugar do emoji — reage ao desempenho
    const emojiEl = document.getElementById('summary-emoji');
    if (window.Mascot && emojiEl) {
        emojiEl.textContent = '';
        emojiEl.style.display = 'flex';
        emojiEl.style.justifyContent = 'center';
        try {
            const _ph = acc >= 80 ? [{ text: `Boa! Acertaste ${s.correct} em ${total}!`, lang: 'pt-PT' }, { text: 'Excellent work!', lang: 'en-US' }]
                       : acc >= 50 ? [{ text: 'Quase lá! Continua a treinar.', lang: 'pt-PT' }]
                       : [{ text: 'Não faz mal. Vamos tentar outra vez!', lang: 'pt-PT' }];
            const m = window.Mascot.create(emojiEl, { size: 72, avatarHtml: _mascotAvatarHtml(66), talkOnTap: true, phrases: _ph });
            setTimeout(() => { try { m && m.react(acc >= 50 ? (acc >= 80 ? 'cheer' : 'happy') : 'sad'); } catch {} }, 350);
        } catch { emojiEl.textContent = emoji; }
    } else if (emojiEl) {
        emojiEl.textContent = emoji;
    }
    document.getElementById('summary-sub').textContent = subLabel;
    document.getElementById('summary-title').textContent = title;
    document.getElementById('sum-correct').textContent = `${s.correct}/${total}`;
    document.getElementById('sum-xp').textContent = '+' + s.xp;
    // Estrelas (1-3) baseadas em accuracy. < 50% fica sem estrelas (vai treinar).
    const starsEl = document.getElementById('summary-stars');
    if (starsEl) {
        let n = 0;
        if (acc >= 90) n = 3;
        else if (acc >= 70) n = 2;
        else if (acc >= 50) n = 1;
        starsEl.innerHTML = '';
        for (let i = 0; i < 3; i++) {
            const span = document.createElement('span');
            span.className = 'summary-star' + (i < n ? ' summary-star-on' : ' summary-star-off');
            span.textContent = '⭐';
            span.style.animationDelay = (i * 0.2 + 0.4) + 's';
            starsEl.appendChild(span);
        }
    }
    // Anima o número da accuracy
    _animateNumber(document.getElementById('sum-accuracy'), 0, acc, 900, v => v + '%');

    // Sons
    if (acc === 100) playPerfectSound();
    else if (acc >= 80) playVictorySound();
    if (streakIncreased) setTimeout(playStreakSound, 600);
    if (newBadges && newBadges.length > 0) setTimeout(playBadgeSound, acc === 100 ? 900 : 500);
    if (newRewards && newRewards.length > 0) setTimeout(playRewardSound, 1400);

    // Confetti se >= 80% (e celebração maior se 100%)
    if (acc >= 80) { _launchConfetti(acc === 100 ? 'big' : 'normal'); _haptic('win'); }

    // === Celebrações extra (v315) ===
    // Lição do curso concluída — revela coroas ganhas + garante festa
    if (s.courseLesson) {
        const cs = state.coursePath?.[s.courseLesson.subjectKey]?.lessons?.[s.courseLesson.lessonId];
        const crown = cs?.crown || 0;
        if (crown >= 1 && acc < 80) _launchConfetti('normal');
        if (crown >= 1) setTimeout(() => _popCelebration('👑', 'Lição completa!', '<span class="pop-crowns">' + '★'.repeat(crown) + '☆'.repeat(3 - crown) + '</span>'), 450);
    }
    // Marco de ofensiva (streak)
    const _streakMilestones = [3, 7, 14, 30, 50, 100, 365];
    if (streakIncreased && _streakMilestones.includes(state.streak?.days)) {
        setTimeout(() => { fireConfetti({ count: 180, duration: 2800 }); _popCelebration('🔥', `${state.streak.days} dias seguidos!`, 'Ofensiva imparável'); }, 500);
    }
    // Badge desbloqueado
    if (newBadges && newBadges.length > 0) {
        setTimeout(() => fireConfetti({ count: 120 }), 700);
    }

    // Cards informativos abaixo do hero
    const info = document.getElementById('summary-info-cards');
    const cards = [];
    if (s.testId) {
        const t = state.tests.find(x => x.id === s.testId);
        const sub = t ? SUBJECTS[t.subject] : null;
        if (sub) cards.push(_summaryCard('fa-graduation-cap', sub.color, 'TESTE', sub.fullName || sub.name));
    } else if (s.subject) {
        const sub = SUBJECTS[s.subject];
        if (sub) cards.push(_summaryCard('fa-' + (sub.icon || '').replace(/^fa-/, ''), sub.color, 'DISCIPLINA', sub.fullName || sub.name));
    }
    if (s.isDaily && state.streak && state.streak.days > 0) {
        cards.push(_summaryCard('fa-fire', '#f97316', 'SEQUÊNCIA', `${state.streak.days} dia${state.streak.days === 1 ? '' : 's'} seguido${state.streak.days === 1 ? '' : 's'}`));
    }
    cards.push(_summaryCard('fa-bolt', '#facc15', 'XP TOTAL', `${state.xp} pontos`));
    info.innerHTML = cards.join('');

    // Badges/prémios
    const bdg = document.getElementById('summary-badges');
    const badgeChips = newBadges.map(b => `<div class="summary-badge-chip">${b.icon} ${b.name}</div>`).join('');
    const rewardChips = (newRewards || []).map(r => `<div class="summary-badge-chip" style="background:linear-gradient(135deg,#fef9c3,#fde047);border-color:#eab308">🎁 ${r.name}</div>`).join('');
    bdg.innerHTML = badgeChips + rewardChips;

    // Botão repetir perguntas erradas
    // Usa s.correct como fonte de verdade para evitar inconsistência visual
    const wrongCount = total - s.correct;
    const retryWrap = document.getElementById('summary-retry-wrap');
    if (retryWrap) {
        if (wrongCount > 0 && s.correct < total) {
            retryWrap.innerHTML = `<button class="btn btn-block" onclick="retryWrongSession()" style="background:linear-gradient(135deg,#f59e0b,#d97706);color:#fff;font-weight:700;margin-bottom:10px;border:none;padding:14px"><i class="fas fa-rotate-left"></i> Repetir perguntas erradas (${wrongCount})</button>`;
        } else {
            retryWrap.innerHTML = '';
        }
    }

    // Botão "Mais um ciclo!" — em sessões de treino normais OU retry (apos
    // corrigir as erradas, vir o convite para fazer outra ronda).
    const newCycleWrap = document.getElementById('summary-newcycle-wrap');
    if (newCycleWrap) {
        if (!s.isDaily && !s.testId && !s.isDuel && !s.isMax && s.subject) {
            const label = s._isRetry ? 'Iniciar novo ciclo' : 'Mais um ciclo!';
            newCycleWrap.innerHTML = `<button class="btn btn-block" onclick="startNewCycle()" style="background:linear-gradient(135deg,#f472b6,#db2777);color:#fff;font-weight:700;padding:14px;margin-bottom:10px;border:none"><i class="fas fa-rotate-right"></i> ${label}</button>`;
        } else {
            newCycleWrap.innerHTML = '';
        }
    }

    // Modal de prémio desbloqueado
    if (newRewards && newRewards.length > 0) {
        pendingRewardId = newRewards[0].id;
        setTimeout(() => {
            document.getElementById('reward-unlocked-name').textContent = newRewards[0].name;
            document.getElementById('reward-modal').style.display = 'flex';
        }, 800);
    }

    // Guarda dados para a partilha
    _lastSummary = { s, acc, total, title, subLabel };
}

// Card "ícone circular + label/value"
function _summaryCard(icon, color, label, value) {
    const c = color || '#f472b6';
    // bg suave a partir da cor (12% opacidade)
    const bg = c + '22';
    return `<div class="summary-info-card">
        <div class="summary-info-icon" style="background:${bg};color:${c}"><i class="fas ${icon}"></i></div>
        <div class="summary-info-body">
            <div class="summary-info-label">${label}</div>
            <div class="summary-info-value">${value}</div>
        </div>
    </div>`;
}

// Anima um número de start até end no DOM
function _animateNumber(el, start, end, durationMs, fmt) {
    if (!el) return;
    const t0 = performance.now();
    fmt = fmt || (v => String(v));
    const step = (now) => {
        const p = Math.min(1, (now - t0) / durationMs);
        const eased = 1 - Math.pow(1 - p, 3); // easeOutCubic
        const v = Math.round(start + (end - start) * eased);
        el.textContent = fmt(v);
        if (p < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
}

// Confetti em canvas — sem libs
// Confetti full-screen independente — funciona em qualquer ecrã/overlay
// (inclui o escape room). Cria o seu proprio canvas e remove-o no fim.
function fireConfetti(opts) {
    opts = opts || {};
    const count = opts.count || 130;
    const duration = opts.duration || 2400;
    const colors = opts.colors || ['#f59e0b','#ef4444','#f472b6','#a78bfa','#22d3ee','#10b981','#facc15'];
    const canvas = document.createElement('canvas');
    canvas.style.cssText = 'position:fixed;inset:0;width:100vw;height:100vh;pointer-events:none;z-index:99999';
    document.body.appendChild(canvas);
    const ctx = canvas.getContext('2d');
    const dpr = window.devicePixelRatio || 1;
    function resize() { canvas.width = innerWidth * dpr; canvas.height = innerHeight * dpr; ctx.setTransform(dpr, 0, 0, dpr, 0, 0); }
    resize();
    const ox = opts.x != null ? opts.x : innerWidth / 2;
    const oy = opts.y != null ? opts.y : innerHeight * 0.32;
    const parts = [];
    for (let i = 0; i < count; i++) {
        const ang = Math.random() * Math.PI * 2;
        const sp = Math.random() * 7 + 3;
        parts.push({
            x: ox, y: oy,
            vx: Math.cos(ang) * sp,
            vy: Math.sin(ang) * sp - Math.random() * 5,
            size: Math.random() * 7 + 4,
            color: colors[Math.floor(Math.random() * colors.length)],
            rot: Math.random() * Math.PI,
            vr: (Math.random() - 0.5) * 0.35,
            circle: Math.random() < 0.4
        });
    }
    const start = performance.now();
    function frame(now) {
        const t = now - start;
        ctx.clearRect(0, 0, innerWidth, innerHeight);
        const alpha = Math.max(0, 1 - t / duration);
        parts.forEach(p => {
            p.vy += 0.16; p.vx *= 0.99;
            p.x += p.vx; p.y += p.vy; p.rot += p.vr;
            ctx.save();
            ctx.globalAlpha = alpha;
            ctx.translate(p.x, p.y);
            ctx.rotate(p.rot);
            ctx.fillStyle = p.color;
            if (p.circle) { ctx.beginPath(); ctx.arc(0, 0, p.size / 2, 0, Math.PI * 2); ctx.fill(); }
            else ctx.fillRect(-p.size / 2, -p.size / 3, p.size, p.size * 0.66);
            ctx.restore();
        });
        if (t < duration) requestAnimationFrame(frame);
        else canvas.remove();
    }
    requestAnimationFrame(frame);
}
window.fireConfetti = fireConfetti;

// Pop de celebração central — cartão com emoji + título que faz bounce e
// desaparece sozinho. Reutilizável para qualquer "win" (coroas, streak…).
function _popCelebration(emoji, title, subtitleHtml) {
    const el = document.createElement('div');
    el.className = 'pop-celebrate';
    el.innerHTML = `<div class="pop-celebrate-card">
        <div class="pop-celebrate-emoji">${emoji}</div>
        <div class="pop-celebrate-title">${escapeHtml(title)}</div>
        <div class="pop-celebrate-sub">${subtitleHtml || ''}</div>
    </div>`;
    document.body.appendChild(el);
    requestAnimationFrame(() => el.classList.add('show'));
    setTimeout(() => { el.classList.remove('show'); setTimeout(() => el.remove(), 400); }, 1700);
}
window._popCelebration = _popCelebration;

// Haptic feedback (Android + alguns browsers). Silencioso onde nao suportado.
function _haptic(kind) {
    if (!('vibrate' in navigator)) return;
    try {
        if (kind === 'ok') navigator.vibrate(18);
        else if (kind === 'wrong') navigator.vibrate([30, 40, 30]);
        else if (kind === 'win') navigator.vibrate([20, 30, 20, 30, 60]);
        else navigator.vibrate(15);
    } catch {}
}
window._haptic = _haptic;

function _launchConfetti(intensity) {
    const canvas = document.getElementById('summary-confetti');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const W = canvas.width = canvas.clientWidth * (window.devicePixelRatio || 1);
    const H = canvas.height = canvas.clientHeight * (window.devicePixelRatio || 1);
    ctx.scale(window.devicePixelRatio || 1, window.devicePixelRatio || 1);
    const colors = ['#f59e0b','#ef4444','#f472b6','#f472b6','#3b82f6','#10b981','#facc15'];
    const count = intensity === 'big' ? 140 : 80;
    const parts = [];
    for (let i = 0; i < count; i++) {
        parts.push({
            x: (canvas.clientWidth/2) + (Math.random() - 0.5) * canvas.clientWidth * 0.3,
            y: -20 - Math.random() * 60,
            vx: (Math.random() - 0.5) * 5,
            vy: 2 + Math.random() * 4,
            size: 6 + Math.random() * 8,
            color: colors[Math.floor(Math.random() * colors.length)],
            angle: Math.random() * Math.PI * 2,
            spin: (Math.random() - 0.5) * 0.3,
            life: 0
        });
    }
    let frames = 0;
    const maxFrames = 220;
    function loop() {
        frames++;
        ctx.clearRect(0, 0, canvas.clientWidth, canvas.clientHeight);
        parts.forEach(p => {
            p.vy += 0.12; // gravidade
            p.x += p.vx;
            p.y += p.vy;
            p.angle += p.spin;
            p.life++;
            ctx.save();
            ctx.translate(p.x, p.y);
            ctx.rotate(p.angle);
            ctx.fillStyle = p.color;
            ctx.globalAlpha = Math.max(0, 1 - frames / maxFrames);
            ctx.fillRect(-p.size/2, -p.size/4, p.size, p.size/2);
            ctx.restore();
        });
        if (frames < maxFrames) requestAnimationFrame(loop);
        else ctx.clearRect(0, 0, canvas.clientWidth, canvas.clientHeight);
    }
    requestAnimationFrame(loop);
}

// Partilha do resultado da sessão
let _lastSummary = null;
async function shareSummary() {
    if (!_lastSummary) return;
    const { s, acc, total, title, subLabel } = _lastSummary;
    const lines = [];
    lines.push(`🏆 ${title} — ${acc}% de precisão`);
    lines.push('');
    lines.push(`📚 ${subLabel}`);
    lines.push(`🎯 ${s.correct}/${total} certas`);
    lines.push(`⭐ +${s.xp} XP`);
    if (s.isDaily && state.streak?.days > 0) lines.push(`🔥 Sequência: ${state.streak.days} dia(s)`);
    lines.push('');
    lines.push(`— EscolaPlay`);
    const text = lines.join('\n');
    if (navigator.share) {
        try { await navigator.share({ title: 'O meu resultado no EscolaPlay', text }); return; }
        catch (err) { if (err && err.name === 'AbortError') return; }
    }
    try {
        await navigator.clipboard.writeText(text);
        showToast('📋 Resultado copiado!');
    } catch {
        showToast('Não foi possível partilhar.');
    }
}

function closeSummary() {
    document.getElementById('summary-screen').style.display = 'none';
    currentSession = null;
    updateAll();
    switchTab('home');
}

// Inicia novo ciclo com o mesmo tópico/disciplina (bypassa verificação de "tudo visto")
function startNewCycle() {
    const s = currentSession;
    if (!s || !s.subject) { closeSummary(); return; }
    const key = s.subject;
    const topicSet = s.topicSet || activeTopicsFor(key);
    const pool = allExercisesFor(key, topicSet);
    if (pool.length === 0) { closeSummary(); return; }
    const items = pickExercises(pool, Math.min(getPracticeQuestions(), pool.length));
    document.getElementById('summary-screen').style.display = 'none';
    currentSession = { items, idx: 0, correct: 0, wrong: 0, xp: 0, streak: 0, isDaily: false, subject: key, topicSet, startedAt: Date.now() };
    openExerciseScreen();
    renderQuestion();
}

// Inicia uma mini-sessão só com as perguntas que o aluno errou
function retryWrongSession() {
    const s = currentSession;
    if (!s) return;
    const wrongItems = s.items.filter((_, i) => s.results && s.results[i] === false);
    if (!wrongItems.length) {
        // Não há erros reais em s.results — botão não devia aparecer; volta ao início
        showToast('Afinal não há perguntas erradas! 🎉', 'success');
        setTimeout(closeSummary, 1200);
        return;
    }
    document.getElementById('summary-screen').style.display = 'none';
    currentSession = {
        items:   wrongItems,
        idx:     0,
        correct: 0,
        wrong:   0,
        xp:      0,
        streak:  0,
        startedAt: Date.now(),
        results: [],
        isDaily: false,
        testId:  null,
        _isRetry: true,
        subject: s.subject,    // preserva para "Mais um ciclo" funcionar
        topicSet: s.topicSet
    };
    document.getElementById('exercise-screen').style.display = 'flex';
    renderQuestion();
}

function claimCurrentReward() {
    if (pendingRewardId) claimReward(pendingRewardId);
    closeRewardModal();
}
function closeRewardModal() {
    document.getElementById('reward-modal').style.display = 'none';
    pendingRewardId = null;
}

// ============================================================
// ============== DUELOS — desafiar amigos via URL =============
// ============================================================
// Sem backend: a URL transporta { perguntas, score do criador, tempo }.
// O amigo abre o link, faz as MESMAS perguntas com cronómetro, vê
// comparação no fim, e pode enviar o seu resultado de volta via outro
// link. Sistema viral estilo Wordle.

// ----- helpers de codificação base64 URL-safe -----
function _b64UrlEncode(str) {
    return btoa(unescape(encodeURIComponent(str)))
        .replace(/=+$/, '')
        .replace(/\+/g, '-')
        .replace(/\//g, '_');
}
function _b64UrlDecode(s) {
    let b64 = s.replace(/-/g, '+').replace(/_/g, '/');
    const pad = b64.length % 4;
    if (pad) b64 += '='.repeat(4 - pad);
    return decodeURIComponent(escape(atob(b64)));
}
function encodeDuel(obj) {
    try { return _b64UrlEncode(JSON.stringify(obj)); } catch (_) { return ''; }
}
function decodeDuel(s) {
    try { return JSON.parse(_b64UrlDecode(s)); } catch (_) { return null; }
}

// ----- procura exercício por id em qualquer ano carregado -----
function _findExerciseAnyYear(id) {
    if (!id) return null;
    // Tenta no ano ativo primeiro
    if (Array.isArray(EXERCISES)) {
        const e = EXERCISES.find(x => x && x.id === id);
        if (e) return e;
    }
    // Procura em todos os anos disponíveis
    if (window.EXERCISES_BY_YEAR) {
        for (const yr of Object.keys(window.EXERCISES_BY_YEAR)) {
            const arr = window.EXERCISES_BY_YEAR[yr];
            if (Array.isArray(arr)) {
                const e = arr.find(x => x && x.id === id);
                if (e) return e;
            }
        }
    }
    // MAX exercises do estado
    if (state && Array.isArray(state.maxExercises)) {
        const e = state.maxExercises.find(x => x && x.id === id);
        if (e) return e;
    }
    return null;
}

// ----- formatação do tempo -----
function _formatDuelTime(ms) {
    const n = Number(ms);
    const safe = Number.isFinite(n) ? n : 0;
    const sec = Math.max(0, Math.floor(safe / 1000));
    const m = Math.floor(sec / 60);
    const s = sec % 60;
    return m > 0 ? `${m}:${String(s).padStart(2,'0')}` : `${s}s`;
}

// ----- pontuação de duelo -----
// 100 pontos por certa + bónus por velocidade (5 pontos por seg restante)
function _duelScore(correct, timeUsedSec, timeLimitSec) {
    const c = Number(correct) || 0;
    const used = Number(timeUsedSec);
    const limit = Number(timeLimitSec);
    const baseScore = c * 100;
    const speedBonus = Number.isFinite(used) && Number.isFinite(limit)
        ? Math.max(0, Math.floor((limit - used) * 5))
        : 0;
    return baseScore + speedBonus;
}

async function _shareDuelUrl(url, data) {
    const sub = SUBJECTS[ data.q && _findExerciseAnyYear(data.q[0])?.s ];
    const subName = sub?.name || 'EscolaPlay';
    const text =
`🥊 ${data.c} desafia-te no EscolaPlay!

${subName} · ${data.q.length} perguntas
${Number(data.sb) || 0}/${data.q.length} certas em ${_formatDuelTime(data.st * 1000)}

📲 Como aceitar:
1. Abre a app EscolaPlay no telemóvel
2. No início, toca em "🥊 Tens um duelo?"
3. Cola este link

${url}

(Se não tiveres a app, o link funciona também no browser.)`;
    if (navigator.share) {
        try { await navigator.share({ title: '🥊 Duelo no EscolaPlay', text }); return; }
        catch (err) { if (err && err.name === 'AbortError') return; }
    }
    try { await navigator.clipboard.writeText(text); showToast('🔗 Link de duelo copiado!'); }
    catch { prompt('Copia este link e envia ao teu amigo:', url); }
}

// ============================================================
// DUELOS via FIRESTORE (v266+)
// ============================================================
// Schema: duels/{duelId}: { v, createdAt, creator:{name,avatar,year},
//   questions:[ids], mode:'open', responses:{ [name]: {...} } }

function _fbReady() { return !!(window.__fb && window.__fb.db); }
// Nome → chave de campo Firestore segura (sem . ~ * / [ ]) — 'Sr. João' criava
// um caminho aninhado e a resposta nunca era encontrada.
function _duelRespKey(name) { return String(name || 'Anónimo').replace(/[.~*\/\[\]]/g, '_').slice(0, 60); }
function _onFbReady() {
    if (_fbReady()) return Promise.resolve();
    // v571: o SDK só se carrega quando algo o pede (duelos/backup/admin).
    try { if (typeof window._initFirebase === 'function') window._initFirebase(); } catch {}
    // Timeout de 10s: sem isto, se o Firebase não carregar (rede/adblocker),
    // todos os fbCreateDuel/fbSubmitDuelResult ficavam pendurados para sempre
    // e o utilizador via "A criar duelo…" eternamente, sem feedback.
    return new Promise((resolve, reject) => {
        const cleanup = () => { try { window.removeEventListener('fbready', onReady); window.removeEventListener('fbfail', onFail); } catch {} clearTimeout(to); };
        const onReady = () => { cleanup(); resolve(); };
        const onFail = () => { cleanup(); reject(new Error('Firebase não disponível (verifica ligação ou bloqueador).')); };
        window.addEventListener('fbfail', onFail, { once: true });
        const to = setTimeout(() => {
            cleanup();
            reject(new Error('Firebase não disponível (verifica ligação ou bloqueador).'));
        }, 10000);
        window.addEventListener('fbready', onReady, { once: true });
    });
}
function _genDuelId() {
    // ID curto memoravel — 8 chars alfanum (sem 0/O/I/1 para evitar confusao)
    const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    let s = '';
    for (let i = 0; i < 8; i++) s += alphabet[Math.floor(Math.random() * alphabet.length)];
    return s;
}

async function fbCreateDuel({ subjectKey, questionIds, name, avatar, year, timeLimit, inviteFor, creatorCode }) {
    await _onFbReady();
    const { db, doc, setDoc, serverTimestamp } = window.__fb;
    // Gera id e tenta ate nao colidir (probabilidade ridicula em 32^8=1.1e12)
    let id, tries = 0;
    while (tries < 4) {
        id = _genDuelId();
        const ref = doc(db, 'duels', id);
        const { getDoc } = window.__fb;
        const snap = await getDoc(ref);
        if (!snap.exists()) break;
        tries++;
    }
    if (tries >= 4) throw new Error('Não foi possível gerar um ID único para o duelo — tenta outra vez.');
    const ref = doc(db, 'duels', id);
    await setDoc(ref, {
        v: 1,
        createdAt: serverTimestamp(),
        mode: 'open',
        subject: subjectKey || null,
        creator: { name: name || 'Anónimo', avatar: _pubAvatar(avatar), year: year || 0, code: creatorCode || null },
        questions: questionIds,
        timeLimit: timeLimit || Math.max(60, questionIds.length * 20),
        inviteFor: Array.isArray(inviteFor) ? inviteFor : [],
        responses: {}
    });
    return id;
}

async function fbGetDuel(id) {
    await _onFbReady();
    const { db, doc, getDoc } = window.__fb;
    const ref = doc(db, 'duels', id);
    const snap = await getDoc(ref);
    return snap.exists() ? Object.assign({ id }, snap.data()) : null;
}

async function fbDeleteDuel(id) {
    await _onFbReady();
    const { db, doc } = window.__fb;
    const { deleteDoc } = await _fbQueryFns();
    await deleteDoc(doc(db, 'duels', id));
}

async function deleteMyDuel(id) {
    if (!confirm('Apagar este duelo? Não vai aparecer mais nem para ti nem para os amigos.')) return;
    try {
        await fbDeleteDuel(id);
    } catch (err) {
        console.error('[duel] delete fail', err);
        showToast('❌ Erro: ' + (err?.message || err));
        // Pode ser que rule Firestore ainda esteja em allow delete: if false
        if (err?.code === 'permission-denied' || /permission/i.test(err?.message || '')) {
            showToast('Não foi possível apagar o duelo agora.');
        }
        return;
    }
    // Remove do local + apaga listener
    if (state.myDuels) state.myDuels = state.myDuels.filter(d => d.id !== id);
    if (_duelListeners[id]) { try { _duelListeners[id](); } catch {} delete _duelListeners[id]; }
    saveState();
    showToast('🗑️ Duelo apagado.');
    if (document.getElementById('my-duels-modal-temp')) openMyDuelsScreen();
}
window.deleteMyDuel = deleteMyDuel;

async function fbSubmitDuelResult(id, playerName, result) {
    await _onFbReady();
    const { db, doc, updateDoc } = window.__fb;
    const ref = doc(db, 'duels', id);
    // result = { correct, time, score, items, completedAt }
    const path = `responses.${_duelRespKey(playerName)}`;
    try { if (result && typeof result === 'object' && !result.name) result.name = String(playerName || '').slice(0, 40); } catch {}
    await updateDoc(ref, { [path]: result });
}

// Single-use por dispositivo (state.duelsPlayed[id] = {at, score, ...})
function _markDuelPlayed(id, payload) {
    if (!state.duelsPlayed) state.duelsPlayed = {};
    state.duelsPlayed[id] = Object.assign({ at: Date.now() }, payload);
    saveState();
}
function _hasDuelPlayed(id) {
    return !!(state.duelsPlayed && state.duelsPlayed[id]);
}

// ===== CRIAR DUELO direto da disciplina (mode='open' — sem score) =====
async function createDuelFromSubject(subjectKey, opts = {}) {
    const p = activeProfile();
    if (!p) { showToast('Cria primeiro um perfil.'); return; }
    let topicSet;
    if (opts.useSelection && selectedTopicsForMax.size > 0) topicSet = new Set(selectedTopicsForMax);
    else topicSet = activeTopicsFor(subjectKey);
    const pool = allExercisesFor(subjectKey, topicSet);
    if (pool.length === 0) { showToast('Sem exercícios para gerar duelo.'); return; }
    const count = Math.min(getPracticeQuestions(), pool.length);
    const items = pickExercises(pool, count);
    const questionIds = items.map(e => e.id);
    showToast('A criar duelo…');
    try {
        // Garante userCode (e regista perfil) antes de criar
        const myCode = await ensureUserCode();
        const id = await fbCreateDuel({
            subjectKey,
            questionIds,
            name: p.name,
            avatar: _pubAvatar(p.avatar),
            year: p.year,
            inviteFor: opts.inviteFor || [],
            creatorCode: myCode || null
        });
        _trackMyDuel(id, subjectKey, count);
        if (opts.inviteFor && opts.inviteFor.length > 0) {
            const names = opts.inviteNames || opts.inviteFor;
            const namesStr = names.length === 1 ? names[0] : `${names.length} amigos`;
            showToast(`✅ Duelo enviado para ${namesStr}!`);
            // Convidar criador a jogar tambem
            setTimeout(() => _promptCreatorPlay(id, namesStr), 700);
        } else {
            showToast('✅ Duelo criado.');
            setTimeout(() => _promptCreatorPlay(id, 'os teus amigos'), 700);
        }
    } catch (err) {
        console.error('[duel] create failed', err);
        showToast('❌ Erro ao criar duelo. Verifica a ligação.');
    }
}

// Guarda no perfil os duelos que criei (para historico e listeners)
function _trackMyDuel(id, subjectKey, qCount) {
    if (!state.myDuels) state.myDuels = [];
    // Evita duplicados
    if (state.myDuels.some(d => d.id === id)) return;
    state.myDuels.unshift({
        id, subject: subjectKey, qCount,
        createdAt: Date.now(),
        lastSeenResponses: 0
    });
    // Trim a 50 duelos
    if (state.myDuels.length > 50) state.myDuels = state.myDuels.slice(0, 50);
    saveState();
    // Comecar a ouvir
    _attachDuelListener(state.myDuels[0]);
}

// Listeners ativos (id -> unsubscribe fn)
const _duelListeners = {};

function _attachDuelListener(entry) {
    if (!entry || !entry.id) return;
    if (_duelListeners[entry.id]) return;
    _duelListeners[entry.id] = () => {}; // pendente — evita 2 onSnapshot no mesmo doc
    _onFbReady().then(() => {
        const { db, doc, onSnapshot } = window.__fb;
        const ref = doc(db, 'duels', entry.id);
        const unsub = onSnapshot(ref, snap => {
            if (!snap.exists()) return;
            const data = snap.data();
            const respNames = Object.keys(data.responses || {});
            const p = activeProfile();
            const myName = p?.name;
            // Excluir as proprias respostas
            const othersNames = respNames.filter(n => n !== _duelRespKey(myName) && n !== myName);
            const cur = othersNames.length;
            const prev = entry.lastSeenResponses || 0;
            if (cur > prev) {
                // Novidade!
                const newOnes = othersNames.slice(prev);
                const last = newOnes[newOnes.length - 1];
                const lastResp = data.responses[last];
                const sub = SUBJECTS[entry.subject]?.name || 'EscolaPlay';
                showToast(`🥊 ${last} respondeu! ${lastResp.correct||0}/${data.questions.length} · ${lastResp.score||0}pts (${sub})`);
                entry.lastSeenResponses = cur;
                entry.lastResponseAt = Date.now();
                saveState();
                _updateDuelsBadge();
            }
        }, err => {
            console.warn('[duel] listener err for', entry.id, err);
        });
        _duelListeners[entry.id] = unsub;
    }).catch(err => {
        // Com o novo timeout em _onFbReady, este .catch evita o
        // "Uncaught promise rejection" na consola quando o Firebase
        // não carrega (offline, bloqueador, sem chave fb).
        console.warn('[duel] listener attach skipped:', err.message);
    });
}

function _attachAllDuelListeners() {
    if (!state.myDuels) return;
    for (const d of state.myDuels) _attachDuelListener(d);
    _updateDuelsBadge();
}

function _updateDuelsBadge() {
    const el = document.getElementById('my-duels-badge');
    if (!el) return;
    const total = (state.myDuels || []).reduce((s, d) => s + (d.lastSeenResponses || 0), 0);
    if (total > 0) {
        el.textContent = String(total);
        el.style.display = 'inline-flex';
    } else {
        el.style.display = 'none';
    }
}
window._updateDuelsBadge = _updateDuelsBadge;

// ===== ECRA "Os meus duelos" =====
