    const xp = document.getElementById('xp-bar-fill');      if (xp) xp.style.width = '0%';
    // Substituir o conteúdo do tab ativo por uma chamada à ação
    document.querySelectorAll('.tab-content').forEach(t => t.classList.remove('active'));
