// Preview de uma voz PT específica SEM mudar a escolha guardada — útil para
// testar Raquel/Duarte/Fernanda no picker antes de escolher.
async function previewPTVoice(sel) {
    if (!sel) return;
    const sep = sel.indexOf(':');
    const eng = sep > 0 ? sel.slice(0, sep) : 'edge';
    const vname = sep > 0 ? sel.slice(sep + 1) : sel;
    const text = 'Olá! Vamos praticar juntos. Estás pronto?';
    // iOS: usar proxy se disponível, senão voz do sistema. Ver ttsSpeak.
    if (isIOSDevice()) {
        if (state.ttsProxyUrl && eng === 'edge') {
            try { _primeTtsAudio(); } catch {}
            try { _stopCurrentAudio(); } catch {}
            try {
                const b = await _edgeTTSProxy(text, vname, 'pt-PT');
                if (b && _playBlob(b, text, 'pt-PT', {})) { _lastTTSEngine = 'Proxy'; return; }
            } catch {}
        }
        try { _stopCurrentAudio(); } catch {}
        _ttsSpeakSystem(text);
        return;
    }
    // Prime SÍNCRONO no gesto — sem isto o iOS recusa o blob que chega depois.
    try { _stopCurrentAudio(); } catch {}
    try { _primeTtsAudio(); } catch {}
    try {
        if (eng === 'edge') {
            const b = await _edgeTTS(text, vname, 'pt-PT', 6000);
            if (b && _playBlob(b, text, 'pt-PT', {})) { _lastTTSEngine = 'Edge'; return; }
        } else if (eng === 'mistral' && state.max && state.max.mistralKey) {
            const b = await _mistralTTS(text, 'pt', vname);
            if (b && _playBlob(b, text, 'pt-PT', {})) { _lastTTSEngine = 'Mistral'; return; }
        }
    } catch {}
    // Nunca ficar mudo: cair para a voz pt-PT do sistema e avisar porquê.
    showToast('Voz neural indisponível agora — a tocar com a voz do sistema.');
    _ttsSpeakSystem(text);
}
window.choosePTVoice = choosePTVoice;
window.previewPT = previewPT;
window.previewPTVoice = previewPTVoice;
// Descobre as vozes disponíveis na conta Mistral (catálogo da API hospedada)
async function _mistralListVoices() {
    const key = state.max && state.max.mistralKey;
    if (!key) return { error: 'Sem chave Mistral' };
    try {
        const res = await fetch('https://api.mistral.ai/v1/audio/voices', { headers: { 'authorization': `Bearer ${key}` } });
        if (!res.ok) { let d = ''; try { d = (await res.text()).slice(0, 160); } catch {} return { error: res.status + ' ' + d }; }
        const j = await res.json();
        const arr = Array.isArray(j) ? j : (j.data || j.voices || []);
        const ids = arr.map(v => (typeof v === 'string' ? v : (v.id || v.name || v.voice_id))).filter(Boolean);
        return { voices: ids };
    } catch (e) { return { error: String(e && e.message || e) }; }
}
async function _mistralLoadVoices() {
    showToast('A carregar vozes…');
    const r = await _mistralListVoices();
    if (r.voices && r.voices.length) {
        state.mistralVoiceList = r.voices;
        saveState();
        showToast(r.voices.length + ' vozes carregadas');
        openVoicePickerEN();
    } else {
        showToast('Listagem indisponível (' + (r.error || '') + '). Escreve a voz à mão.');
    }
}
